    def _prepare_table(self, table, compact=False):
        """Normalize table readability in views touched by the layout transfer."""
        table.setAlternatingRowColors(True)
        table.setWordWrap(False)
        table.setShowGrid(True)
        try:
            vh = table.verticalHeader()
            vh.setVisible(False)
            vh.setDefaultSectionSize(22 if compact else 26)
            vh.setMinimumSectionSize(20)
        except Exception:
            pass

    # ─── MENUS ─────────────────────────────────────────────────

    def _create_menus(self):
        mb = self.menuBar()
        # Start from a clean menu bar. This prevents any persisted/legacy
        # QAction (especially the old rolling Panels menu) from surviving
        # when the UI is rebuilt.
        try:
            mb.clear()
        except Exception:
            pass

        # File
        fm = mb.addMenu(t('menu_file'))
        act = fm.addAction(t('open_fasta'), self.load_fasta)
        act.setShortcut('Ctrl+O')
        fm.addAction(t('load_hmm'), self.load_hmm)
        # v29.11.3 — quick access to "Load AF3 results directory".  The
        # handler is shared with the button on the AF3 table results tab
        # (self._af3a_load_folder).  After loading we switch to that tab
        # so the user immediately sees the parsed predictions.
        fm.addAction("📂 Load AF3 results directory...",
                     self._load_af3_results_from_menu)
        fm.addSeparator()
        act = fm.addAction(t('save_project'), self.save_project)
        act.setShortcut('Ctrl+S')
        act = fm.addAction('💾 Save Project As (full copy)...', self.save_project_as)
        act.setShortcut('Ctrl+Shift+S')
        act = fm.addAction(t('open_project'), self.load_project)
        act.setShortcut('Ctrl+Shift+O')
        fm.addSeparator()
        fm.addAction(t('save_orfs_fasta'), self.save_fasta)
        fm.addAction(t('save_report_tsv'), self.save_report_tsv)
        fm.addSeparator()
        _fig_act = fm.addAction('📷 Export Figure  (P+S / Ctrl+Shift+P)',
            lambda: self.export_vector_figure(fmt=None, silent=False))
        _fig_act.setShortcut('Ctrl+Shift+P')

        fm.addSeparator()
        act = fm.addAction(t('quit'), self.close)
        act.setShortcut('Ctrl+Q')

        # Parameters
        pm = mb.addMenu(t('menu_params'))
        pm.addAction("🧬 ORF Analysis Parameters...", self._show_orf_params)
        pm.addAction(t('blast_params'), self._show_blast_params)
        pm.addAction(t('hmm_params'), self._show_hmm_params)
        pm.addSeparator()
        pm.addAction("🗺️ Genome Map...", self._show_genome_map_params)
        pm.addAction("🔬 PPI Analysis Plots...", self._show_ppi_plot_params)

        # Export  (v29.11.3 — single entry point for every export method)
        em = mb.addMenu("📤 Export")
        # Genome Map
        em.addAction("🗺️ Genome Map → PDF (vector)...",
                     self.export_map_pdf)
        em.addSeparator()
        # Tables / sequences
        em.addAction("📊 ORF table (TSV)...",
                     lambda: self._export_orf_table(fmt='tsv'))
        em.addAction("📊 ORF table with sequences (TSV)...",
                     lambda: self._export_orf_table(
                         fmt='tsv', include_seqs=True))
        em.addAction("🧬 ORF proteins (FASTA)...",
                     lambda: self._export_orf_fasta(aa=True))
        em.addAction("🧬 ORF DNA (FASTA)...",
                     lambda: self._export_orf_fasta(aa=False))
        em.addAction("📋 Full report (TSV)...",
                     self.save_report_tsv)
        em.addSeparator()
        # PPI Map
        em.addAction("🧬 Genomic PPI Map → SVG...",
                     self._export_ppi_arc_map_svg)
        em.addAction("🧬 PPI arcs → TSV...",
                     self._export_ppi_arc_map_tsv)
        em.addSeparator()
        # PPI Analysis
        em.addAction("🔬 PPI Analysis — current view → SVG...",
                     self._export_ppi_analysis_svg)
        em.addAction("🔬 PPI Analysis — current view → PNG...",
                     self._export_ppi_analysis_png)
        em.addSeparator()
        # AF3 results
        em.addAction("📈 AF3 results table → TSV...",
                     self._export_af3a_tsv)
        em.addAction("📈 AF3 motifs → TSV...",
                     self._export_af3a_motifs_tsv)
        em.addAction("📈 AF3 interface anchor windows → FASTA...",
                     self._export_af3a_anchor_windows)
        em.addSeparator()
        # Whole-window screenshot
        em.addAction("🖼️ Whole window → PDF screenshot (Ctrl+Shift+P)",
                     lambda: self.export_vector_figure(fmt=None, silent=False))

        # Help
        hm = mb.addMenu(t('menu_help'))
        hm.addAction(t('manual'), self._show_manual)
        hm.addAction(t('tutorial'), self._show_tutorial)
        hm.addAction(t('install'), self._show_install)
        hm.addAction("System Check...", self._show_system_check)
        hm.addSeparator()
        hm.addAction("📈 Interaction Results — analysis guide",
                     self._show_help_interaction_results)
        hm.addAction("🧬 Genomic PPI Map — guide",
                     self._show_help_ppi_map)
        hm.addAction("🔬 PPI Analysis — guide",
                     self._show_help_ppi_analysis)
        hm.addSeparator()
        hm.addAction("📚 References && methodology",
                     self._show_help_references)
        hm.addSeparator()
        hm.addAction(t('about'), self._show_about)

        # The former rolling "Panels" menu is deprecated; keep it removed
        # even if older code or saved UI state tries to recreate it.
        self._remove_panels_menu_action()

    # ─── WINDOW MENU (responsive sizing) ──────────────────────

    def _build_window_menu(self):
        """Add a Window menu with size presets, Custom Size dialog,
        Fullscreen toggle, and re-center / reset actions.

        Idempotent: safe to call multiple times — re-uses existing menu.
        """
        mb = self.menuBar()
        # Look for an existing Window menu first
        win_menu = None
        for act in mb.actions():
            if act.text() in ('&Window', 'Window'):
                win_menu = act.menu()
                break
        if win_menu is None:
            win_menu = mb.addMenu("&Window")
        else:
            win_menu.clear()

        # Quick presets
        for name, val in WIN_PRESETS_RELATIVE.items():
            act = QAction(name, self)
            if val is None:
                act.triggered.connect(self.win_mgr.apply_maximized)
            else:
                wp, hp = val
                act.triggered.connect(
                    lambda _checked=False, w=wp, h=hp:
                        self.win_mgr.apply_relative(w, h)
                )
            win_menu.addAction(act)

        win_menu.addSeparator()

        act_custom = QAction("&Custom size...", self)
        act_custom.setShortcut("Ctrl+Shift+W")
        act_custom.setToolTip(
            "Open a dialog to dial-in any window size, "
            "either as a percentage of the screen or in pixels.")
        act_custom.triggered.connect(self.win_mgr.open_custom_size_dialog)
        win_menu.addAction(act_custom)

        act_fs = QAction("&Toggle Fullscreen", self)
        act_fs.setShortcut("F11")
        def _toggle_fs():
            if self.isFullScreen():
                self.showNormal()
            else:
                self.showFullScreen()
        act_fs.triggered.connect(_toggle_fs)
        win_menu.addAction(act_fs)

        win_menu.addSeparator()
        act_center = QAction("Re-center on screen", self)
        act_center.triggered.connect(self.win_mgr.center_on_screen)
        win_menu.addAction(act_center)

        act_reset = QAction("Reset to &default size  (85% × 90%)", self)
        act_reset.triggered.connect(
            lambda: self.win_mgr.apply_default_size(0.85, 0.90, 1100, 700))
        win_menu.addAction(act_reset)

        # Remove the deprecated rolling Panels menu whenever Window is rebuilt.
        self._remove_panels_menu_action()

        # ── P+S shortcut: instant vectorized PDF figure export ────────────
        _ps_shortcut = QShortcut(
            QKeySequence("P+S") if QT_VERSION == 6
            else QKeySequence("P+S"),
            self)
        _ps_shortcut.activated.connect(
            lambda: self.export_vector_figure(fmt='pdf', silent=True))
        # also bind Ctrl+Shift+P as a fallback (more reliable on some keyboards)
        _csp_shortcut = QShortcut(
            QKeySequence("Ctrl+Shift+P"), self)
        _csp_shortcut.activated.connect(
            lambda: self.export_vector_figure(fmt='pdf', silent=True))

    def _remove_panels_menu_action(self):
        """Remove the legacy rolling Panels menu from the menu bar.

        The right-panel views are exposed as direct top-bar buttons. This
        routine is intentionally aggressive and idempotent because older
        project/session code can recreate the menu after startup.
        """
        try:
            mb = self.menuBar()
            for act in list(mb.actions()):
                raw_txt = act.text() or ""
                menu_title = ""
                try:
                    if act.menu() is not None:
                        menu_title = act.menu().title() or ""
                except Exception:
                    menu_title = ""

                combined = f"{raw_txt} {menu_title}"
                # Normalize aggressively: remove mnemonics, emojis, spaces,
                # punctuation and hidden characters.  Examples that must all
                # be removed: "Panels", "&Panels", "🗂 Panels", "📁 Panels".
                norm = combined.replace('&', '').lower()
                norm_letters = re.sub(r'[^a-z]+', '', norm)

                if norm_letters == 'panels':
                    try:
                        menu = act.menu()
                        if menu is not None:
                            menu.clear()
                            menu.deleteLater()
                    except Exception:
                        pass
                    try:
                        mb.removeAction(act)
                    except Exception:
                        pass
                    try:
                        act.deleteLater()
                    except Exception:
                        pass

            self._panels_menu = None
        except Exception:
            pass

    def _build_panels_menu(self):
        """Compatibility wrapper: keep Panels removed."""
        self._remove_panels_menu_action()

    def _core_right_panel_indices_for_top_buttons(self):
        """Return core right-panel tab indices exposed as visible top buttons.

        Archived Pfam-A tabs can be created later and remain available from
        the Panels menu and the Right-panel selector. The permanent top row
        intentionally mirrors the built-in views from Genome through
        Genomic PPI Map, as requested.
        """
        indices = []
        if not hasattr(self, "_tabs"):
            return indices
        # Stop AFTER the optional PPI Analysis tab — every panel from
        # Genome through PPI Analysis becomes a permanent top-bar button.
        for i in range(self._tabs.count()):
            indices.append(i)
            label = self._right_view_label(i).strip().lower()
            # End of the standard list: PPI Analysis closes the row.
            if 'ppi analysis' in label:
                break
            # If the PPI Analysis tab does not exist for any reason, fall back
            # to stopping at the Genomic PPI Map tab as in v29.7.
            if label in ("genomic ppi map", "genomic ppi mapa"):
                # Peek one more position — if the next tab is PPI Analysis,
                # keep going; otherwise stop here.
                if i + 1 < self._tabs.count():
                    nxt = self._right_view_label(i + 1).strip().lower()
                    if 'ppi analysis' in nxt:
                        continue
                break
        return indices


    def _compact_right_panel_label(self, label):
        """Short display labels for the top bar; full name stays in tooltip."""
        key = (label or "").strip().lower()
        compact = {
            "blast query":          "BLAST Q",
            "blast results":        "BLAST R",
            "neighborhood":         "Neighbor",
            "submit af3 via server":"Submit AF3",
            "interaction results":  "AF3 table results",
            "results":              "AF3 table results",
            "genomic ppi map":      "PPI Map",
            "genomic ppi mapa":     "PPI Map",
            "🔬 ppi analysis":      "PPI Analysis",
            "ppi analysis":         "PPI Analysis",
        }
        return compact.get(key, label)

    def _build_top_right_panel_buttons(self):
        """Expose right-panel views as visible buttons on the top menu bar.

        These actions sit immediately after Window and switch the same
        views previously reachable through the Right panel dropdown. The
        legacy rolling Panels menu is removed to keep the top bar clean.
        """
        if not hasattr(self, "_tabs"):
            return

        mb = self.menuBar()

        # Remove a previous build before recreating the list, keeping the
        # method idempotent when tabs are added/removed or the active tab
        # changes.
        for act in getattr(self, "_top_right_panel_actions", []):
            try:
                mb.removeAction(act)
                act.deleteLater()
            except Exception:
                pass
        self._top_right_panel_actions = []

        self._remove_panels_menu_action()

        # Reorganize the top bar: insert the view buttons immediately after
        # Window, before the remaining menus/actions. Compact labels keep the
        # toolbar readable after removing the rolling Panels dropdown.
        menu_actions = list(mb.actions())
        insert_before = None
        for pos, act in enumerate(menu_actions):
            txt = (act.text() or "").replace('&', '').strip().lower()
            if txt == 'window' and pos + 1 < len(menu_actions):
                insert_before = menu_actions[pos + 1]
                break

        cur = self._tabs.currentIndex()
        for i in self._core_right_panel_indices_for_top_buttons():
            full_label = self._right_view_label(i)
            label = self._compact_right_panel_label(full_label)
            act = QAction(label, self)
            act.setCheckable(True)
            act.setChecked(i == cur)
            act.setData(i)
            tip = self._panel_tooltip_for(full_label)
            act.setToolTip(tip)
            try:
                act.setStatusTip(tip)
                act.setWhatsThis(tip)
            except Exception:
                pass
            act.triggered.connect(
                lambda _checked=False, idx=i: self._switch_right_view_by_index(idx))

            if insert_before is not None:
                mb.insertAction(insert_before, act)
            else:
                mb.addAction(act)
            self._top_right_panel_actions.append(act)

        # Final cleanup pass in case a legacy Panels QAction was between
        # Window and the newly inserted view actions.
        self._remove_panels_menu_action()
        try:
            self._apply_top_menu_tooltips()
        except Exception:
            pass

    def _refresh_top_right_panel_button_state(self):
        """Update the checked state of the visible top panel buttons."""
        if not hasattr(self, "_tabs"):
            return
        cur = self._tabs.currentIndex()
        for act in getattr(self, "_top_right_panel_actions", []):
            idx = act.data()
            if idx is None:
                continue
            act.setChecked(int(idx) == cur)


    def _panel_tooltip_for(self, full_label):
        """Return a descriptive tooltip for a top-bar panel button.

        Robust to label variations: case-insensitive direct lookup, then a
        partial-keyword search, then a generic fallback.  Keys cover every
        label returned by ``_right_view_label``.
        """
        tips = {
            "genome":             "Genome view — linear coordinate map of every predicted ORF with HMM/Pfam annotations and strand orientation. Primary entry point after loading a FASTA file.",
            "blast query":        "BLAST query — paste or load a query protein and run BLASTp against any UniProt / RefSeq / custom database.",
            "blast results":      "BLAST results — tabular hits from the most recent BLASTp run, with E-value, identity and alignment.",
            "dna":                "DNA view — nucleotide sequence of the loaded genome with codon highlighting and copy/export tools.",
            "protein":            "Protein view — translated protein sequence of the selected ORF, with copy/export tools.",
            "domains":            "Domains — per-ORF list of every HMM/Pfam profile hit found across the genome.",
            "neighborhood":       "Neighborhood — flanking ORFs around the currently selected ORF, with their domain annotations and strand orientation. Used for genomic-context analyses.",
            "hmm":                "HMM profile manager — load, search and visualise Pfam-A or custom HMM libraries against every predicted ORF.",
            "alphafold":          "AlphaFold job builder — organise selected ORFs into AlphaFold 3 batch jobs across seven interaction modes (Pairs, All-vs-All, Genomic Interactome, HMM Hits vs Each Other, Neighbours Interactome, etc.). Supports protein, RNA and DNA chains.",
            "submit af3":         "Submit AF3 — send the generated batch JSON to a remote HPC cluster (SLURM / PBS / LSF) or to the AlphaFold Server.",
            "interaction results":"AF3 table results — per-pair AlphaFold 3 prediction summary with PAE_min, hotspot metrics, contact maps and connected-component motif detection.",
            "results":            "AF3 table results — per-pair AlphaFold 3 prediction summary with PAE_min, hotspot metrics, contact maps and connected-component motif detection.",
            "genomic ppi map":    "Genomic PPI Map — genome-wide arc view of every predicted interaction. Configurable HIGH/MED/ipTM thresholds, bidirectional arcs and label-control on the toolbar.",
            "ppi analysis":       "PPI Analysis — six analytical sub-views of the genomic interactome: per-ORF scatter (transform × base metric), distribution histogram, ROC enrichment of a user-chosen positive set, PAE_min × ipTM 2D scatter, sliding-window genomic density, and Pfam × Pfam interaction heatmap.",
        }
        key = (full_label or "").strip().lower()
        # 1. exact case-insensitive match
        if key in tips:
            return tips[key]
        # 2. partial keyword match (handles minor label variations)
        for k, v in tips.items():
            if k in key or key in k:
                return v
        return f"Show panel: {full_label}"

    def _apply_top_menu_tooltips(self):
        try:
            mb = self.menuBar()
        except Exception:
            return
        for act in mb.actions():
            sub = act.menu()
            if sub is None:
                continue
            try:
                sub.setToolTipsVisible(True)
            except Exception:
                pass
            label = (act.text() or "").replace("&", "").strip().lower()
            tip = None
            if label.startswith("file"):
                tip = "File operations: open FASTA, load HMM, save/open project, export ORFs/figures, quit."
                for child in sub.actions():
                    txt = (child.text() or "").lower()
                    if "open" in txt and "project" not in txt and "hmm" not in txt:
                        child.setToolTip("Open a nucleotide FASTA file to begin analysis.")
                    elif "load hmm" in txt or ("hmm" in txt and "load" in txt):
                        child.setToolTip("Load one or more HMM profile files for domain annotation.")
                    elif "save project as" in txt or "copy" in txt:
                        child.setToolTip("Save a full copy of the project under a new file name.")
                    elif "save project" in txt:
                        child.setToolTip("Save the current project (annotations, HMM library, AF3 results).")
                    elif "open project" in txt:
                        child.setToolTip("Reopen a previously saved ppigFinder project.")
                    elif "orfs" in txt and "save" in txt:
                        child.setToolTip("Export translated ORFs as a multi-FASTA file.")
                    elif "report" in txt and "tsv" in txt:
                        child.setToolTip("Export the ORF annotation table as a TSV file.")
                    elif "export figure" in txt:
                        child.setToolTip("Export the current main view as a vector PDF or raster image.")
                    elif "quit" in txt or "exit" in txt:
                        child.setToolTip("Close ppigFinder.")
                    else:
                        child.setToolTip(child.text() or "")
            elif label.startswith("parameters") or label.startswith("param"):
                tip = "Configure analysis parameters: ORF prediction, BLAST+, and HMMER3 search."
                for child in sub.actions():
                    txt = (child.text() or "").lower()
                    if "orf" in txt:
                        child.setToolTip("Configure ORF prediction (start codons, min length, Pyrodigal vs six-frame, hybrid mode).")
                    elif "blast" in txt:
                        child.setToolTip("Configure BLASTp parameters (E-value, word size, max targets, threads).")
                    elif "hmm" in txt:
                        child.setToolTip("Configure HMMER3 parameters (E-value, score thresholds, domain inclusion).")
                    else:
                        child.setToolTip(child.text() or "")
            elif label.startswith("help"):
                tip = "Documentation: user manual, tutorial, installation, diagnostics, references, about."
                for child in sub.actions():
                    txt = (child.text() or "").lower()
                    if "manual" in txt:
                        child.setToolTip("Open the full user manual.")
                    elif "tutorial" in txt:
                        child.setToolTip("Walk-through tutorial for a typical analysis.")
                    elif "install" in txt:
                        child.setToolTip("Installation and dependency notes.")
                    elif "system check" in txt:
                        child.setToolTip("Run diagnostics on external dependencies (BLAST+, HMMER3, Pyrodigal).")
                    elif "interaction results" in txt:
                        child.setToolTip("Help on interpreting the Interaction Results panel.")
                    elif "ppi map" in txt:
                        child.setToolTip("Help on reading the Genomic PPI Map.")
                    elif "reference" in txt or "method" in txt:
                        child.setToolTip("References and methodology.")
                    elif "about" in txt:
                        child.setToolTip("About ppigFinder.")
                    else:
                        child.setToolTip(child.text() or "")
            elif label.startswith("window"):
                tip = "Window: change window size presets, toggle fullscreen, re-center, reset layout."
                for child in sub.actions():
                    child.setToolTip(child.text() or "")
            if tip:
                act.setToolTip(tip)

    def _switch_right_view_by_index(self, idx):
        """Switch the right panel to a tab by its index (used by Panels menu)."""
        if hasattr(self, "_tabs") and 0 <= idx < self._tabs.count():
            self._tabs.setCurrentIndex(idx)
            self._sync_right_view_selector()

    def closeEvent(self, event):
        """Persist user's window size/position for next session."""
        try:
            if hasattr(self, 'win_mgr'):
                self.win_mgr.save_geometry()
        except Exception:
            pass
        try:
            super().closeEvent(event)
        except Exception:
            event.accept()

