    # ── AF3 Analysis helpers ─────────────────────────────────────

    def _af3a_load_folder(self):
        folder = QFileDialog.getExistingDirectory(
            self, "Select AF3 results folder")
        if not folder:
            return
        self._af3_analysis_dir = folder
        self._af3a_scan_folder(folder)

    def _af3a_clear(self):
        self._af3_analysis_results = []
        self._af3a_table.setRowCount(0)
        self._af3a_clear_plots()
        self._af3a_status.setText("Cleared")

    # ── AF3 file classification (content-based) ───────────────
    #
    # v1.15: classify JSON files by their top-level keys rather than
    # their filename, because the AF3 server sometimes writes files
    # whose filenames do not clearly mark their role. Also keeps the
    # large input-data JSON (which can be 80+ MB of MSA / sequences)
    # from being loaded into memory during the scan.

    # Signatures (top-level keys) used to identify each JSON type.
    _AF3_SUMMARY_SIGNATURE_KEYS  = {'iptm', 'ptm', 'ranking_score'}
    _AF3_CONF_SIGNATURE_KEYS     = {'pae', 'atom_plddts', 'token_chain_ids'}
    _AF3_DATA_SIGNATURE_KEYS     = {'sequences', 'modelSeeds', 'dialect'}

    # Files larger than this are skipped without opening (protects us
    # from accidentally loading the input-data JSON with its full MSA).
    _AF3_MAX_JSON_SCAN_BYTES = 200 * 1024 * 1024   # 200 MB

    @classmethod
    def _af3a_classify_json(cls, path: Path) -> str:
        """Classify an AlphaFold JSON by content, with filename hints only as
        tie-breakers.

        v2.8 fix: AF3 local/DaVinci jobs may store the full PAE matrix in
        files named *_full_data_0.json rather than *_confidences.json.  These
        files can also contain input-like keys such as ``sequences`` and
        ``modelSeeds``; therefore PAE-bearing JSONs must be treated as
        ``confidences`` before applying the input-data rule.

        Returns one of:
          'summary'      — summary_confidences JSON (ipTM/pTM/ranking)
          'confidences'  — JSON carrying the PAE/contact matrix
          'data'         — AF3 job request / input sequence JSON
          'unknown'      — any other JSON
        """
        try:
            size = path.stat().st_size
        except OSError:
            return 'unknown'

        name_lc = path.name.lower()

        # Explicit filename hints that are safe and cheap.
        if 'summary_confidences' in name_lc:
            return 'summary'
        if ('job_request' in name_lc or name_lc.endswith('_data.json')
                or name_lc == 'data.json'):
            # Important: do NOT classify *_full_data_0.json here.
            if 'full_data' not in name_lc:
                return 'data'
        if 'full_data' in name_lc:
            # AF3 local output: this is the file that carries the full PAE
            # matrix and often contact_probs/atom_plddts.
            return 'confidences'
        if 'confidences' in name_lc and 'summary' not in name_lc:
            return 'confidences'

        if size > cls._AF3_MAX_JSON_SCAN_BYTES:
            # Very large JSONs in AF3 output folders are almost always full
            # data/confidence files.  They are useful for PAE, not for job
            # input, so keep them as confidences.
            return 'confidences'

        # Small/medium files: load full object if feasible.
        if size < 10 * 1024 * 1024:
            try:
                with open(path, encoding='utf-8') as f:
                    obj = json.load(f)
                if not isinstance(obj, dict):
                    return 'unknown'
                keys = set(obj.keys())

                # Summary-only files first when they do not carry matrices.
                if (cls._AF3_SUMMARY_SIGNATURE_KEYS.issubset(keys)
                        and not ({'pae', 'contact_probs'} & keys)):
                    return 'summary'

                # PAE/contact-bearing JSONs are matrix/confidence files even
                # if they also contain sequences/modelSeeds/dialect.
                if ({'pae', 'contact_probs'} & keys
                        or {'atom_plddts', 'token_chain_ids'} & keys):
                    return 'confidences'

                if cls._AF3_DATA_SIGNATURE_KEYS & keys:
                    return 'data'
                return 'unknown'
            except (OSError, json.JSONDecodeError, MemoryError):
                return 'unknown'

        # Larger files: stream top-level keys via ijson when available.
        try:
            import ijson
            keys_seen = set()
            with open(path, 'rb') as f:
                for prefix, event, _val in ijson.parse(f):
                    if (prefix and '.' not in prefix
                            and event in ('start_array', 'start_map',
                                          'string', 'number',
                                          'boolean', 'null')):
                        keys_seen.add(prefix)
                    # Once PAE/contact keys are seen, classification is final.
                    if {'pae', 'contact_probs'} & keys_seen:
                        return 'confidences'
                    if len(keys_seen) >= 24:
                        break
            if cls._AF3_SUMMARY_SIGNATURE_KEYS.issubset(keys_seen):
                return 'summary'
            if ({'pae', 'contact_probs'} & keys_seen
                    or {'atom_plddts', 'token_chain_ids'} & keys_seen):
                return 'confidences'
            if cls._AF3_DATA_SIGNATURE_KEYS & keys_seen:
                return 'data'
            return 'unknown'
        except ImportError:
            # Without ijson, a >10 MB JSON in an AF3 output folder is more
            # likely to be a PAE/full_data file than a small job request.
            return 'confidences'
        except (OSError, ValueError):
            return 'unknown'

    def _af3a_find_job_files(self, job_dir: Path) -> dict:
        """Find AF3 output files inside a job directory.

        v2.8: supports both AF3 Server-style folders
        (summary_confidences.json + confidences.json + model.cif) and local
        AF3/DaVinci folders with replicate files
        (*_summary_confidences_0.json, *_full_data_0.json, *_model_0.cif).
        The PAE matrix is selected from any JSON that actually carries PAE,
        not only from files named "confidences".
        """
        result = {
            'summary': None, 'confidences': None,
            'model': None, 'ranking_csv': None,
            'input': None,
            'sample_dirs': [],
        }
        try:
            entries = list(job_dir.iterdir())
        except OSError:
            return result

        summaries = []
        confidences = []
        inputs = []
        models = []

        def _idx(path: Path):
            name = path.name.lower()
            for pat in (r'summary_confidences_(\d+)\.json$',
                        r'full_data_(\d+)\.json$',
                        r'model_(\d+)\.cif$'):
                m = re.search(pat, name)
                if m:
                    try:
                        return int(m.group(1))
                    except ValueError:
                        return None
            return None

        def _load_small_json(path: Path):
            try:
                if path.stat().st_size > 5 * 1024 * 1024:
                    return None
                with open(path, encoding='utf-8') as f:
                    obj = json.load(f)
                return obj if isinstance(obj, dict) else None
            except Exception:
                return None

        def _summary_score(path: Path):
            obj = _load_small_json(path) or {}
            name = path.name.lower()
            score = 0.0
            if 'chain_pair_pae_min' in obj:
                score += 1000.0
            if 'chain_pair_iptm' in obj:
                score += 500.0
            # Prefer job-specific summary over generic duplicated
            # summary_confidences.json when both are present.
            stem_tokens = [t for t in re.split(r'[^a-z0-9]+', job_dir.name.lower()) if t]
            if any(t and t in name for t in stem_tokens[:4]):
                score += 100.0
            if name != 'summary_confidences.json':
                score += 25.0
            # Prefer the model already ranked first by AF3 naming (_0) when
            # no ranking CSV is available.  If ranking_score differs, use it.
            try:
                score += float(obj.get('ranking_score', 0.0))
            except Exception:
                pass
            ix = _idx(path)
            if ix == 0:
                score += 10.0
            elif ix is not None:
                score += max(0.0, 5.0 - ix)
            return score

        for p in entries:
            if not p.is_file():
                continue
            name_lc = p.name.lower()
            if name_lc.endswith('.json'):
                kind = self._af3a_classify_json(p)
                if kind == 'summary':
                    summaries.append(p)
                elif kind == 'confidences':
                    confidences.append(p)
                    # A *_full_data_N.json may also carry sequences.  Keep it
                    # as a possible input fallback, but never at the expense
                    # of a cleaner *_data.json or job_request.json.
                    if 'full_data' in name_lc:
                        inputs.append(p)
                elif kind == 'data':
                    inputs.append(p)
            elif name_lc.endswith('.cif'):
                models.append(p)
            elif name_lc == 'ranking_scores.csv':
                result['ranking_csv'] = p

        if summaries:
            summaries.sort(key=_summary_score, reverse=True)
            result['summary'] = summaries[0]
            selected_idx = _idx(result['summary'])
        else:
            selected_idx = None

        def _prefer_by_index(paths, ix):
            if not paths:
                return None
            if ix is not None:
                same = [p for p in paths if _idx(p) == ix]
                if same:
                    # Prefer files that are not tiny placeholders.
                    return max(same, key=lambda p: p.stat().st_size)
            return max(paths, key=lambda p: (
                1 if 'confidences' in p.name.lower() and 'summary' not in p.name.lower() else 0,
                1 if 'full_data' in p.name.lower() else 0,
                p.stat().st_size))

        result['confidences'] = _prefer_by_index(confidences, selected_idx)
        result['model'] = _prefer_by_index(models, selected_idx)

        # Input sequence source: prefer explicit job request / *_data.json.
        explicit_inputs = [p for p in inputs
                           if ('job_request' in p.name.lower()
                               or p.name.lower().endswith('_data.json')
                               or p.name.lower() == 'data.json')
                           and 'full_data' not in p.name.lower()]
        if explicit_inputs:
            result['input'] = _prefer_by_index(explicit_inputs, selected_idx)
        else:
            # Fallback: full_data can also contain submitted sequences.
            result['input'] = _prefer_by_index(inputs, selected_idx)

        # Collect sample sub-dirs (detail views, not primary jobs)
        for p in entries:
            if p.is_dir() and re.match(r'seed-\d+_sample-\d+', p.name):
                result['sample_dirs'].append(p)
        result['sample_dirs'].sort()

        return result

    def _af3a_discover_job_dirs(self, root: Path) -> list:
        """Find AF3 job folders recursively without treating wrapper folders
        as jobs.

        AF3 batch exports commonly use one wrapper folder containing many job
        folders.  Some download tools add one extra layer, so direct-child-only
        scanning silently loads nothing.  This keeps the parser itself intact
        and only improves candidate discovery.
        """
        if not root.is_dir():
            return []

        def _dir_has_summary(path: Path) -> bool:
            try:
                jsons = list(path.glob("*.json"))
            except OSError:
                return False
            likely = [p for p in jsons if "summary" in p.name.lower()]
            rest = [p for p in jsons if p not in likely]
            for p in likely + rest:
                if self._af3a_classify_json(p) == "summary":
                    return True
            return False

        if _dir_has_summary(root):
            return [root]

        job_dirs = []
        seen = set()
        for dirpath, dirnames, filenames in os.walk(root):
            # seed/sample subfolders are detail folders for a parent job.
            dirnames[:] = [
                d for d in dirnames
                if not re.match(r'seed-\d+_sample-\d+', d)
            ]
            path = Path(dirpath)
            if path == root:
                continue
            if not any(name.lower().endswith(".json") for name in filenames):
                continue
            if not any("summary" in name.lower() for name in filenames):
                continue
            if _dir_has_summary(path):
                try:
                    key = str(path.resolve())
                except OSError:
                    key = str(path)
                if key not in seen:
                    seen.add(key)
                    job_dirs.append(path)
        job_dirs.sort(key=lambda p: str(p).lower())
        return job_dirs

    def _af3a_scan_folder(self, folder: str):
        """Scan a folder tree for AF3 jobs.

        v1.15 (content-based):
          • Each candidate directory is inspected for AF3 output files
            via content classification (_af3a_classify_json), not file-
            name globs. This handles AF3 server outputs whose naming
            differs from the strict _summary_confidences.json /
            _confidences.json convention.
          • Huge input-data JSONs are filtered out by size BEFORE being
            opened (they contain MSAs and would otherwise bloat memory).
          • seed-*_sample-* subfolders are treated as the per-sample
            detail of their parent job (the best model is already
            promoted to the parent), not as independent jobs.
          • Parse errors are surfaced in a single dialog at the end.
          • A progress dialog shows scan status for large folder trees.
          • The top-scoring row is auto-selected after populate.
        """
        root = Path(folder)
        try:
            top_level = sorted(root.iterdir())
        except OSError as e:
            QMessageBox.critical(
                self, "AF3 Analysis",
                f"Could not read folder:\n{folder}\n\n{e}")
            return

        # Build list of candidate job dirs.  Wrapper folders are scanned
        # recursively because AF3 batch downloads often put the real jobs one
        # or more levels below the selected folder.
        candidates = self._af3a_discover_job_dirs(root)
        if not candidates:
            candidates = [
                p for p in top_level
                if p.is_dir() and not re.match(r'seed-\d+_sample-\d+', p.name)
            ]
        if not candidates:
            candidates = [root]

        # Progress dialog
        try:
            if QT_VERSION == 6:
                from PyQt6.QtWidgets import QProgressDialog
            else:
                from PyQt5.QtWidgets import QProgressDialog
            progress = QProgressDialog(
                "Scanning AF3 jobs…", "Cancel",
                0, len(candidates), self)
            progress.setWindowTitle("AF3 Analysis")
            progress.setMinimumDuration(400)
            progress.setValue(0)
        except Exception:
            progress = None

        jobs = []
        errors  = []  # list of (dir_name, error_message)
        skipped = 0   # dirs that are not AF3 jobs

        for i, job_dir in enumerate(candidates):
            if progress is not None:
                progress.setValue(i)
                progress.setLabelText(
                    f"Scanning AF3 jobs… ({i}/{len(candidates)})")
                QApplication.processEvents()
                if progress.wasCanceled():
                    break

            files = self._af3a_find_job_files(job_dir)
            if files['summary'] is None:
                # Not an AF3 job folder — skip silently
                skipped += 1
                continue

            try:
                parsed = self._af3a_parse_job(
                    job_dir,
                    files['summary'],
                    files['confidences'],
                    model_cif=files['model'],
                    ranking_csv=files['ranking_csv'],
                    input_json=files['input'],
                    lazy=True)
                if parsed:
                    jobs.append(parsed)
            except Exception as e:
                errors.append((job_dir.name, str(e)))
                print(f"[AF3 Analysis] {job_dir.name}: {e}")

        if progress is not None:
            progress.setValue(len(candidates))

        # v2.5 Tier 1 — assign duplicate groups before the table is built
        # so the badge / count columns can reflect group membership.
        self._af3a_assign_duplicate_groups(jobs)

        self._af3_analysis_results = jobs
        self._af3a_populate_table()

        status = f"{len(jobs)} job(s) loaded from {Path(folder).name}/"
        if errors:  status += f"  ⚠ {len(errors)} failed"
        if skipped: status += f"  ({skipped} non-AF3 dirs skipped)"
        self._af3a_status.setText(status)
        self._update_orfs_list()

        if not jobs and not errors:
            QMessageBox.information(
                self, "AF3 Analysis",
                "No AF3 summary JSON files were found in this folder tree.\n\n"
                "Select the folder that contains AlphaFold job result folders "
                "with summary_confidences JSON files.")

        if self._af3a_table.rowCount() > 0:
            self._af3a_table.selectRow(0)

        # v2.5 Tier 2 — show the validation report dialog after every load
        # if there are problems worth flagging.  For perfectly-clean
        # folders we keep things quiet (no dialog interrupts the flow).
        try:
            self._af3a_show_validation_report(jobs, folder, after_scan=True)
        except Exception as _e:
            print(f"[AF3 Analysis] validation report error: {_e}")

        if errors:
            msg = "\n".join(f"• {name}: {err}" for name, err in errors[:15])
            if len(errors) > 15:
                msg += f"\n… and {len(errors) - 15} more."
            QMessageBox.warning(
                self, "AF3 Analysis — partial load",
                f"{len(errors)} job(s) could not be parsed:\n\n{msg}")

    # ──────────────────────────────────────────────────────────────────
    #  v2.5 — Fingerprinting & validation helpers (Tier 1 + Tier 2)
    # ──────────────────────────────────────────────────────────────────
    #
    #  These build the metadata used by the new duplicate detector and
    #  the Validation Report panel.  All are pure functions so they can
    #  be unit-tested without instantiating the full app.
    #
    @staticmethod
    def _af3a_seq_fingerprint(input_seqs):
        """Order-independent fingerprint of a job's sequence set.

        Two jobs with the same fingerprint were submitted with the same
        bag of protein sequences regardless of chain ordering or folder
        naming.  Uses SHA-256 truncated to 16 chars — collision-safe at
        the scale of any realistic ppigFinder dataset.

        Returns None if input_seqs is empty (no fingerprint possible).
        """
        if not input_seqs:
            return None
        # Canonical form: each seq stripped of stop codons, uppercased,
        # then sorted to make ordering irrelevant.
        canonical_parts = sorted(
            s.upper().replace('*', '').strip()
            for s in input_seqs if s)
        if not canonical_parts:
            return None
        canonical = '|'.join(canonical_parts)
        return hashlib.sha256(canonical.encode('utf-8')).hexdigest()[:16]

    @staticmethod
    def _af3a_seq_seed_fingerprint(input_seqs, model_seeds):
        """Fingerprint that distinguishes byte-identical replicates.

        Same fingerprint AND same seeds → AF3 was re-run with the same
        inputs (true duplicate).  Same fingerprint, different seeds →
        legitimate replicate for variance estimation.
        """
        base = ppigFinderApp._af3a_seq_fingerprint(input_seqs)
        if base is None:
            return None
        seeds_str = '-'.join(str(s) for s in sorted(model_seeds or []))
        return f"{base}-{seeds_str}" if seeds_str else f"{base}-noseed"

    @staticmethod
    def _af3a_completeness_status(files_dict, model_loaded_ok=True,
                                   has_chain_info=True):
        """Classify how complete an AF3 job folder is.

        Returns one of:
          'complete'             — summary + confidences + model.cif all present
          'no_full_confidences'  — summary + model present, full conf missing
                                    (the case fix #4 made loadable as fallback)
          'no_model'             — summary present but no model.cif
                                    (AF3 likely crashed before writing)
          'no_summary'           — no summary_confidences.json
                                    (parsing wouldn't even start)
          'empty_or_partial'     — directory exists but key files absent
        """
        if files_dict is None:
            return 'empty_or_partial'
        has_summary  = files_dict.get('summary')   is not None
        has_conf     = files_dict.get('confidences') is not None
        has_model    = files_dict.get('model')     is not None
        if not has_summary:
            return 'no_summary' if (has_conf or has_model) else 'empty_or_partial'
        if not has_model:
            return 'no_model'
        if not has_conf:
            return 'no_full_confidences'
        return 'complete'

    @staticmethod
    def _af3a_detect_truncation(input_seqs, chain_order, chain_lens):
        """Compare modeled chain lengths vs input sequence lengths.

        AF3 silently truncates inputs that exceed its token budget.
        If the model.cif (or confidences) reports fewer residues than
        the data.json input for a chain, that chain was clipped.

        Returns a list of {chain, expected, modeled, missing} dicts,
        or [] if no truncation detected.  Returns [] also when the
        information needed for the comparison is unavailable.
        """
        if not input_seqs or not chain_order or not chain_lens:
            return []
        results = []
        for i, cid in enumerate(chain_order):
            if i >= len(input_seqs):
                break
            modeled  = chain_lens.get(cid, 0)
            expected = len(input_seqs[i])
            # Only flag clear truncations (>5 residues short).  Small
            # discrepancies are normal for terminal residues that AF3
            # sometimes omits from the model output.
            if modeled > 0 and expected - modeled >= 5:
                results.append({
                    'chain':    cid,
                    'expected': expected,
                    'modeled':  modeled,
                    'missing':  expected - modeled,
                })
        return results

    def _af3a_assign_duplicate_groups(self, jobs):
        """Group jobs by seq_fingerprint and tag duplicates in-place.

        v2.5 Tier 1 — runs once per scan, after every job has been
        parsed.  Groups jobs with identical sequence fingerprints and
        elects a "canonical" job per group (the one with the highest
        ranking_score, breaking ties by alphabetic folder name).

        Mutates each job dict to set:
            duplicate_group_id     — int (0..N) or -1 if singleton
            duplicate_role         — 'canonical' / 'replicate' / None
            duplicate_count        — total jobs in this group
            duplicate_sub_role     — 'true_duplicate'  (same seeds too)
                                     'replicate'        (same seqs, ≠ seeds)
                                     None               (singleton)
        """
        if not jobs:
            return
        # Group by fingerprint
        from collections import defaultdict
        groups = defaultdict(list)
        for j in jobs:
            fp = j.get('seq_fingerprint')
            if fp is None:
                # No fingerprint (no input JSON) — treat as singleton
                continue
            groups[fp].append(j)

        # Assign group IDs only to groups with > 1 member
        gid = 0
        for fp, members in groups.items():
            if len(members) <= 1:
                continue
            # Choose canonical: highest ranking_score, then alphabetic folder
            members.sort(
                key=lambda j: (
                    -(j.get('ranking_score') if j.get('ranking_score') is not None else -1),
                    j.get('job_name', '')))
            canonical = members[0]
            n = len(members)
            # Sub-classify by seeds: same seq_seed_fingerprint → byte-id dup
            seed_groups = defaultdict(list)
            for m in members:
                seed_groups[m.get('seq_seed_fingerprint')].append(m)
            for m in members:
                m['duplicate_group_id'] = gid
                m['duplicate_count']    = n
                m['duplicate_role']     = ('canonical' if m is canonical
                                            else 'replicate')
                # 'true_duplicate' if 2+ jobs share BOTH seqs and seeds
                ssfp = m.get('seq_seed_fingerprint')
                if len(seed_groups.get(ssfp, [])) > 1:
                    m['duplicate_sub_role'] = 'true_duplicate'
                else:
                    m['duplicate_sub_role'] = 'replicate'
                # Add a warning so the badge tooltip explains why it's flagged
                if m['duplicate_role'] == 'replicate':
                    if m['duplicate_sub_role'] == 'true_duplicate':
                        msg = (f"True duplicate of {canonical['job_name']} "
                               f"(same sequences AND seeds)")
                    else:
                        msg = (f"Replicate of {canonical['job_name']} "
                               f"(same sequences, different seeds)")
                    if msg not in m.get('validation_warnings', []):
                        m.setdefault('validation_warnings', []).append(msg)
            gid += 1

    def _af3a_show_validation_report(self, jobs, folder, after_scan=False):
        """Show a summary dialog with counts of each problem class.

        Suppressed (no dialog) when nothing notable is found AND we're
        being called right after a scan (we don't want to interrupt
        the user with empty pop-ups).  Always shows when invoked
        manually from the menu (after_scan=False).
        """
        if not jobs:
            return

        # Tally categories
        n_total = len(jobs)
        seq_status_counts = defaultdict(int)
        completeness_counts = defaultdict(int)
        n_truncated = 0
        n_ambiguous = 0
        n_with_warnings = 0
        # Duplicate groups
        from collections import defaultdict as _dd
        dup_groups = _dd(list)
        for j in jobs:
            seq_status_counts[j.get('seq_status', '?')] += 1
            completeness_counts[j.get('completeness', '?')] += 1
            if j.get('truncation_info'):  n_truncated += 1
            if j.get('ambiguity_info'):   n_ambiguous += 1
            if j.get('validation_warnings'): n_with_warnings += 1
            gid = j.get('duplicate_group_id', -1)
            if gid >= 0:
                dup_groups[gid].append(j)

        n_dup_jobs   = sum(len(v) for v in dup_groups.values())
        n_dup_groups = len(dup_groups)
        n_true_dup   = sum(1 for j in jobs
                            if j.get('duplicate_sub_role') == 'true_duplicate'
                            and j.get('duplicate_role') == 'replicate')
        n_replicate  = sum(1 for j in jobs
                            if j.get('duplicate_sub_role') == 'replicate'
                            and j.get('duplicate_role') == 'replicate')

        # Decide whether to surface the dialog at all
        anything_notable = (
            n_dup_groups > 0
            or n_truncated > 0
            or n_ambiguous > 0
            or seq_status_counts.get('name_partial', 0) > 0
            or seq_status_counts.get('name_foreign', 0) > 0
            or seq_status_counts.get('name_outdated', 0) > 0
            or seq_status_counts.get('name_swapped', 0) > 0
            or seq_status_counts.get('name_homodimer_hidden', 0) > 0
            or completeness_counts.get('no_model', 0) > 0
            or completeness_counts.get('empty_or_partial', 0) > 0)
        if after_scan and not anything_notable:
            return  # quiet path — clean folder

        # Build the report text
        lines = []
        lines.append(f"<h3>Validation Report — {Path(folder).name}/</h3>")
        lines.append(f"<p><b>{n_total} job(s) loaded</b></p>")

        # Sequence-status breakdown
        _seq_labels = [
            ('name_perfect',          '✅ Folder name matches sequences perfectly'),
            ('name_swapped',          '🔄 Chain order swapped vs folder name'),
            ('name_outdated',         '🔁 ORF numbering corrected (genome re-run)'),
            ('name_partial',          '⚠ Partial sequence match (some chains foreign)'),
            ('name_foreign',          '🌐 Sequences not in current genome'),
            ('name_homodimer_hidden', '👯 Hidden homodimer (folder lists 2 different ORFs)'),
            ('no_input',              '📂 No input JSON to verify against'),
            ('no_orfs',               '❔ No genome loaded'),
            # legacy values (in case older results are mixed in)
            ('verified',              '✅ Verified (legacy)'),
            ('corrected',             '🔁 Corrected (legacy)'),
            ('mismatch',              '⚠ Mismatch (legacy)'),
        ]
        lines.append('<p><b>Sequence verification status</b></p><ul>')
        for key, lbl in _seq_labels:
            n = seq_status_counts.get(key, 0)
            if n > 0:
                lines.append(f'<li>{lbl}: <b>{n}</b></li>')
        lines.append('</ul>')

        # Duplicate summary
        if n_dup_groups > 0:
            lines.append(
                f'<p><b>🔁 Duplicates: {n_dup_jobs} job(s) in '
                f'{n_dup_groups} group(s)</b></p><ul>')
            lines.append(
                f'<li>True duplicates (same seqs + same seeds): '
                f'<b>{n_true_dup}</b> redundant job(s) — '
                f'safe to delete</li>')
            lines.append(
                f'<li>Replicates (same seqs, different seeds): '
                f'<b>{n_replicate}</b> job(s) — '
                f'useful for variance analysis</li>')
            lines.append('</ul>')
            # Show top 5 groups
            sorted_groups = sorted(dup_groups.items(),
                                    key=lambda kv: -len(kv[1]))[:5]
            lines.append(
                '<p><b>Largest duplicate groups</b> '
                '(see Interaction Results table for details):</p><ul>')
            for gid, members in sorted_groups:
                names = ', '.join(m['job_name'] for m in members[:3])
                if len(members) > 3:
                    names += f', … (+{len(members)-3} more)'
                lines.append(
                    f'<li>Group {gid+1} ({len(members)} jobs): {names}</li>')
            lines.append('</ul>')

        # Completeness summary
        if any(completeness_counts.get(k, 0) > 0
               for k in ('no_model', 'no_full_confidences',
                          'no_summary', 'empty_or_partial')):
            lines.append('<p><b>Completeness issues</b></p><ul>')
            _comp_labels = [
                ('no_model',
                 '❌ Missing model.cif (AF3 likely crashed)'),
                ('no_full_confidences',
                 'ℹ Summary OK, full confidences missing (chain info from fallback)'),
                ('no_summary',
                 '❌ Missing summary_confidences.json'),
                ('empty_or_partial',
                 '❌ Job folder mostly empty'),
            ]
            for key, lbl in _comp_labels:
                n = completeness_counts.get(key, 0)
                if n > 0:
                    lines.append(f'<li>{lbl}: <b>{n}</b></li>')
            lines.append('</ul>')

        # Truncation / ambiguity
        if n_truncated > 0:
            lines.append(
                f'<p>✂ <b>{n_truncated} job(s) truncated</b> — '
                'modeled chain shorter than input sequence '
                '(AF3 token limit hit?). See tooltip on the job '
                'name cell for details.</p>')
        if n_ambiguous > 0:
            lines.append(
                f'<p>🧬 <b>{n_ambiguous} job(s) with ambiguous matches</b> — '
                'one or more sequences match multiple ORFs in the genome '
                '(paralogs / duplicate ORFs). Consider running BLAST to '
                'pick the right one.</p>')

        lines.append(
            '<p style="color:#666;font-size:11px;">'
            '<i>Tip: the Interaction Results table now has a right-click '
            'menu with "Select all duplicates" and "Select all rows with '
            'no chain info" — quick way to triage from this report.</i></p>')

        # Show the dialog
        try:
            dlg = QDialog(self)
            dlg.setWindowTitle("AF3 — Validation Report")
            lay = QVBoxLayout(dlg)
            tb = QTextBrowser()
            tb.setHtml('\n'.join(lines))
            tb.setOpenExternalLinks(False)
            lay.addWidget(tb)
            btn_row = QHBoxLayout()
            btn_row.addStretch()
            btn_close = QPushButton("Close")
            btn_close.clicked.connect(dlg.accept)
            btn_row.addWidget(btn_close)
            lay.addLayout(btn_row)
            dlg.resize(620, 540)
            dlg.exec()
        except Exception:
            # Fall back to plain message box if dialog construction fails
            QMessageBox.information(
                self, "AF3 — Validation Report",
                "\n".join(re.sub(r'<[^>]+>', '', l) for l in lines))

    def _af3a_parse_job(self, job_dir: Path, sum_path: Path,
                         conf_path, model_cif: Path = None,
                         ranking_csv: Path = None,
                         input_json: Path = None,
                         lazy: bool = False) -> dict:
        """Parse one AF3 job. Handles any number of chains.

        v2.8.1 performance mode:
          • lazy=True is used during large folder scans.  It reads only
            lightweight metadata (summary JSON, CIF chain lengths and small
            job_request/data JSONs) and never loads full PAE/contact matrices.
          • Heavy arrays (PAE, contact_probs, atom_plddts) are loaded only
            when the user selects a row for plotting.

        v1.15:
          • Rich summary: uses chain_iptm, chain_pair_iptm,
            chain_pair_pae_min, chain_ptm, fraction_disordered,
            has_clash when present.
          • Per-residue pLDDT: if only 'atom_plddts' is available
            (current AF3 server output), aggregates atoms → residues
            using the atom→residue map parsed from the model .cif.
          • token_res_ids are kept so the plot can show actual residue
            numbers (1..N per chain, not a running 0..total index).
          • ranking_scores.csv is attached to the result dict when
            present, for display as a per-sample breakdown.
        """
        # ── Summary scores ─────────────────────────────────────
        with open(sum_path, encoding='utf-8') as f:
            summary = json.load(f)

        iptm          = summary.get('iptm')
        ptm           = summary.get('ptm')
        ranking_score = summary.get('ranking_score')

        # Rich per-chain + pair data (AF3 server format)
        chain_iptm         = summary.get('chain_iptm')          # list[float]
        chain_ptm          = summary.get('chain_ptm')           # list[float]
        chain_pair_iptm    = summary.get('chain_pair_iptm')     # 2D list
        chain_pair_pae_min = summary.get('chain_pair_pae_min')  # 2D list
        fraction_disordered = summary.get('fraction_disordered')
        has_clash          = summary.get('has_clash')

        # Mean pLDDT: AF3 summary does not carry it; we compute it
        # below from atom_plddts / per-residue arrays.
        mean_plddt = (summary.get('mean_plddt')
                      or summary.get('mean_pLDDT'))

        # ── PAE + pLDDT + chain info ────────────────────────────
        pae_matrix    = None
        plddt_arr     = None        # per-residue
        chain_ids     = None        # per-residue chain labels
        token_res_ids = None
        atom_plddts   = None
        contact_probs = None

        if (not lazy) and conf_path and Path(conf_path).is_file():
            with open(conf_path, encoding='utf-8') as f:
                conf = json.load(f)
            pae_matrix    = conf.get('pae')
            contact_probs = conf.get('contact_probs')

            # Per-residue (token) chain IDs and residue IDs
            for key in ('token_chain_ids', 'chain_ids', 'asym_id'):
                v = conf.get(key)
                if v:
                    chain_ids = v
                    break
            token_res_ids = conf.get('token_res_ids')

            # Per-residue pLDDT — try direct keys first.
            for key in ('token_plddts', 'plddt',
                        'predicted_lddt', 'residue_plddt'):
                v = conf.get(key)
                if v:
                    plddt_arr = v
                    break

            # Per-atom pLDDT (always keep for fallback / CIF aggregation)
            atom_plddts    = conf.get('atom_plddts')

            # If direct per-residue pLDDT is missing or length mismatch,
            # aggregate per-atom pLDDT to per-residue using the CIF map.
            if (plddt_arr is None
                    or (chain_ids is not None
                        and len(plddt_arr) != len(chain_ids))):
                plddt_arr = self._af3a_derive_token_plddt(
                    atom_plddts, chain_ids, token_res_ids, model_cif)

        # If mean_plddt missing, compute from whatever is available.
        if mean_plddt is None:
            for arr in (plddt_arr, atom_plddts):
                if arr:
                    try:
                        mean_plddt = float(np.mean(arr))
                        break
                    except Exception:
                        pass

        # ── Pre-load sequences from input JSON (used as fallback for ──
        # ── chain layout below if confidences.json is missing chain IDs)
        # The ppigFinder-generated *_data.json (v3 of the AF3 spec) holds
        # the proteinChain entries in the order they were submitted to AF3,
        # which directly corresponds to chain letters A, B, C…
        input_seqs = []          # sequences extracted from input JSON
        model_seeds = []         # v2.5: model seeds extracted from data.json
        if input_json and Path(input_json).is_file():
            try:
                _input_path_obj = Path(input_json)
                _input_name_lc = _input_path_obj.name.lower()
                # In lazy scan mode, avoid parsing heavy *_full_data_N.json
                # files just to recover sequences.  Explicit job_request or
                # small *_data.json inputs remain cheap and are still parsed.
                if lazy and ('full_data' in _input_name_lc or
                             _input_path_obj.stat().st_size > 5 * 1024 * 1024):
                    raise RuntimeError('skip heavy input JSON during lazy scan')
                with open(input_json, encoding='utf-8') as _f:
                    _inp = json.load(_f)
                _entries = _inp if isinstance(_inp, list) else [_inp]
                for _job in _entries:
                    if not isinstance(_job, dict):
                        continue
                    # Capture modelSeeds (used to distinguish replicate
                    # AF3 runs vs byte-identical re-submissions in the
                    # duplicate detector).  AF3 v3 stores these at the
                    # job level.
                    _seeds = _job.get('modelSeeds') or _job.get('seeds')
                    if isinstance(_seeds, list):
                        for _s in _seeds:
                            try:
                                model_seeds.append(int(_s))
                            except (TypeError, ValueError):
                                pass
                    for _entry in _job.get('sequences', []):
                        if not isinstance(_entry, dict):
                            continue
                        # Support both v2 ("proteinChain") and v3 ("protein")
                        # spellings of the protein-chain entry.
                        _pc = (_entry.get('proteinChain')
                               or _entry.get('protein')
                               or {})
                        _pcs = _pc if isinstance(_pc, list) else [_pc]
                        for _chain in _pcs:
                            if not isinstance(_chain, dict):
                                continue
                            _seq = (_chain.get('sequence', '')
                                    .strip().rstrip('*').upper())
                            if _seq:
                                # Stoichiometry: 'id' may be a list of chain
                                # letters meaning "this same sequence is
                                # repeated N times".  Expand accordingly so
                                # input_seqs has one entry per actual chain.
                                _id = _chain.get('id')
                                _n_copies = (len(_id) if isinstance(_id, list)
                                             else 1)
                                for _ in range(max(_n_copies, 1)):
                                    input_seqs.append(_seq)
            except (OSError, json.JSONDecodeError, AttributeError, TypeError, RuntimeError):
                pass

        # ── Chain layout ────────────────────────────────────────
        # Five-tier fallback strategy (v2.7):
        #   1. token_chain_ids from confidences.json   (most reliable)
        #   2. PAE matrix dimension                   (single-chain case)
        #   3. summary 'chain_iptm' length × input_seqs lengths from data.json
        #      (NEW: handles AF3 server outputs whose confidences.json
        #       lacks the per-token chain map)
        #   4. input_seqs lengths from data.json
        #      (NEW: works even if neither confidences.json nor summary
        #       carry chain info, as long as the ppigFinder-generated
        #       data.json is present)
        #   5. model.cif chain parse                  (last resort)
        chain_order = []
        chain_lens  = {}
        chain_layout_source = 'none'  # diagnostic, kept on the result dict

        cif_chains = None
        if model_cif and Path(model_cif).is_file():
            try:
                cif_chains = self._af3a_chains_from_cif(model_cif)
            except Exception:
                cif_chains = None

        if cif_chains:
            # v2.8: use model.cif as the authoritative source for chain
            # identity and residue counts.  The CIF belongs to the exact
            # model displayed by ChimeraX and is robust even when the JSON
            # lacks token_chain_ids or uses a non-standard full_data name.
            chain_order = list(cif_chains.keys())
            chain_lens  = dict(cif_chains)
            chain_layout_source = 'cif'
        elif chain_ids:
            for cid in chain_ids:
                if cid not in chain_lens:
                    chain_lens[cid] = 0
                    chain_order.append(cid)
                chain_lens[cid] += 1
            chain_layout_source = 'confidences'
        elif pae_matrix:
            n = len(pae_matrix)
            chain_lens  = {'A': n}
            chain_order = ['A']
            chain_layout_source = 'pae_matrix'
        else:
            # Tier 3/4 — fall back to the input JSON, possibly cross-checked
            # against summary's chain_iptm count when both are available.
            n_chains_from_summary = (len(chain_iptm)
                                     if isinstance(chain_iptm, list)
                                     else 0)
            n_chains_from_input   = len(input_seqs)
            # Pick the count that's both > 0 and most consistent with the
            # other source.  When both agree, great.  When only one is
            # populated, use it.
            if n_chains_from_input > 0 and n_chains_from_summary > 0:
                n_use = min(n_chains_from_input, n_chains_from_summary)
            else:
                n_use = max(n_chains_from_input, n_chains_from_summary)
            if n_use > 0:
                # Chain letter assignment: A, B, …, Z, AA, AB, …
                def _chain_letter(i):
                    s = ''
                    i += 1
                    while i:
                        i, r = divmod(i - 1, 26)
                        s = chr(65 + r) + s
                    return s
                for i in range(n_use):
                    cid = _chain_letter(i)
                    chain_order.append(cid)
                    if i < len(input_seqs):
                        chain_lens[cid] = len(input_seqs[i])
                    else:
                        # Length unknown — leave 0 so the table cell
                        # reads e.g. "ORF42(?aa)".  Better than blank.
                        chain_lens[cid] = 0
                chain_layout_source = ('input_json' if n_chains_from_input
                                       else 'summary_chain_iptm')

            # Tier 5 — try to derive chain layout from the model.cif
            # (last-resort path; expensive on big files).  Only invoked
            # when previous tiers failed to produce a layout.
            if not chain_order and cif_chains:
                chain_order = list(cif_chains.keys())
                chain_lens  = dict(cif_chains)
                chain_layout_source = 'cif'

            # Tier 6 (v2.6) — derive chain count from chain_pair_pae_min
            # matrix dimensions when all other tiers failed.  This handles
            # DaVinci outputs whose confidences.json lacks token_chain_ids.
            # Chain lengths remain 0 (?aa) but at least A/B labels exist
            # so PAE_min and cp_ipTM can be extracted from the summary.
            if not chain_order and chain_pair_pae_min:
                try:
                    n_from_pae = len(chain_pair_pae_min)
                    if n_from_pae >= 2:
                        chain_order = [chr(65 + i) for i in range(n_from_pae)]
                        chain_lens  = {c: 0 for c in chain_order}
                        chain_layout_source = 'chain_pair_pae_min'
                except (TypeError, ValueError):
                    pass

        n_chains = len(chain_order)

        # ── ORF names from directory name ────────────────────────
        orf_names = [f"ORF{m.group(1)}"
                     for m in re.finditer(r'orf(\d+)',
                                           job_dir.name, re.IGNORECASE)]

        # ── Sequence verification (v2.5 — expanded taxonomy) ──────────
        # Cross-checks the input JSON sequences against the loaded ORFs
        # AND against the folder-name ORF IDs.  v2.5 splits the previous
        # binary 'verified'/'mismatch' into a richer set of statuses so
        # the user can triage problems precisely:
        #
        #   'name_perfect'   — folder name matches sequences exactly,
        #                       in correct chain order
        #   'name_swapped'   — same ORFs but in reversed chain order
        #                       (folder says A_vs_B; data has B in chain
        #                        A and A in chain B)
        #   'name_outdated'  — sequences found in genome but at different
        #                       ORF indices than folder name
        #                       (genome was re-run with new numbering)
        #   'name_partial'   — only some sequences match ORFs in genome
        #   'name_foreign'   — none of the sequences exist in the
        #                       currently-loaded genome (different organism?)
        #   'name_homodimer_hidden' — folder lists 2 different ORFs but
        #                       both chains have the SAME sequence
        #                       (homodimer disguised as heterodimer)
        #   'no_input'       — input JSON absent; cannot verify
        #   'no_orfs'        — no genome loaded
        #   'verified'/'corrected'/'mismatch' — kept for backward compat;
        #                       now mapped onto the new categories
        seq_status   = 'no_input'
        seq_chains   = []        # verified sequences, one per chain
        seq_verified_names = []  # ORF names resolved by sequence (may differ)
        ambiguity_info = None    # populated if any seq matches multiple ORFs
        validation_warnings = [] # human-readable list, surfaced in tooltip

        if input_seqs and hasattr(self, 'orfs') and self.orfs:
            seq_chains = input_seqs

            # Build a lookup: sequence → list of ORF indices (allows
            # detecting paralogs / duplicate ORFs in the genome).
            _orfs_by_len: dict = {}
            for _i, _o in enumerate(self.orfs):
                _p = _o['protein'].strip().rstrip('*').upper()
                _orfs_by_len.setdefault(len(_p), []).append((_i, _p))

            def _find_orfs_by_seq(seq: str):
                """Return list of ORF indices whose protein matches seq exactly."""
                return [_idx
                        for _idx, _p in _orfs_by_len.get(len(seq), [])
                        if _p == seq]

            # All matches per chain (for ambiguity detection)
            all_matches = [_find_orfs_by_seq(s) for s in input_seqs]
            verified_indices = [m[0] if m else -1 for m in all_matches]
            n_with_match     = sum(1 for i in verified_indices if i >= 0)

            # Detect ambiguous matches (paralogs)
            ambig_chains = [(i, ms) for i, ms in enumerate(all_matches)
                            if len(ms) > 1]
            if ambig_chains:
                ambiguity_info = [
                    {
                        'chain_index': ci,
                        'candidates':  [f"ORF{m+1}" for m in ms],
                    }
                    for ci, ms in ambig_chains
                ]
                validation_warnings.append(
                    f"Ambiguous: {len(ambig_chains)} chain(s) match "
                    "multiple ORFs (paralogs/duplicates)")

            # Detect hidden homodimer: folder name implies different ORFs,
            # but the input sequences are all the same.
            unique_input = set(input_seqs)
            if (len(input_seqs) >= 2 and len(unique_input) == 1
                    and len(set(orf_names[:len(input_seqs)])) > 1):
                seq_status = 'name_homodimer_hidden'
                seq_verified_names = ([f"ORF{verified_indices[0]+1}"]
                                       * len(input_seqs)
                                       if verified_indices[0] >= 0
                                       else orf_names[:len(input_seqs)])
                validation_warnings.append(
                    f"Folder lists {len(orf_names)} different ORFs "
                    f"but all chains have the SAME sequence (homodimer)")
            elif n_with_match == 0:
                # None of the sequences exist in the current genome
                seq_status = 'name_foreign'
                validation_warnings.append(
                    "Sequences not found in current genome "
                    "(different organism or re-run needed)")
            elif n_with_match < len(input_seqs):
                # Partial match — some chains hit, others didn't
                seq_status = 'name_partial'
                missing = [f"chain{chr(65+i)}"
                           for i, vi in enumerate(verified_indices)
                           if vi < 0]
                validation_warnings.append(
                    f"Partial match: {n_with_match}/{len(input_seqs)} "
                    f"chains found in genome (missing: {', '.join(missing)})")
                seq_verified_names = [f"ORF{i+1}" if i >= 0 else "?"
                                       for i in verified_indices]
            else:
                # All sequences found in genome
                seq_verified_names = [f"ORF{i+1}" for i in verified_indices]
                # Compare verified names to folder-name names
                folder_names = orf_names[:len(verified_indices)]
                if seq_verified_names == folder_names:
                    seq_status = 'name_perfect'
                elif (sorted(seq_verified_names) == sorted(folder_names)
                      and seq_verified_names != folder_names):
                    # Same set of ORFs, different chain order
                    seq_status = 'name_swapped'
                    validation_warnings.append(
                        f"Chain order swapped: folder has "
                        f"{','.join(folder_names)}; data has "
                        f"{','.join(seq_verified_names)}")
                    orf_names = seq_verified_names
                else:
                    # Different ORF identities — folder probably stale
                    seq_status = 'name_outdated'
                    validation_warnings.append(
                        f"Folder name lists {','.join(folder_names)} "
                        f"but sequences belong to {','.join(seq_verified_names)} "
                        f"(genome may have been re-run)")
                    orf_names = seq_verified_names

        elif input_seqs and not (hasattr(self, 'orfs') and self.orfs):
            # We have sequences but no genome → cannot verify
            seq_status = 'no_orfs'
            seq_chains = input_seqs
        else:
            # No input JSON
            seq_status = 'no_input'

        # v2.5 backward-compat alias for older code paths that still
        # check the legacy three-value status.
        seq_status_legacy = {
            'name_perfect':          'verified',
            'name_swapped':          'corrected',
            'name_outdated':         'corrected',
            'name_partial':          'mismatch',
            'name_foreign':          'mismatch',
            'name_homodimer_hidden': 'mismatch',
            'no_input':              'no_input',
            'no_orfs':               'no_orfs',
        }.get(seq_status, seq_status)

        # Map chain letters → ORF names (A→orf_names[0], B→orf_names[1] …)
        chain_to_orf = {}
        for ci, cid in enumerate(chain_order):
            chain_to_orf[cid] = (orf_names[ci]
                                 if ci < len(orf_names) else cid)

        # ── v2.5 Tier 2: truncation & completeness pre-computation ────
        # We compute these here (BEFORE pair-metrics / motif detection)
        # so that any warning message they produce can be appended to
        # validation_warnings in one place.  The result dict at the
        # bottom just packages them up for the table to consume.
        truncation_info = self._af3a_detect_truncation(
            input_seqs, chain_order, chain_lens)
        if truncation_info:
            for t in truncation_info:
                validation_warnings.append(
                    f"Chain {t['chain']} truncated: "
                    f"{t['modeled']}/{t['expected']} aa modeled "
                    f"({t['missing']} aa missing)")

        completeness = self._af3a_completeness_status({
            'summary':     sum_path,
            'confidences': conf_path,
            'model':       model_cif,
        })
        if completeness == 'no_model':
            validation_warnings.append(
                "model.cif missing — AF3 may have crashed before saving")
        elif completeness == 'no_full_confidences':
            validation_warnings.append(
                "Full confidences.json missing — using fallback for chains/PAE")
        elif completeness == 'empty_or_partial':
            validation_warnings.append(
                "Job folder is incomplete — most output files are absent")

        # ── Inter-chain metrics ─────────────────────────────────
        thresh = self._af3a_thresh_spin.value()
        pair_metrics   = {}   # (cid_A, cid_B) → dict
        best_pae_inter = None
        best_pair      = ('?', '?')

        if pae_matrix and n_chains >= 2:
            try:
                pae_np = np.array(pae_matrix, dtype=float)
                best_pae_min = None   # for best-pair selection by PAE_min
                for i_c, ca in enumerate(chain_order):
                    for j_c, cb in enumerate(chain_order):
                        if i_c >= j_c:
                            continue
                        r0 = sum(chain_lens[chain_order[k]]
                                 for k in range(i_c))
                        r1 = r0 + chain_lens[ca]
                        c0 = sum(chain_lens[chain_order[k]]
                                 for k in range(j_c))
                        c1 = c0 + chain_lens[cb]
                        sub_AB = pae_np[r0:r1, c0:c1]
                        sub_BA = pae_np[c0:c1, r0:r1]
                        # Global mean PAE (diluted by disordered regions)
                        pi = float((sub_AB.mean() + sub_BA.mean()) / 2)
                        # Minimum PAE — best single contact point (focal metric)
                        pae_min_ab = float(sub_AB.min())
                        pae_min_ba = float(sub_BA.min())
                        pae_min_pair = min(pae_min_ab, pae_min_ba)
                        # Contact fraction: residue pairs with PAE < 5Å
                        contact_frac = float((sub_AB < 5.0).mean())
                        # Per-row MIN (not mean) to find focal residues correctly
                        minA = sub_AB.min(axis=1)   # best contact each A-res has w/ any B
                        minB = sub_BA.min(axis=1)   # best contact each B-res has w/ any A
                        mA   = sub_AB.mean(axis=1)  # kept for legacy n_contacts count
                        mB   = sub_BA.mean(axis=1)
                        contacts = int((mA < thresh).sum()
                                       + (mB < thresh).sum())
                        cr = self._af3a_contact_str(
                            minA, minB,
                            chain_to_orf.get(ca, ca),
                            chain_to_orf.get(cb, cb),
                            thresh)
                        # ── Hotspot around PAE minimum ──────────────────────
                        _hs_radius = getattr(self, '_af3a_hotspot_radius', 10)
                        _cp_AB = None
                        if contact_probs:
                            try:
                                import numpy as _np2
                                _cp_full = _np2.array(contact_probs, dtype=float)
                                if _cp_full.shape == pae_np.shape:
                                    _cp_AB = _cp_full[r0:r1, c0:c1]
                            except Exception:
                                pass
                        hotspot = self._compute_pae_hotspot(
                            sub_AB, sub_BA, _cp_AB, radius=_hs_radius)
                        entry = {
                            'pae_inter':      pi,
                            'pae_min':        pae_min_pair,
                            'contact_frac':   contact_frac,
                            'n_contacts':     contacts,
                            'contact_region': cr,
                            'hotspot':        hotspot,
                        }
                        # Attach rich summary pair-data if available
                        try:
                            if chain_pair_iptm:
                                # v29.14 FIX: take max(A→B, B→A) for symmetry,
                                # matching the documented definition
                                #   cp_ipTM = max(chain_pair_iptm[A][B],
                                #                 chain_pair_iptm[B][A])
                                # AF3 normally emits a symmetric array, so this
                                # is a no-op there, but it guards against
                                # asymmetric or partially-filled arrays.
                                try:
                                    _ip_ab = float(chain_pair_iptm[i_c][j_c])
                                    _ip_ba = float(chain_pair_iptm[j_c][i_c])
                                    entry['pair_iptm'] = max(_ip_ab, _ip_ba)
                                except (IndexError, TypeError, ValueError):
                                    entry['pair_iptm'] = float(
                                        chain_pair_iptm[i_c][j_c])
                            if chain_pair_pae_min:
                                # Prefer summary chain_pair_pae_min (more accurate)
                                # v2.6 FIX: take min(A→B, B→A) for symmetry
                                try:
                                    val_ab = float(chain_pair_pae_min[i_c][j_c])
                                    val_ba = float(chain_pair_pae_min[j_c][i_c])
                                    entry['pair_pae_min'] = min(val_ab, val_ba)
                                except (IndexError, TypeError, ValueError):
                                    entry['pair_pae_min'] = float(
                                        chain_pair_pae_min[i_c][j_c])
                                pae_min_pair = entry['pair_pae_min']
                        except (IndexError, TypeError, ValueError):
                            pass
                        pair_metrics[(ca, cb)] = entry
                        # Select best pair by PAE_min (focal) not global mean
                        if best_pae_min is None or pae_min_pair < best_pae_min:
                            best_pae_min   = pae_min_pair
                            best_pae_inter = pi
                            best_pair      = (ca, cb)
            except Exception as e:
                print(f"[AF3 Analysis] inter-metric: {e}")

        # ── Summary-only fallback (v2.6) ─────────────────────────
        # When pae_matrix is absent (e.g. DaVinci confidences.json lacks
        # the 'pae' field), chain_pair_pae_min and chain_pair_iptm from
        # summary_confidences.json are the only available focal metrics.
        # Populate pair_metrics directly from the summary so that PAE_min
        # and cp_ipTM are surfaced even without a full confidences.json.
        if not pair_metrics and chain_pair_pae_min and n_chains >= 2:
            try:
                for i_c, ca in enumerate(chain_order):
                    for j_c, cb in enumerate(chain_order):
                        if i_c >= j_c:
                            continue
                        val_ab = float(chain_pair_pae_min[i_c][j_c])
                        val_ba = float(chain_pair_pae_min[j_c][i_c])
                        pae_min_s = min(val_ab, val_ba)
                        entry = {
                            'pae_inter':      None,
                            'pae_min':        pae_min_s,
                            'pair_pae_min':   pae_min_s,
                            'contact_frac':   None,
                            'n_contacts':     0,
                            'contact_region': '-',
                        }
                        if chain_pair_iptm:
                            # v29.14 FIX: max(A→B, B→A) for symmetry — see the
                            # matching fix in the rich-summary route above.
                            try:
                                _ip_ab = float(chain_pair_iptm[i_c][j_c])
                                _ip_ba = float(chain_pair_iptm[j_c][i_c])
                                entry['pair_iptm'] = max(_ip_ab, _ip_ba)
                            except (IndexError, TypeError, ValueError):
                                try:
                                    entry['pair_iptm'] = float(
                                        chain_pair_iptm[i_c][j_c])
                                except (IndexError, TypeError, ValueError):
                                    pass
                        pair_metrics[(ca, cb)] = entry
                        if best_pae_inter is None or pae_min_s < (
                                pair_metrics.get(best_pair, {}).get(
                                    'pae_min', float('inf'))):
                            best_pair      = (ca, cb)
                            best_pae_inter = None   # not computable
            except Exception as e:
                print(f"[AF3 Analysis] summary-only fallback: {e}")

        best_cr = (pair_metrics[best_pair]['contact_region']
                   if best_pair in pair_metrics else '-')

        # ── ranking_scores.csv (per-sample) ─────────────────────
        ranking_samples = []
        if ranking_csv and Path(ranking_csv).is_file():
            try:
                with open(ranking_csv, encoding='utf-8') as f:
                    reader = csv.DictReader(f)
                    for row in reader:
                        try:
                            ranking_samples.append({
                                'seed':   int(row.get('seed', 0)),
                                'sample': int(row.get('sample', 0)),
                                'ranking_score': float(
                                    row.get('ranking_score', 'nan')),
                            })
                        except (TypeError, ValueError):
                            continue
            except OSError:
                pass

        # ── Motif detection (v1.16) ─────────────────────────────
        # Build a preliminary result dict so _af3a_detect_motifs can
        # use the standard accessors. Detection runs once at parse time
        # using the current toolbar settings; re-runs happen on demand
        # when the user changes a spinbox.
        prelim = {
            'pae_matrix':    pae_matrix,
            'contact_probs': contact_probs,
            'plddt_arr':     plddt_arr,
            'token_res_ids': token_res_ids,
            'chain_order':   chain_order,
            'chain_lens':    chain_lens,
            'chain_to_orf':  chain_to_orf,
        }
        motifs = []
        if not lazy:
            try:
                # Pull live parameters from the toolbar when already built,
            # otherwise fall back to class defaults.
                pae_core = (self._af3a_motif_core_spin.value()
                            if hasattr(self, '_af3a_motif_core_spin')
                            else self._AF3_MOTIF_PAE_CORE)
                pae_ext  = (self._af3a_motif_ext_spin.value()
                            if hasattr(self, '_af3a_motif_ext_spin')
                            else self._AF3_MOTIF_PAE_EXT)
                min_ct   = (self._af3a_motif_contact_spin.value()
                            if hasattr(self, '_af3a_motif_contact_spin')
                            else self._AF3_MOTIF_MIN_CONTACT)
                min_sz   = (self._af3a_motif_size_spin.value()
                            if hasattr(self, '_af3a_motif_size_spin')
                            else self._AF3_MOTIF_MIN_SIZE)
                require_recip = (self._af3a_motif_recip_cb.isChecked()
                                 if hasattr(self, '_af3a_motif_recip_cb')
                                 else True)
                motifs = self._af3a_detect_motifs(
                    prelim, pae_core, pae_ext, min_ct, min_sz,
                    require_reciprocal=require_recip)
            except Exception as e:
                print(f"[AF3 Analysis] motif detection failed for "
                      f"{job_dir.name}: {e}")

        return {
            'job_name':      job_dir.name,
            'job_dir':       str(job_dir),
            # v2.8.1 lazy-loading file paths.  The scan stores only paths
            # and lightweight metrics; heavy matrices are loaded on demand.
            'summary_path':   str(sum_path) if sum_path else None,
            'conf_path':      str(conf_path) if conf_path else None,
            'model_path':     str(model_cif) if model_cif else None,
            'ranking_csv_path': str(ranking_csv) if ranking_csv else None,
            'input_json_path': str(input_json) if input_json else None,
            'heavy_loaded':   (not lazy),
            'orf_names':     orf_names,
            'chain_order':   chain_order,
            'chain_lens':    chain_lens,
            'chain_to_orf':  chain_to_orf,
            'n_chains':      n_chains,
            # Global metrics
            'iptm':          iptm,
            'ptm':           ptm,
            'mean_plddt':    mean_plddt,
            'ranking_score': ranking_score,
            'fraction_disordered': fraction_disordered,
            'has_clash':     has_clash,
            # Per-chain metrics (v1.15)
            'chain_iptm':    chain_iptm,
            'chain_ptm':     chain_ptm,
            # Arrays for plotting
            'pae_matrix':    pae_matrix,
            'contact_probs': contact_probs,
            'plddt_arr':     plddt_arr,
            'token_res_ids': token_res_ids,
            # Pairwise interface metrics
            'pair_metrics':  pair_metrics,
            'pae_inter':     best_pae_inter,
            'best_pair':     best_pair,
            'contact_region': best_cr,
            # Focal metrics (v2.0) — correctly identify domain-limited interactions
            'pae_min_inter':  (pair_metrics[best_pair].get('pair_pae_min') or
                               pair_metrics[best_pair].get('pae_min'))
                              if best_pair in pair_metrics else None,
            'cp_iptm_inter':  pair_metrics[best_pair].get('pair_iptm')
                              if best_pair in pair_metrics else None,
            'contact_frac':   pair_metrics[best_pair].get('contact_frac')
                              if best_pair in pair_metrics else None,
            # Hotspot metrics (v2.7)
            'hotspot':        pair_metrics[best_pair].get('hotspot', {})
                              if best_pair in pair_metrics else {},
            # Motifs (v1.16)
            'motifs':        motifs,
            # Sequence verification (v2.0)
            'seq_status':    seq_status,
            'seq_status_legacy': seq_status_legacy,
            'seq_chains':    seq_chains,
            # v2.7 — diagnostic: which fallback tier produced the chain
            # layout ('confidences', 'pae_matrix', 'input_json',
            # 'summary_chain_iptm', 'cif', or 'none').  Useful when
            # debugging why some folders show n_chains=0.
            'chain_layout_source': chain_layout_source,
            # ── v2.5 Tier 1: fingerprinting & duplicate detection ─────
            'seq_fingerprint':       self._af3a_seq_fingerprint(input_seqs),
            'seq_seed_fingerprint':  self._af3a_seq_seed_fingerprint(
                                          input_seqs, model_seeds),
            'model_seeds':           list(model_seeds),
            # Filled in by _af3a_assign_duplicate_groups after scan:
            'duplicate_group_id':    -1,    # -1 = singleton
            'duplicate_role':        None,  # 'canonical' | 'replicate' | None
            'duplicate_count':       1,
            # ── v2.5 Tier 2: validation taxonomy ──────────────────────
            'completeness':          completeness,
            'truncation_info':       truncation_info,
            'ambiguity_info':        ambiguity_info,
            'validation_warnings':   list(validation_warnings),
            # Extras
            'ranking_samples': ranking_samples,
            'partner_name':  (orf_names[1] if len(orf_names) > 1
                              else chain_order[1] if len(chain_order) > 1
                              else '-'),
        }

    def _af3a_derive_token_plddt(self, atom_plddts, token_chain_ids,
                                  token_res_ids, model_cif):
        """Aggregate per-atom pLDDT → per-residue (token) pLDDT.

        In current AF3 server outputs only 'atom_plddts' is stored. To
        obtain per-residue values we need the atom→residue mapping,
        which is available in the model .cif file (the B_iso column of
        each ATOM record equals the atom pLDDT).

        Returns a list of length len(token_chain_ids) (mean of atoms in
        that residue), or None if a reliable mapping cannot be built.
        """
        if (not atom_plddts or not token_chain_ids
                or not token_res_ids or model_cif is None):
            return None
        if not Path(model_cif).is_file():
            return None

        # Parse atom_site records to get (chain, seq_id) per atom.
        atom_key_order = []   # list of (chain, seq_id) in atom order
        try:
            in_atom_loop = False
            col_names = []
            with open(model_cif, encoding='utf-8', errors='replace') as f:
                for line in f:
                    s = line.strip()
                    if s.startswith('loop_'):
                        col_names = []
                        in_atom_loop = False
                        continue
                    if s.startswith('_atom_site.'):
                        col_names.append(s)
                        in_atom_loop = False
                        continue
                    if col_names and col_names[0] == '_atom_site.group_PDB':
                        if (line.startswith('ATOM')
                                or line.startswith('HETATM')):
                            in_atom_loop = True
                            parts = line.split()
                            # Fixed CIF layout from AF3 (verified):
                            #   parts[6] = label_asym_id (chain)
                            #   parts[8] = label_seq_id  (residue)
                            if len(parts) >= 9:
                                try:
                                    atom_key_order.append(
                                        (parts[6], int(parts[8])))
                                except ValueError:
                                    atom_key_order.append(None)
                        elif in_atom_loop and s and not s.startswith('#'):
                            # End of the atom loop
                            break
        except OSError:
            return None

        if len(atom_key_order) != len(atom_plddts):
            # Mapping couldn't be built reliably → abort
            return None

        # Group atom pLDDTs by (chain, seq_id)
        from collections import defaultdict
        per_res = defaultdict(list)
        for key, plddt in zip(atom_key_order, atom_plddts):
            if key is not None:
                per_res[key].append(plddt)

        # Build per-token array, ordered by token_chain_ids + token_res_ids
        out = []
        for c, r in zip(token_chain_ids, token_res_ids):
            vs = per_res.get((c, int(r)))
            if vs:
                out.append(sum(vs) / len(vs))
            else:
                out.append(None)
        # If too many residues lack mapping, give up (protects the plot)
        if sum(v is None for v in out) > 0.1 * len(out):
            return None
        # Replace any remaining None with 0 (rare)
        return [v if v is not None else 0.0 for v in out]

    # ────────────────────────────────────────────────────────────────
    #  v2.7 — Last-resort chain layout from model.cif
    # ────────────────────────────────────────────────────────────────
    #  Used by `_af3a_parse_job` when neither the confidences.json nor
    #  the input data.json carry chain info.  Counts unique residues
    #  per chain (label_asym_id) by walking ATOM/HETATM records once.
    #
    #  Returns an OrderedDict {chain_id: residue_count}, preserving the
    #  order in which chains first appear in the file.  Returns an
    #  empty dict on any I/O or parse failure (caller falls back to
    #  whichever tier is left, ultimately leaving Chains/Chain IDs blank
    #  rather than crashing).
    def _af3a_chains_from_cif(self, model_cif):
        """Parse {chain_id: residue_count} from an AF3 model .cif file.

        v2.8: header-driven mmCIF parser.  It uses the _atom_site column
        names instead of fixed token positions, so it works with both AF3
        Server and local/DaVinci CIF layouts.  Unique residues are counted
        per label_asym_id, preferring label_seq_id and falling back to
        auth_seq_id when needed.
        """
        from collections import OrderedDict
        chains = OrderedDict()
        if not model_cif:
            return chains
        try:
            cif_path = Path(model_cif)
            if not cif_path.is_file():
                return chains
        except (TypeError, OSError):
            return chains

        try:
            atom_cols = []
            seen_residues = set()
            in_atom_loop = False
            with open(cif_path, encoding='utf-8', errors='replace') as f:
                for line in f:
                    s = line.strip()
                    if not s:
                        continue
                    if s.startswith('loop_'):
                        atom_cols = []
                        in_atom_loop = False
                        continue
                    if s.startswith('_atom_site.'):
                        atom_cols.append(s)
                        continue
                    if atom_cols and (line.startswith('ATOM') or line.startswith('HETATM')):
                        in_atom_loop = True
                        parts = line.split()
                        if len(parts) < len(atom_cols):
                            # mmCIF atom rows generated by AF3 do not contain
                            # quoted whitespace in atom_site values, so split()
                            # is normally safe.  Skip malformed rows.
                            continue
                        col_index = {c: i for i, c in enumerate(atom_cols)}

                        def _get(*names):
                            for name in names:
                                i = col_index.get(name)
                                if i is not None and i < len(parts):
                                    v = parts[i]
                                    if v not in ('.', '?', ''):
                                        return v
                            return None

                        chain_id = _get('_atom_site.label_asym_id',
                                        '_atom_site.auth_asym_id')
                        seq_id = _get('_atom_site.label_seq_id',
                                      '_atom_site.auth_seq_id')
                        comp_id = _get('_atom_site.label_comp_id',
                                       '_atom_site.auth_comp_id') or ''
                        if not chain_id or not seq_id:
                            continue
                        key = (chain_id, seq_id, comp_id)
                        if key in seen_residues:
                            continue
                        seen_residues.add(key)
                        chains[chain_id] = chains.get(chain_id, 0) + 1
                    elif in_atom_loop and s.startswith('#'):
                        break
                    elif in_atom_loop and atom_cols and not (line.startswith('ATOM') or line.startswith('HETATM')):
                        break
        except (OSError, ValueError):
            return OrderedDict()
        return chains

    # ────────────────────────────────────────────────────────────────
    # Motif detection (v1.16)
    # ────────────────────────────────────────────────────────────────
    #
    # Detect 2-D interaction motifs in the off-diagonal quadrants of the
    # PAE matrix using two confidence tiers + contact_probs validation:
    #
    #   core      : PAE < pae_core    (≈ 5 Å, high-confidence interface
    #               residues — the "nucleus" of the motif)
    #   extended  : PAE < pae_ext     (≈ 12 Å, exploratory peripheral
    #               residues adjacent to a core)
    #   contacts  : contact_probs >= min_contact (3-D proximity, from
    #               the *_confidences.json; filters out "aligned but far"
    #               artefacts which low-PAE alone cannot distinguish)
    #
    # The algorithm:
    #   1. Extract the A↔B off-diagonal quadrant (+ B↔A for reciprocity).
    #   2. Build core_mask = (PAE < pae_core) AND (contact_probs >= min_contact)
    #                     — contact filter is applied only if the matrix
    #                       is available, otherwise it defaults to True.
    #   3. Close small gaps with a 3×3 morphological closing.
    #   4. Label connected components. Each ≥ (min_size × min_size)
    #      component is a candidate motif.
    #   5. For each motif, extend its bounding box with neighboring
    #      pixels satisfying the extended tier.
    #   6. Reciprocity: require a B↔A component whose transposed bbox
    #      overlaps ≥ 50 % of the A↔B bbox.
    #   7. Score each motif on a 0-100 scale combining PAE, size,
    #      density, pLDDT and reciprocity.
    #
    # The result is stored on each result dict as res['motifs'], sorted
    # by score descending.

    # Default motif-detection parameters. User overrides these via
    # spinboxes in the AlphaFold Analysis toolbar.
    #
    # Defaults were calibrated against real AF3 server output — a strong
    # interface (e.g. confirmed Y2H hits) typically has core-tier PAE
    # < 5 Å over ≥ 5×5 residues; a borderline interface may only have
    # core-tier PAE < 8 Å. The contact-prob filter is intentionally soft
    # (0.05) because contact_probs are often < 0.2 even at real interfaces.
    _AF3_MOTIF_PAE_CORE    = 8.0    # Å — high-confidence tier
    _AF3_MOTIF_PAE_EXT     = 15.0   # Å — extended / peripheral tier
    _AF3_MOTIF_MIN_CONTACT = 0.05   # probability, 0 disables the filter
    _AF3_MOTIF_MIN_SIZE    = 5      # residues — min dimension of a motif

    @staticmethod
    def _af3a_label_cc(mask):
        """Label connected components in a 2-D boolean mask.

        Uses scipy.ndimage.label when available (fast C implementation),
        otherwise falls back to a pure-numpy BFS. 4-connectivity.

        Returns (labels, n) where labels is an int array of the same
        shape as mask and n is the number of components. Background
        pixels carry label 0; motifs are labelled 1..n.
        """
        if SCIPY_NDIMAGE_AVAILABLE:
            # Default structuring element is 4-connectivity
            labels, n = _scipy_ndimage.label(mask)
            return labels, n
        # Pure-numpy BFS fallback
        h, w = mask.shape
        labels = np.zeros((h, w), dtype=np.int32)
        cur = 0
        # Pre-compute neighbour offsets
        for i in range(h):
            for j in range(w):
                if not mask[i, j] or labels[i, j]:
                    continue
                cur += 1
                stack = [(i, j)]
                labels[i, j] = cur
                while stack:
                    y, x = stack.pop()
                    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w
                                and mask[ny, nx] and not labels[ny, nx]):
                            labels[ny, nx] = cur
                            stack.append((ny, nx))
        return labels, cur

    @staticmethod
    def _af3a_binary_closing(mask, iterations=2):
        """Morphological closing (dilation → erosion) with 3×3 kernel.

        Bridges small gaps so a motif fragmented by one or two noisy
        high-PAE pixels still registers as a single component.
        Falls back to a simple numpy implementation if scipy missing.
        """
        if SCIPY_NDIMAGE_AVAILABLE:
            return _scipy_ndimage.binary_closing(mask, iterations=iterations)
        out = mask.copy()
        for _ in range(iterations):
            # dilate
            d = out.copy()
            d[1:, :]  |= out[:-1, :]
            d[:-1, :] |= out[1:, :]
            d[:, 1:]  |= out[:, :-1]
            d[:, :-1] |= out[:, 1:]
            # erode (4-connected erosion = AND of 4 shifted copies + self)
            e = d.copy()
            e[1:, :]  &= d[:-1, :]
            e[:-1, :] &= d[1:, :]
            e[:, 1:]  &= d[:, :-1]
            e[:, :-1] &= d[:, 1:]
            out = e
        return out


    @staticmethod
    def _compute_pae_hotspot(sub_AB, sub_BA, contact_AB=None, radius: int = 10) -> dict:
        return compute_pae_hotspot(
            sub_AB=sub_AB,
            sub_BA=sub_BA,
            contact_AB=contact_AB,
            radius=radius,
        )

    def _af3a_visible_results(self):
        """Return the AF3 result dicts currently visible in the results table.

        The table stores the result *index* in the job-name cell, not the full
        dict.  The first v29.1 build incorrectly expected a dict in Qt.UserRole,
        which made the Anchor-window summary table stay empty even when the
        selected job had a valid PAE minimum.
        """
        rows = []
        table = getattr(self, "_af3a_table", None)
        if table is None:
            return rows
        for r in range(table.rowCount()):
            try:
                if table.isRowHidden(r):
                    continue
            except Exception:
                pass
            try:
                res = self._af3a_res_for_view_row(r)
            except Exception:
                res = None
            if isinstance(res, dict):
                rows.append(res)
        return rows

    def _af3a_resolve_orf_ref(self, ref):
        """Resolve a chain_to_orf entry to the real ORF dict.

        chain_to_orf normally stores ORF *names* (e.g. 'ORF200'); the
        anchor-window code needs the ORF dict (which holds 'domains' and any
        fragment-offset metadata). Accepts a dict (returned as-is), an
        'ORF<n>' name, or a plain index-bearing string. Returns a dict or None.
        """
        if isinstance(ref, dict):
            return ref
        if not isinstance(ref, str) or not ref:
            return None
        orfs = getattr(self, 'orfs', None) or []
        # Fast path: 'ORF<n>' is 1-based into self.orfs.
        m = re.match(r'^ORF(\d+)$', ref.strip())
        if m:
            idx = int(m.group(1)) - 1
            if 0 <= idx < len(orfs) and isinstance(orfs[idx], dict):
                return orfs[idx]
        # Fallback: match by stored orf_name / locus.
        for o in orfs:
            if isinstance(o, dict) and (o.get('orf_name') == ref or o.get('locus') == ref):
                return o
        return None

    def _af3a_chain_domains(self, chain_orf, seq_len=None):
        out = []
        if not isinstance(chain_orf, dict):
            return out
        for d in (chain_orf.get("domains") or []):
            if not isinstance(d, dict):
                continue
            st = d.get("start", d.get("ali_from"))
            en = d.get("end", d.get("ali_to"))
            try:
                st = int(st); en = int(en)
            except Exception:
                continue
            if en < st:
                st, en = en, st
            if seq_len:
                st = max(1, min(int(seq_len), st))
                en = max(1, min(int(seq_len), en))
            label = d.get("name") or d.get("acc") or d.get("domain") or d.get("kind") or "domain"
            out.append({"start": st, "end": en, "label": str(label)})
        return out

    def _af3a_chain_offset_aa(self, chain_orf, job_name=None, side=None):
        """Return the 0-based residue offset of a chain within its full protein.

        Priority:
          1. explicit fragment-offset keys on the ORF dict (if present), then
          2. coordinates parsed from a fragmented AF3 job name of the form
             '<A>_<sA>-<eA>_vs_<B>_<sB>-<eB>...' (side 'a' uses sA, 'b' uses sB).
        Falls back to 0 (full-length protein) when nothing is found.
        """
        if isinstance(chain_orf, dict):
            for key in ("fragment_aa_start", "protein_start_aa", "parent_aa_start",
                        "full_protein_aa_start", "aa_offset", "fragment_start_aa"):
                try:
                    val = chain_orf.get(key)
                    if val is not None:
                        return max(0, int(val) - 1)
                except Exception:
                    pass
        # Parse coordinates from a fragmented job name as a fallback.
        if job_name and side in ('a', 'b'):
            try:
                m = re.match(r'^.+?_(\d+)-(\d+)_vs_.+?_(\d+)-(\d+)', str(job_name))
                if m:
                    if side == 'a':
                        return max(0, int(m.group(1)) - 1)
                    else:
                        return max(0, int(m.group(3)) - 1)
            except Exception:
                pass
        return 0

    def _af3a_pae_color(self, value):
        try:
            v = float(value)
        except Exception:
            return "#9ca3af"
        if math.isnan(v):
            return "#9ca3af"
        if v <= 3:   return "#1d4ed8"
        if v <= 5:   return "#06b6d4"
        if v <= 10:  return "#22c55e"
        if v <= 15:  return "#eab308"
        if v <= 20:  return "#f97316"
        return "#ef4444"

    def _af3a_locate_anchor_window(self, res, chain_a=None, chain_b=None, radius=None):
        radius = int(radius if radius is not None else getattr(self, '_af3a_hotspot_radius', 10))
        if chain_a is None or chain_b is None:
            bp = res.get('best_pair') or ()
            if len(bp) == 2:
                chain_a, chain_b = bp
        if not chain_a or not chain_b:
            return None
        pae = res.get('pae_matrix')
        if pae is None:
            return None
        try:
            pae = np.asarray(pae, dtype=float)
        except Exception:
            return None
        chain_ids = list(res.get('chain_ids') or res.get('chain_order') or [])
        seqs_by_chain = self._af3a_seq_map_for_result(res)
        lens = res.get('chain_lengths') or res.get('chain_lens') or {}
        if chain_a not in chain_ids or chain_b not in chain_ids:
            return None
        seq_a = str(seqs_by_chain.get(chain_a) or '')
        seq_b = str(seqs_by_chain.get(chain_b) or '')
        if not seq_a or not seq_b:
            return None
        spans = {}
        cur = 0
        for cid in chain_ids:
            clen = int(lens.get(cid) or len(seqs_by_chain.get(cid) or ''))
            spans[cid] = (cur, cur + clen)
            cur += clen
        a0, a1 = spans[chain_a]
        b0, b1 = spans[chain_b]
        sub_ab = pae[a0:a1, b0:b1]
        sub_ba = pae[b0:b1, a0:a1]
        if sub_ab.size == 0 or sub_ba.size == 0:
            return None
        try:
            idx_ab = np.unravel_index(np.nanargmin(sub_ab), sub_ab.shape)
            val_ab = float(sub_ab[idx_ab])
        except Exception:
            idx_ab = None; val_ab = float('inf')
        try:
            idx_ba = np.unravel_index(np.nanargmin(sub_ba), sub_ba.shape)
            val_ba = float(sub_ba[idx_ba])
        except Exception:
            idx_ba = None; val_ba = float('inf')
        if idx_ab is None and idx_ba is None:
            return None
        if val_ab <= val_ba:
            a_anchor = int(idx_ab[0]) + 1
            b_anchor = int(idx_ab[1]) + 1
            pae_min = val_ab
        else:
            b_anchor = int(idx_ba[0]) + 1
            a_anchor = int(idx_ba[1]) + 1
            pae_min = val_ba
        a_start = max(1, a_anchor - radius); a_end = min(len(seq_a), a_anchor + radius)
        b_start = max(1, b_anchor - radius); b_end = min(len(seq_b), b_anchor + radius)
        cmap = res.get('chain_to_orf') or {}
        orf_a_ref = cmap.get(chain_a) if isinstance(cmap, dict) else None
        orf_b_ref = cmap.get(chain_b) if isinstance(cmap, dict) else None
        # chain_to_orf usually stores ORF *names* (strings). Resolve each to
        # the real ORF dict (which carries 'domains') so domain boxes and any
        # fragment offset metadata become available. Pass through dicts as-is.
        orf_a = self._af3a_resolve_orf_ref(orf_a_ref)
        orf_b = self._af3a_resolve_orf_ref(orf_b_ref)
        off_a = self._af3a_chain_offset_aa(orf_a, job_name=res.get('job_name'), side='a')
        off_b = self._af3a_chain_offset_aa(orf_b, job_name=res.get('job_name'), side='b')
        name_a = (orf_a.get('orf_name') or orf_a.get('locus') if isinstance(orf_a, dict) else None) \
                 or (orf_a_ref if isinstance(orf_a_ref, str) else None) or chain_a
        name_b = (orf_b.get('orf_name') or orf_b.get('locus') if isinstance(orf_b, dict) else None) \
                 or (orf_b_ref if isinstance(orf_b_ref, str) else None) or chain_b
        return {
            'job_name': res.get('job_name') or '',
            'pair': f'{chain_a}-{chain_b}',
            'chain_a': chain_a, 'chain_b': chain_b,
            'chain_a_name': name_a, 'chain_b_name': name_b,
            'seq_a': seq_a[a_start-1:a_end], 'seq_b': seq_b[b_start-1:b_end],
            'a_start': a_start, 'a_end': a_end, 'b_start': b_start, 'b_end': b_end,
            'a_full_start': off_a + a_start, 'a_full_end': off_a + a_end,
            'b_full_start': off_b + b_start, 'b_full_end': off_b + b_end,
            'a_anchor': a_anchor, 'b_anchor': b_anchor,
            'a_full_anchor': off_a + a_anchor, 'b_full_anchor': off_b + b_anchor,
            'pae_min': pae_min, 'color': self._af3a_pae_color(pae_min),
            'len_a': len(seq_a), 'len_b': len(seq_b),
            'domains_a': self._af3a_chain_domains(orf_a, len(seq_a)),
            'domains_b': self._af3a_chain_domains(orf_b, len(seq_b)),
        }

    def _af3a_anchor_windows_visible_results(self):
        out = []
        for res in self._af3a_visible_results():
            try:
                heavy = self._af3a_ensure_heavy_loaded(res)
            except Exception:
                heavy = None
            if not heavy:
                continue
            aw = self._af3a_locate_anchor_window(heavy, radius=getattr(self, '_af3a_hotspot_radius', 10))
            if aw:
                out.append(aw)
        out.sort(key=lambda x: (float(x.get('pae_min', 9999.0)), x.get('job_name', '')))
        return out

    def _af3a_build_anchor_window_table(self, parent_layout):
        anchors = self._af3a_anchor_windows_visible_results()
        box = QFrame()
        box.setFrameShape(QFrame.Shape.StyledPanel if QT_VERSION == 6 else QFrame.StyledPanel)
        v = QVBoxLayout(box)
        v.setContentsMargins(8, 8, 8, 8)
        head = QHBoxLayout()
        lbl = QLabel('Anchor-window summary (filtered rows)')
        lbl.setStyleSheet('font-weight:600;')
        head.addWidget(lbl)
        head.addStretch(1)
        btn = QPushButton('Export FASTA / TSV')
        btn.setToolTip('Export the visible anchor windows as paired FASTA or as a two-column TSV file.')
        btn.clicked.connect(self._af3a_export_anchor_windows)
        head.addWidget(btn)
        v.addLayout(head)
        help_lbl = QLabel('Each row uses the absolute inter-chain PAE minimum as an anchor and reports a ±N residue window around it. Only the currently filtered jobs are included.')
        help_lbl.setWordWrap(True)
        help_lbl.setStyleSheet('color:#4b5563; font-size:11px;')
        v.addWidget(help_lbl)
        table = QTableWidget(0, 8)
        table.setHorizontalHeaderLabels(['Rank', 'Job', 'Pair', 'PAE_min', 'Chain A region', 'Seq A', 'Chain B region', 'Seq B'])
        table.verticalHeader().setVisible(False)
        if QT_VERSION == 6:
            table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
            table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        else:
            table.setEditTriggers(QAbstractItemView.NoEditTriggers)
            table.setSelectionBehavior(QAbstractItemView.SelectRows)
        table.setAlternatingRowColors(True)
        table.setWordWrap(False)
        table.setSortingEnabled(False)
        table.setMinimumHeight(220)
        for i, aw in enumerate(anchors, start=1):
            row = table.rowCount()
            table.insertRow(row)
            vals = [
                str(i), aw.get('job_name', ''), aw.get('pair', ''),
                f"{aw.get('pae_min', float('nan')):.2f}" if aw.get('pae_min') is not None else '',
                f"{aw.get('chain_a_name', aw.get('chain_a',''))}:{aw.get('a_full_start', aw.get('a_start',''))}-{aw.get('a_full_end', aw.get('a_end',''))}",
                aw.get('seq_a', ''),
                f"{aw.get('chain_b_name', aw.get('chain_b',''))}:{aw.get('b_full_start', aw.get('b_start',''))}-{aw.get('b_full_end', aw.get('b_end',''))}",
                aw.get('seq_b', ''),
            ]
            for col, val in enumerate(vals):
                item = QTableWidgetItem(val)
                if col == 0:
                    item.setData(Qt.ItemDataRole.UserRole if QT_VERSION == 6 else Qt.UserRole, aw)
                table.setItem(row, col, item)
            bg = QColor(aw.get('color', '#9ca3af')).lighter(180)
            for col in range(table.columnCount()):
                it = table.item(row, col)
                if it is not None:
                    it.setBackground(bg)
        hdr = table.horizontalHeader()
        try:
            if QT_VERSION == 6:
                _RTC = QHeaderView.ResizeMode.ResizeToContents
                _STR = QHeaderView.ResizeMode.Stretch
            else:
                _RTC = QHeaderView.ResizeToContents
                _STR = QHeaderView.Stretch
            for _c in (0, 2, 3, 4, 6):
                hdr.setSectionResizeMode(_c, _RTC)
            for _c in (1, 5, 7):
                hdr.setSectionResizeMode(_c, _STR)
        except Exception:
            pass
        self._af3a_anchor_table = table
        self._af3a_anchor_rows = anchors
        v.addWidget(table)
        parent_layout.addWidget(box)

    def _af3a_export_anchor_windows(self):
        anchors = getattr(self, '_af3a_anchor_rows', None) or self._af3a_anchor_windows_visible_results()
        if not anchors:
            QMessageBox.information(self, 'Export anchor windows', 'No filtered anchor-window entries are available for export.')
            return
        path, flt = QFileDialog.getSaveFileName(
            self, 'Export anchor windows',
            os.path.join(os.path.expanduser('~'), 'af3_anchor_windows.tsv'),
            'Tab-separated paired FASTA (*.tsv);;FASTA (*.fasta *.fa)'
        )
        if not path:
            return
        try:
            if 'FASTA' in flt and not path.lower().endswith('.tsv'):
                if not path.lower().endswith(('.fasta', '.fa')):
                    path += '.fasta'
                with open(path, 'w', encoding='utf-8') as fh:
                    for aw in anchors:
                        h1 = f">{aw.get('job_name','job')}|{aw.get('pair','pair')}|A|{aw.get('chain_a_name',aw.get('chain_a','A'))}|{aw.get('a_full_start',aw.get('a_start',1))}-{aw.get('a_full_end',aw.get('a_end',1))}|PAEmin={aw.get('pae_min', float('nan')):.2f}"
                        h2 = f">{aw.get('job_name','job')}|{aw.get('pair','pair')}|B|{aw.get('chain_b_name',aw.get('chain_b','B'))}|{aw.get('b_full_start',aw.get('b_start',1))}-{aw.get('b_full_end',aw.get('b_end',1))}|PAEmin={aw.get('pae_min', float('nan')):.2f}"
                        fh.write(h1 + '\n' + aw.get('seq_a','') + '\n')
                        fh.write(h2 + '\n' + aw.get('seq_b','') + '\n')
            else:
                if not path.lower().endswith('.tsv'):
                    path += '.tsv'
                with open(path, 'w', encoding='utf-8') as fh:
                    fh.write('A_FASTA\tB_FASTA\n')
                    for aw in anchors:
                        fa = f">{aw.get('job_name','job')}|{aw.get('pair','pair')}|A|{aw.get('chain_a_name',aw.get('chain_a','A'))}|{aw.get('a_full_start',aw.get('a_start',1))}-{aw.get('a_full_end',aw.get('a_end',1))}|PAEmin={aw.get('pae_min', float('nan')):.2f}\n{aw.get('seq_a','')}"
                        fb = f">{aw.get('job_name','job')}|{aw.get('pair','pair')}|B|{aw.get('chain_b_name',aw.get('chain_b','B'))}|{aw.get('b_full_start',aw.get('b_start',1))}-{aw.get('b_full_end',aw.get('b_end',1))}|PAEmin={aw.get('pae_min', float('nan')):.2f}\n{aw.get('seq_b','')}"
                        fh.write(fa.replace('\t',' ').replace('\n',' ') + '\t' + fb.replace('\t',' ').replace('\n',' ') + '\n')
            QMessageBox.information(self, 'Export anchor windows', f'Export completed:\n{path}')
        except Exception as e:
            QMessageBox.warning(self, 'Export anchor windows', f'Failed to export anchor windows:\n{e}')

    def _af3a_build_selected_interface_schematic(self, parent_layout, res):
        aw = self._af3a_locate_anchor_window(res, radius=getattr(self, '_af3a_hotspot_radius', 10))
        if not aw:
            return
        frame = QFrame()
        frame.setFrameShape(QFrame.Shape.StyledPanel if QT_VERSION == 6 else QFrame.StyledPanel)
        v = QVBoxLayout(frame)
        v.setContentsMargins(8, 8, 8, 8)
        title = QLabel('Protein architecture and probable interface region')
        title.setStyleSheet('font-weight:600;')
        v.addWidget(title)
        sub = QLabel(
            f"Selected pair: {aw.get('chain_a_name', aw.get('chain_a','A'))} vs {aw.get('chain_b_name', aw.get('chain_b','B'))}. "
            f"Both proteins are drawn to the same scale (the longer one fills the track; "
            f"the shorter is proportional). Colored traces mark the probable interface window "
            f"around the absolute inter-chain PAE minimum (PAEmin={aw.get('pae_min', float('nan')):.2f} Å)."
        )
        sub.setWordWrap(True)
        sub.setStyleSheet('color:#4b5563; font-size:11px;')
        v.addWidget(sub)
        fig = Figure(figsize=(8.0, 2.6), dpi=110)
        ax = fig.add_subplot(111)
        canvas = FigureCanvas(fig)
        x0, x1 = 0.12, 0.95
        ax.set_xlim(0, 1)
        ax.set_ylim(-0.05, 1.95)
        ax.axis('off')

        # Common scale: the LONGER protein of this pair fills the whole track
        # (x0 → x1); the shorter one is drawn proportionally. The same scale
        # is applied to domain boxes, the interface window and the anchor dot,
        # so everything stays aligned across the two chains.
        ref_len = max(1, int(aw.get('len_a', 1)), int(aw.get('len_b', 1)))

        def _draw_track(y, name, length, domains, wstart, wend, anchor_pos, color, seq_text, pos_text):
            length = max(1, int(length))
            # Fraction of the full track width this protein occupies.
            track_w = (x1 - x0) * (length / ref_len)
            xend = x0 + track_w

            def _xpos(res):
                # Map a 1-based residue to an x coordinate on THIS protein's
                # scaled track (shared scale via ref_len).
                return x0 + (max(1, res) - 1) / ref_len * (x1 - x0)

            ax.text(0.01, y + 0.02, name, fontsize=9.5, fontweight='bold', ha='left', va='center')
            ax.hlines(y, x0, xend, colors='#111827', linewidth=1.5)
            ax.text(xend + 0.01, y, str(length), fontsize=8, color='#374151', va='center', ha='left')
            if domains:
                cmap = plt.get_cmap('tab20')
                for i, d in enumerate(domains):
                    ds = _xpos(d['start'])
                    de = _xpos(d['end'])
                    rect = patches.Rectangle((ds, y + 0.06), max(0.008, de - ds), 0.17,
                                             facecolor=cmap(i % 20), edgecolor='#374151',
                                             linewidth=0.7, alpha=0.92)
                    ax.add_patch(rect)
                    if de - ds > 0.065:
                        ax.text((ds + de) / 2.0, y + 0.145, d['label'], fontsize=6.9,
                                ha='center', va='center', color='black', clip_on=True)
            ws = _xpos(wstart)
            we = _xpos(wend)
            ax.hlines(y - 0.15, ws, we, colors=color, linewidth=4.0)
            ap = _xpos(anchor_pos)
            ax.plot([ap], [y - 0.15], 'o', color=color, markersize=4.8)
            ax.text(0.12, y - 0.34, f"{pos_text}: {seq_text}", fontsize=8.0, color='#111827', ha='left', va='center')
        _draw_track(1.28, aw.get('chain_a_name', aw.get('chain_a','A')), aw['len_a'], aw['domains_a'], aw['a_start'], aw['a_end'], aw['a_anchor'], aw['color'], aw['seq_a'], f"{aw['a_full_start']}-{aw['a_full_end']}")
        _draw_track(0.45, aw.get('chain_b_name', aw.get('chain_b','B')), aw['len_b'], aw['domains_b'], aw['b_start'], aw['b_end'], aw['b_anchor'], aw['color'], aw['seq_b'], f"{aw['b_full_start']}-{aw['b_full_end']}")
        fig.tight_layout(pad=0.5)
        v.addWidget(canvas)
        parent_layout.addWidget(frame)

    @classmethod
    def _af3a_detect_motifs_one_pair(cls, pae_AB, pae_BA, contact_AB,
                                       plddt_A, plddt_B,
                                       pae_core, pae_ext, min_contact,
                                       min_size, require_reciprocal,
                                       offset_a=0, offset_b=0,
                                       token_res_A=None,
                                       token_res_B=None,
                                       res_id_to_res_num=None):
        """Detect motifs in a single A↔B quadrant pair.

        Parameters
        ----------
        pae_AB : 2-D ndarray (len_A × len_B)
            Off-diagonal PAE, rows = chain A residues, cols = chain B.
        pae_BA : 2-D ndarray (len_B × len_A)
            Transposed quadrant, for reciprocity validation.
        contact_AB : 2-D ndarray or None (len_A × len_B)
            Contact probabilities. None disables the contact filter.
        plddt_A, plddt_B : 1-D ndarray or None
            Per-residue pLDDT for chains A, B.
        pae_core, pae_ext : float
            PAE thresholds in Å for the core (strict) and extended
            (peripheral) tiers.
        min_contact : float
            Minimum contact probability for the core mask. 0 disables.
        min_size : int
            Minimum width AND height (in residues) for a surviving motif.
        require_reciprocal : bool
            Drop motifs without a matching component in the B↔A quadrant.
        offset_a, offset_b : int
            Running positional offset of this quadrant inside the full
            PAE matrix — used so plot overlays can draw rectangles in
            the correct absolute position.
        token_res_A, token_res_B : 1-D ndarray or None
            The AF3 per-residue numbers for chain A / B (from
            token_res_ids). When provided, motif positions are reported
            in the native chain-local numbering (restarting at 1 per
            chain) that the AF3 server shows.

        Returns
        -------
        list[dict]  sorted by `score` desc.
        """
        if pae_AB is None or pae_AB.size == 0:
            return []

        len_A, len_B = pae_AB.shape
        use_contact = (contact_AB is not None
                       and contact_AB.shape == pae_AB.shape
                       and min_contact > 0.0)

        # 1) Core mask — low PAE AND (optionally) high contact prob
        core_mask = (pae_AB < pae_core)
        if use_contact:
            core_mask &= (contact_AB >= min_contact)

        # 2) Close 1-2 pixel gaps
        core_mask = cls._af3a_binary_closing(core_mask, iterations=1)

        # 3) Reciprocity mask on the transposed quadrant
        if pae_BA is not None and pae_BA.shape == (len_B, len_A):
            recip_mask = (pae_BA < pae_core)
            recip_mask = cls._af3a_binary_closing(recip_mask, iterations=1)
        else:
            recip_mask = None

        # 4) Label connected components
        labels, n_cc = cls._af3a_label_cc(core_mask)
        if n_cc == 0:
            return []

        # 5) Extended mask (peripheral residues, for bbox extension)
        ext_mask = (pae_AB < pae_ext)

        motifs = []
        for k in range(1, n_cc + 1):
            comp_rows, comp_cols = np.where(labels == k)
            if len(comp_rows) == 0:
                continue
            r0, r1 = int(comp_rows.min()), int(comp_rows.max())
            c0, c1 = int(comp_cols.min()), int(comp_cols.max())
            core_h = r1 - r0 + 1
            core_w = c1 - c0 + 1
            if core_h < min_size or core_w < min_size:
                continue

            # 5a) Extend bbox with contiguous low-PAE peripheral cells
            #     (grow the bbox while any edge row/col has ≥ 1 ext pixel)
            while r0 > 0 and ext_mask[r0 - 1, c0:c1 + 1].any():
                r0 -= 1
            while r1 < len_A - 1 and ext_mask[r1 + 1, c0:c1 + 1].any():
                r1 += 1
            while c0 > 0 and ext_mask[r0:r1 + 1, c0 - 1].any():
                c0 -= 1
            while c1 < len_B - 1 and ext_mask[r0:r1 + 1, c1 + 1].any():
                c1 += 1

            block_pae = pae_AB[r0:r1 + 1, c0:c1 + 1]
            block_core_mask = (block_pae < pae_core)

            mean_pae = float(block_pae.mean())
            min_pae  = float(block_pae.min())
            density  = float(block_core_mask.mean())   # % core pixels
            h = r1 - r0 + 1
            w = c1 - c0 + 1
            area = h * w

            # Mean contact prob in the motif (only if available)
            if use_contact:
                mean_contact = float(contact_AB[r0:r1+1, c0:c1+1].mean())
                max_contact  = float(contact_AB[r0:r1+1, c0:c1+1].max())
            else:
                mean_contact = None
                max_contact  = None

            # Per-chain pLDDT for residues inside the motif
            plddt_mA = None
            plddt_mB = None
            if plddt_A is not None and len(plddt_A) >= r1 + 1:
                plddt_mA = float(np.mean(plddt_A[r0:r1 + 1]))
            if plddt_B is not None and len(plddt_B) >= c1 + 1:
                plddt_mB = float(np.mean(plddt_B[c0:c1 + 1]))
            plddt_mean = (
                None if plddt_mA is None and plddt_mB is None
                else (
                    (plddt_mA or 0.0) + (plddt_mB or 0.0)
                ) / max(1, (plddt_mA is not None) + (plddt_mB is not None))
            )

            # Reciprocity: does the transposed region in B↔A also have
            # a low-PAE block? Require ≥ 50 % overlap.
            reciprocal = False
            recip_overlap = 0.0
            if recip_mask is not None:
                recip_block = recip_mask[c0:c1 + 1, r0:r1 + 1]
                recip_overlap = float(recip_block.mean())
                reciprocal = recip_overlap >= 0.5
            if require_reciprocal and recip_mask is not None and not reciprocal:
                continue

            # Combined score (0-100). Weights chosen to match:
            #   confidence 35 %, size 20 %, density 20 %,
            #   pLDDT 15 %, reciprocity 10 %
            conf_term = max(0.0, 1.0 - mean_pae / max(pae_ext, 0.1))
            size_term = min(min(h, w) / 50.0, 1.0)   # saturates at 50
            dens_term = density
            if plddt_mean is not None:
                plddt_term = max(0.0, (plddt_mean - 50.0) / 50.0)
            else:
                plddt_term = 0.5   # neutral if unknown
            recip_term = 1.0 if reciprocal else 0.0
            score = 100.0 * (
                0.35 * conf_term
                + 0.20 * size_term
                + 0.20 * dens_term
                + 0.15 * plddt_term
                + 0.10 * recip_term)

            # Convert row/col indices to user-facing residue numbers
            def _resnum(arr, idx):
                if arr is not None and 0 <= idx < len(arr):
                    try:
                        return int(arr[idx])
                    except (TypeError, ValueError):
                        pass
                return idx + 1  # 1-based running

            a_start = _resnum(token_res_A, r0)
            a_end   = _resnum(token_res_A, r1)
            b_start = _resnum(token_res_B, c0)
            b_end   = _resnum(token_res_B, c1)

            motifs.append({
                # Bounding box in LOCAL quadrant coordinates
                'a_row0': r0, 'a_row1': r1,
                'b_col0': c0, 'b_col1': c1,
                # Residue numbering (native, per-chain)
                'a_start': a_start, 'a_end': a_end,
                'b_start': b_start, 'b_end': b_end,
                # Global (absolute) indices — for plot overlays
                'abs_row0': r0 + offset_a, 'abs_row1': r1 + offset_a,
                'abs_col0': c0 + offset_b, 'abs_col1': c1 + offset_b,
                # Metrics
                'width':  w,   'height': h,   'area': area,
                'mean_pae': mean_pae, 'min_pae': min_pae,
                'density': density,
                'mean_contact': mean_contact, 'max_contact': max_contact,
                'plddt_A': plddt_mA, 'plddt_B': plddt_mB,
                'plddt_mean': plddt_mean,
                'reciprocal': reciprocal,
                'recip_overlap': recip_overlap,
                'score': score,
            })

        motifs.sort(key=lambda m: -m['score'])
        return motifs

    @classmethod
    def _af3a_detect_motifs(cls, res: dict,
                             pae_core: float, pae_ext: float,
                             min_contact: float, min_size: int,
                             require_reciprocal: bool = True) -> list:
        """Detect motifs for every off-diagonal pair in one AF3 result.

        Returns a flat list of motifs with a 'pair' key identifying
        which chain pair the motif belongs to. Sorted by score.
        """
        pae_matrix    = res.get('pae_matrix')
        contact_probs = res.get('contact_probs')
        plddt_arr     = res.get('plddt_arr')
        token_res_ids = res.get('token_res_ids')
        chain_order   = res.get('chain_order') or []
        chain_lens    = res.get('chain_lens') or {}
        chain_to_orf  = res.get('chain_to_orf') or {}

        if (not pae_matrix or len(chain_order) < 2
                or not NUMPY_AVAILABLE):
            return []

        pae_np = np.array(pae_matrix, dtype=float)
        contact_np = (np.array(contact_probs, dtype=float)
                      if contact_probs else None)
        plddt_np = (np.array(plddt_arr, dtype=float)
                    if plddt_arr else None)
        tri_np = (np.array(token_res_ids)
                  if token_res_ids else None)

        # Running offsets for each chain (for mapping into full matrix)
        chain_offsets = {}
        acc = 0
        for cid in chain_order:
            chain_offsets[cid] = acc
            acc += chain_lens.get(cid, 0)

        all_motifs = []
        for i_c, ca in enumerate(chain_order):
            for j_c, cb in enumerate(chain_order):
                if i_c >= j_c:
                    continue  # only upper-triangle inter-chain
                r0 = chain_offsets[ca]; r1 = r0 + chain_lens[ca]
                c0 = chain_offsets[cb]; c1 = c0 + chain_lens[cb]

                pae_AB = pae_np[r0:r1, c0:c1]
                pae_BA = pae_np[c0:c1, r0:r1]
                cont_AB = (contact_np[r0:r1, c0:c1]
                           if contact_np is not None else None)
                plddt_A = (plddt_np[r0:r1]
                           if plddt_np is not None else None)
                plddt_B = (plddt_np[c0:c1]
                           if plddt_np is not None else None)
                tri_A   = (tri_np[r0:r1]
                           if tri_np is not None else None)
                tri_B   = (tri_np[c0:c1]
                           if tri_np is not None else None)

                motifs = cls._af3a_detect_motifs_one_pair(
                    pae_AB, pae_BA, cont_AB,
                    plddt_A, plddt_B,
                    pae_core=pae_core, pae_ext=pae_ext,
                    min_contact=min_contact,
                    min_size=min_size,
                    require_reciprocal=require_reciprocal,
                    offset_a=r0, offset_b=c0,
                    token_res_A=tri_A, token_res_B=tri_B)

                # Attach pair identity & friendly names
                name_A = chain_to_orf.get(ca, ca)
                name_B = chain_to_orf.get(cb, cb)
                for m in motifs:
                    m['pair']    = (ca, cb)
                    m['chain_A'] = ca
                    m['chain_B'] = cb
                    m['name_A']  = name_A
                    m['name_B']  = name_B
                    m['label']   = (f"{name_A}[{m['a_start']}-{m['a_end']}] "
                                    f"× {name_B}[{m['b_start']}-{m['b_end']}]")
                all_motifs.extend(motifs)

        all_motifs.sort(key=lambda m: -m['score'])
        # Assign stable rank indices (for plot overlay labels)
        for rank, m in enumerate(all_motifs, start=1):
            m['rank'] = rank
        return all_motifs

    @staticmethod
    def _af3a_contact_str(mean_A, mean_B, name_A, name_B, thresh):
        """Build a human-readable contact region string."""
        def _ranges(indices, prefix):
            if not len(indices):
                return ''
            ranges, s, e = [], int(indices[0]), int(indices[0])
            for idx in indices[1:]:
                idx = int(idx)
                if idx == e + 1:
                    e = idx
                else:
                    ranges.append(f"res{s+1}-{e+1}" if e > s else f"res{s+1}")
                    s = e = idx
            ranges.append(f"res{s+1}-{e+1}" if e > s else f"res{s+1}")
            return f"{prefix}: {', '.join(ranges[:3])}"

        # Use the supplied per-residue arrays directly (caller now passes min,
        # not mean, so low values correctly flag focal-contact residues)
        c5_A  = np.where(mean_A < 5.0)[0]
        c10_A = np.where(mean_A < 10.0)[0]
        c5_B  = np.where(mean_B < 5.0)[0]
        c10_B = np.where(mean_B < 10.0)[0]

        if not len(c5_A) and not len(c10_A):
            return f"no contact detected with {name_B}"

        parts = []
        if len(c5_A):
            parts.append(f"{_ranges(c5_A, name_A)} <5Å")
        elif len(c10_A):
            parts.append(f"{_ranges(c10_A, name_A)} <10Å")
        if len(c5_B):
            parts.append(f"{_ranges(c5_B, name_B)} <5Å")
        elif len(c10_B):
            parts.append(f"{_ranges(c10_B, name_B)} <10Å")
        return ' | '.join(parts) if parts else (
            f"not relevant interaction found with {name_B}")

    def _af3a_extract_orf_order_value(self, res):
        """Return a numeric ORF ordering key for bait-vs-prey screens.

        In large virtual two-hybrid screens the bait is usually the first
        ORF and the prey is the second one, for example:

            orf2601_vs_orf1_interactome
            orf2601_vs_orf2_interactome
            ...

        Plain string sorting places ORF100 before ORF2.  This helper
        extracts the second/prey ORF number and stores it in a numeric
        column so Qt can sort ORF1, ORF2, ORF3... correctly.
        """
        candidates = []

        # Prefer the displayed chain order. For heterodimers, chain 2 is
        # normally the prey/candidate ORF in bait-vs-genome screens.
        try:
            chain_order = list(res.get('chain_order') or [])
            chain_to_orf = res.get('chain_to_orf') or {}
            if len(chain_order) >= 2:
                name = str(chain_to_orf.get(chain_order[1], ''))
                m = re.search(r'(?i)\borf[_-]?(\d+)\b', name)
                if m:
                    return int(m.group(1))
        except Exception:
            pass

        # Fall back to the job name.  In names such as
        # fold_orf4199_vs_orf4203_down4, the second number is the prey.
        job_name = str(res.get('job_name') or '')
        nums = [int(x) for x in re.findall(r'(?i)\borf[_-]?(\d+)\b', job_name)]
        if len(nums) >= 2:
            return nums[1]
        if len(nums) == 1:
            return nums[0]

        # Last fallback: scan all chain labels and use the second ORF-like
        # label if available.
        try:
            for c in res.get('chain_order') or []:
                name = str((res.get('chain_to_orf') or {}).get(c, ''))
                m = re.search(r'(?i)\borf[_-]?(\d+)\b', name)
                if m:
                    candidates.append(int(m.group(1)))
            if len(candidates) >= 2:
                return candidates[1]
            if candidates:
                return candidates[0]
        except Exception:
            pass
        return None

    def _af3a_sort_by_orf_order(self):
        """Sort Interaction Results by numeric ORF order."""
        if not hasattr(self, '_af3a_table'):
            return
        try:
            order = (Qt.SortOrder.AscendingOrder if QT_VERSION == 6
                     else Qt.AscendingOrder)
            self._af3a_table.sortItems(13, order)
            self._af3a_status.setText(
                re.sub(r'\s*\(\d+/\d+ shown\)\s*$', '',
                       self._af3a_status.text())
                + '  (sorted by ORF order)')
        except Exception as e:
            QMessageBox.warning(self, "Sort ORFs",
                                f"Could not sort by ORF order:\n{e}")

    def _af3a_set_hotspot_radius(self, value):
        """Update the hotspot/anchor window and refresh sequence columns.

        The AF3 table now carries the sequence window directly in columns
        16 and 17. Changing the Hotspot± / anchor control should therefore
        update those columns without requiring the old Anchor-window summary
        table below the plots.
        """
        try:
            self._af3a_hotspot_radius = int(value)
        except Exception:
            self._af3a_hotspot_radius = 10
        try:
            self._af3a_update_anchor_sequence_columns()
        except Exception as e:
            print(f"[AF3 Analysis] anchor sequence refresh failed: {e}")
        # v29.14: the radius also drives _compute_pae_hotspot.  Stored hotspot
        # metrics are now marked stale so the user is told to re-run instead of
        # silently keeping values computed with the previous radius.
        try:
            stale = 0
            for _r in getattr(self, '_af3_analysis_results', []):
                if (_r.get('hotspot') or {}).get('hotspot_score') is not None:
                    _r['hotspot_stale'] = True
                    _r['heavy_loaded'] = False
                    stale += 1
            if stale:
                self._af3a_status.setText(
                    f"Hotspot radius = {self._af3a_hotspot_radius} res — "
                    f"{stale} stored hotspot(s) are now stale; press "
                    f"'Run hotspots' to recompute.")
        except Exception as e:
            print(f"[AF3 Analysis] hotspot invalidation failed: {e}")

    def _af3a_seq_map_for_result(self, res):
        """Return chain_id -> sequence for an AF3 result, when available."""
        chain_order = list(res.get('chain_order') or [])
        seq_map = {}
        # Preferred explicit mapping, used by some patched builds.
        explicit = res.get('seqs_by_chain') or {}
        if isinstance(explicit, dict):
            for cid, seq in explicit.items():
                if seq:
                    seq_map[cid] = str(seq).replace('*', '').strip()
        # Standard ppigFinder path: input JSON sequences in submitted chain order.
        seq_chains = res.get('seq_chains') or []
        if isinstance(seq_chains, dict):
            for cid, seq in seq_chains.items():
                if seq:
                    seq_map[cid] = str(seq).replace('*', '').strip()
        elif isinstance(seq_chains, (list, tuple)):
            for i, cid in enumerate(chain_order):
                if i < len(seq_chains) and seq_chains[i]:
                    seq_map[cid] = str(seq_chains[i]).replace('*', '').strip()
        return seq_map

    def _af3a_anchor_sequence_texts(self, res, radius=None):
        """Return two display strings with the anchor-window sequences.

        The anchor is the PAE-minimum point of the best inter-chain pair.
        Coordinates are 1-based local coordinates in the submitted/modelled
        chain, which is the most reliable coordinate system for AF3 jobs.
        """
        if not isinstance(res, dict):
            return '-', '-'
        radius = int(radius if radius is not None else getattr(self, '_af3a_hotspot_radius', 10))
        hs = res.get('hotspot') or {}
        bp = res.get('best_pair') or ()
        if not hs or len(bp) != 2:
            return '-', '-'
        ca, cb = bp
        seq_map = self._af3a_seq_map_for_result(res)
        seq_a = seq_map.get(ca, '')
        seq_b = seq_map.get(cb, '')
        if not seq_a or not seq_b:
            # If the row was lazy-loaded from a folder that has no small input
            # JSON, the sequence is not available without loading/parsing large
            # files. Keep the table responsive and report this explicitly.
            return '-', '-'
        try:
            ia = int(hs.get('min_row'))
            ib = int(hs.get('min_col'))
        except Exception:
            return '-', '-'
        if ia < 0 or ib < 0 or ia >= len(seq_a) or ib >= len(seq_b):
            return '-', '-'
        a0 = max(0, ia - radius); a1 = min(len(seq_a), ia + radius + 1)
        b0 = max(0, ib - radius); b1 = min(len(seq_b), ib + radius + 1)
        name_a = res.get('chain_to_orf', {}).get(ca, ca) if isinstance(res.get('chain_to_orf'), dict) else ca
        name_b = res.get('chain_to_orf', {}).get(cb, cb) if isinstance(res.get('chain_to_orf'), dict) else cb
        text_a = f"{name_a}:{a0+1}-{a1} | {seq_a[a0:a1]}"
        text_b = f"{name_b}:{b0+1}-{b1} | {seq_b[b0:b1]}"
        return text_a, text_b

    def _af3a_update_anchor_sequence_columns(self):
        """Refresh columns 16/17 after the user changes Hotspot± / anchor."""
        table = getattr(self, '_af3a_table', None)
        if table is None or table.rowCount() == 0:
            return
        was_sortable = table.isSortingEnabled()
        table.setSortingEnabled(False)
        for view_row in range(table.rowCount()):
            res = self._af3a_res_for_view_row(view_row)
            if res is None:
                continue
            seq_a, seq_b = self._af3a_anchor_sequence_texts(res)
            it_a = table.item(view_row, 16) or QTableWidgetItem()
            it_b = table.item(view_row, 17) or QTableWidgetItem()
            it_a.setText(seq_a)
            it_b.setText(seq_b)
            it_a.setToolTip(seq_a)
            it_b.setToolTip(seq_b)
            table.setItem(view_row, 16, it_a)
            table.setItem(view_row, 17, it_b)
        table.setSortingEnabled(was_sortable)

    def _af3a_populate_table(self):
        """Populate the results table.

        BUG FIX (v1.15):
          • Disable sorting during insertion so Qt does not rearrange
            rows mid-population.
          • Store the result-list index in UserRole data on col 0 of
            each row, so `_af3a_on_select` and `_af3a_replot_selected`
            can retrieve the correct result even after the user
            re-sorts the table by any column.
          • Use a small numeric-aware QTableWidgetItem subclass for
            the float columns (ipTM, ptm, pLDDT, ranking, PAE_inter)
            so sorting is numeric, not lexicographic.
        """
        table = self._af3a_table
        user_role = self._af3a_user_role()

        # NumericItem: sorts by the stored float, displays formatted text
        class _NumericItem(QTableWidgetItem):
            def __init__(self, text: str, value):
                super().__init__(text)
                # value may be None → treat as -inf for best-first sort
                self._val = float(value) if value is not None else float('-inf')

            def __lt__(self, other):
                try:
                    return self._val < other._val
                except AttributeError:
                    return super().__lt__(other)

        # Disable sort + signals during rebuild
        was_sortable = table.isSortingEnabled()
        table.setSortingEnabled(False)
        table.blockSignals(True)
        table.setRowCount(0)

        def _c(v, thr_good, thr_ok, inv=False):
            if v is None: return None
            ok  = (v <= thr_ok)   if inv else (v >= thr_good)
            mid = (v <= thr_good) if inv else (v >= thr_ok)
            if ok:   return QColor('#C8E6C9')
            if mid:  return QColor('#FFF9C4')
            return QColor('#FFCDD2')

        for res_idx, res in enumerate(self._af3_analysis_results):
            row = table.rowCount()
            table.insertRow(row)

            # v2.7 — Render unknown lengths (chain_len == 0) as "?aa"
            # so a fallback row with chain IDs but no length still tells
            # the user what's there.
            def _fmt_chain(c):
                name = res['chain_to_orf'].get(c, c)
                length = res['chain_lens'].get(c, 0)
                length_s = f"{length}aa" if length > 0 else "?aa"
                return f"{name}({length_s})"
            chains_s = ', '.join(_fmt_chain(c) for c in res['chain_order'])
            iptm_s   = f"{res['iptm']:.3f}"       if res.get('iptm')          is not None else '-'
            ptm_s    = f"{res['ptm']:.3f}"        if res.get('ptm')           is not None else '-'
            plddt_s  = f"{res['mean_plddt']:.1f}" if res.get('mean_plddt')    is not None else '-'
            rank_s   = f"{res['ranking_score']:.4f}" if res.get('ranking_score') is not None else '-'
            pi_s     = f"{res['pae_inter']:.1f}"  if res.get('pae_inter')     is not None else '-'

            # Column 0: job name — carries the data index in UserRole
            # v2.5 — Multiple badges may apply: sequence-status icon
            # always, plus optional duplicate / completeness badges.
            _seq_st   = res.get('seq_status', 'no_input')
            _seq_icon = {
                # New v2.5 taxonomy
                'name_perfect':          '✅',   # folder name = sequences exactly
                'name_swapped':          '🔄',   # same ORFs, reversed chain order
                'name_outdated':         '🔁',   # folder name has stale ORF numbering
                'name_partial':          '⚠️',   # some chains foreign to genome
                'name_foreign':          '🌐',   # all sequences from another organism
                'name_homodimer_hidden': '👯',   # folder hetero, JSON homo
                # Legacy v2.0 taxonomy (back-compat for older saved sessions)
                'verified':  '✅',
                'corrected': '🔁',
                'mismatch':  '⚠️',
                # Edge cases
                'no_input':  '📂',
                'no_orfs':   '❔',
            }.get(_seq_st, '❔')

            # Duplicate badge — overlays the seq icon when this row is
            # part of a duplicate group.  Canonical of the group gets a
            # different glyph from replicates, so the user can spot
            # "the master" at a glance.
            dup_role = res.get('duplicate_role')
            dup_sub  = res.get('duplicate_sub_role')
            dup_n    = res.get('duplicate_count', 1)
            dup_badge = ''
            if dup_role == 'canonical':
                dup_badge = f'🏷×{dup_n}'   # this is the canonical of a {dup_n}-job group
            elif dup_role == 'replicate':
                dup_badge = ('🔁' if dup_sub == 'true_duplicate'
                              else '👥')

            # Completeness badge — only shown when the job is incomplete
            comp = res.get('completeness', 'complete')
            comp_badge = {
                'no_model':            '❌model',
                'no_full_confidences': '',  # silent — handled by chain-layout tooltip
                'no_summary':          '❌sum',
                'empty_or_partial':    '❌partial',
            }.get(comp, '')

            # Truncation badge
            trunc_badge = '✂' if res.get('truncation_info') else ''
            # Ambiguity badge
            ambig_badge = '🧬?' if res.get('ambiguity_info') else ''

            badges = ' '.join(b for b in
                              (_seq_icon, dup_badge, comp_badge,
                               trunc_badge, ambig_badge) if b)
            item0 = QTableWidgetItem(f"{badges} {res['job_name']}")
            item0.setData(user_role, res_idx)
            # QC tooltip with rich summary info
            tip_parts = []
            # ── Sequence verification status (first, most important) ──────
            _seq_msgs = {
                # New v2.5 taxonomy
                'name_perfect':
                    '✅ Folder name matches sequences exactly',
                'name_swapped':
                    '🔄 Chain order swapped — same ORFs as folder name '
                    'but in reversed chain order',
                'name_outdated':
                    '🔁 ORF numbering corrected — folder name is stale '
                    '(genome was re-run after submission)',
                'name_partial':
                    '⚠ Partial match — only some sequences exist in the '
                    'current genome',
                'name_foreign':
                    '🌐 Foreign sequences — none of the proteins in the '
                    'input JSON exist in the currently-loaded genome '
                    '(different organism, or a re-run is needed)',
                'name_homodimer_hidden':
                    '👯 Hidden homodimer — folder lists 2 different ORFs '
                    'but both chains have the same sequence',
                # Legacy fall-through
                'verified':  '✅ Sequences verified — folder name matches genome',
                'corrected': '🔁 ORF IDs corrected by sequence match',
                'mismatch':  '⚠ SEQUENCE MISMATCH — see Validation Report',
                'no_input':  '📂 No input JSON found — ORF IDs from folder name only',
                'no_orfs':   '❔ No genome loaded — cannot verify sequences',
            }
            tip_parts.append(_seq_msgs.get(_seq_st, '❔ Unknown status'))

            # Duplicate info (right after sequence status)
            if dup_role == 'canonical':
                tip_parts.append(
                    f'🏷 Canonical of duplicate group ({dup_n} jobs total)')
            elif dup_role == 'replicate':
                if dup_sub == 'true_duplicate':
                    tip_parts.append(
                        '🔁 TRUE DUPLICATE — same sequences AND same seeds '
                        'as another job (safe to delete)')
                else:
                    tip_parts.append(
                        '👥 Replicate — same sequences but different '
                        'modelSeeds (legitimate variance run)')

            # Completeness warning if not fully complete
            _comp_msgs = {
                'no_model':
                    '❌ model.cif missing — AF3 likely crashed before saving',
                'no_full_confidences':
                    'ℹ Full confidences.json absent — chains/PAE recovered '
                    'from fallback (input JSON / model.cif)',
                'no_summary':
                    '❌ summary_confidences.json missing',
                'empty_or_partial':
                    '❌ Job folder mostly empty',
            }
            if comp != 'complete' and comp in _comp_msgs:
                tip_parts.append(_comp_msgs[comp])

            # Truncation
            if res.get('truncation_info'):
                for t in res['truncation_info']:
                    tip_parts.append(
                        f"✂ Chain {t['chain']} truncated: "
                        f"{t['modeled']}/{t['expected']} aa "
                        f"({t['missing']} aa missing — token limit?)")

            # Ambiguity
            if res.get('ambiguity_info'):
                for a in res['ambiguity_info']:
                    tip_parts.append(
                        f"🧬 Chain {chr(65+a['chain_index'])} "
                        f"matches multiple ORFs: {', '.join(a['candidates'])}")

            # Sequence fingerprint (helpful for cross-referencing)
            fp = res.get('seq_fingerprint')
            if fp:
                tip_parts.append(f"Seq fingerprint: {fp}")
            # v2.7 — Surface which fallback tier provided the chain layout.
            # Helps users understand why some rows had blank Chain IDs in
            # earlier versions: now the loader recovers the info from the
            # input JSON, summary chain_iptm, or the model.cif.
            _cls_src = res.get('chain_layout_source')
            if _cls_src and _cls_src not in ('confidences', 'pae_matrix'):
                _cls_msgs = {
                    'input_json':         '🧬 Chains derived from input JSON '
                                          '(confidences.json had no chain map)',
                    'summary_chain_iptm': '🧬 Chains derived from summary '
                                          'chain_iptm (length only)',
                    'cif':                '🧬 Chains parsed from model.cif '
                                          '(last-resort fallback)',
                }
                tip_parts.append(_cls_msgs.get(
                    _cls_src, f'🧬 Chain layout source: {_cls_src}'))
            elif _cls_src == 'none':
                tip_parts.append(
                    '⚠ Chain layout could not be determined from any source')
            if res.get('has_clash') is not None:
                hc = res['has_clash']
                has = (hc if isinstance(hc, bool) else hc >= 0.5)
                tip_parts.append(
                    f"Clash: {'YES ⚠' if has else 'no'}")
            if res.get('fraction_disordered') is not None:
                tip_parts.append(
                    f"Disordered: {res['fraction_disordered']*100:.1f}%")
            # Best-pair PAE min (from chain_pair_pae_min)
            bp = res.get('best_pair')
            if bp and bp in res.get('pair_metrics', {}):
                pm = res['pair_metrics'][bp]
                if pm.get('pair_pae_min') is not None:
                    tip_parts.append(
                        f"PAE_min(best pair): {pm['pair_pae_min']:.2f} Å")
                if pm.get('pair_iptm') is not None:
                    tip_parts.append(
                        f"pair_ipTM: {pm['pair_iptm']:.2f}")
            if res.get('chain_iptm'):
                tip_parts.append(
                    "chain_iptm: ["
                    + ", ".join(f"{x:.2f}" for x in res['chain_iptm'])
                    + "]")
            if res.get('ranking_samples'):
                tip_parts.append(
                    f"{len(res['ranking_samples'])} diffusion sample(s)")
            if tip_parts:
                item0.setToolTip("\n".join(tip_parts))
            # Color the job name cell by verification status (v2.5)
            _seq_bg = {
                # New taxonomy
                'name_perfect':          QColor('#E8F5E9'),   # light green
                'name_swapped':          QColor('#FFF8E1'),   # light amber
                'name_outdated':         QColor('#E3F2FD'),   # light blue
                'name_partial':          QColor('#FFEBEE'),   # light red
                'name_foreign':          QColor('#FFCDD2'),   # heavier red
                'name_homodimer_hidden': QColor('#FCE4EC'),   # pink (suspicious)
                # Legacy
                'verified':  QColor('#E8F5E9'),
                'corrected': QColor('#E3F2FD'),
                'mismatch':  QColor('#FFEBEE'),
                'no_input':  None,
                'no_orfs':   None,
            }.get(_seq_st)
            # If this row is part of a duplicate group, tint slightly purple
            # ON TOP OF the seq-status color (replicate non-canonical only).
            if dup_role == 'replicate':
                _seq_bg = QColor('#F3E5F5')   # light purple for replicates
            if _seq_bg:
                item0.setBackground(_seq_bg)
            table.setItem(row, 0, item0)

            # Column 1: n_chains (int; small numbers sort OK as str but still numeric)
            table.setItem(row, 1, _NumericItem(str(res['n_chains']),
                                                res['n_chains']))
            # Column 2: chain description (string)
            table.setItem(row, 2, QTableWidgetItem(chains_s))

            # Columns 3–7: numeric metrics
            it_iptm  = _NumericItem(iptm_s,   res.get('iptm'))
            it_ptm   = _NumericItem(ptm_s,    res.get('ptm'))
            it_plddt = _NumericItem(plddt_s,  res.get('mean_plddt'))
            it_rank  = _NumericItem(rank_s,   res.get('ranking_score'))
            it_paei  = _NumericItem(pi_s,     res.get('pae_inter'))

            bg_iptm = _c(res.get('iptm'),      0.75,  0.50)
            bg_paei = _c(res.get('pae_inter'), 8.0,  15.0, inv=True)
            if bg_iptm: it_iptm.setBackground(bg_iptm)
            if bg_paei: it_paei.setBackground(bg_paei)

            table.setItem(row, 3, it_iptm)
            table.setItem(row, 4, it_ptm)
            table.setItem(row, 5, it_plddt)
            table.setItem(row, 6, it_rank)
            table.setItem(row, 7, it_paei)

            # ── Columns 8–10: focal interaction metrics (v2.0) ──────────────
            pae_min_v = res.get('pae_min_inter')
            cfrac_v   = res.get('contact_frac')

            pmin_s  = f"{pae_min_v:.2f}" if pae_min_v is not None else '-'
            cfrac_s = f"{cfrac_v*100:.1f}%" if cfrac_v is not None else '-'

            it_pmin = _NumericItem(pmin_s, pae_min_v)
            it_cfrc = _NumericItem(cfrac_s, (cfrac_v or 0) * 100)

            # PAE_min coloring: green < 4Å, yellow 4–8Å, red ≥ 8Å
            bg_pmin = _c(pae_min_v, 4.0, 8.0, inv=True)
            if bg_pmin: it_pmin.setBackground(bg_pmin)

            table.setItem(row, 8, it_pmin)
            table.setItem(row, 9, it_cfrc)

            # ── Columns 10–12: Hotspot metrics (v2.7) ────────────────────
            hs = res.get('hotspot') or {}
            hs_score  = hs.get('hotspot_score')
            hs_pae    = hs.get('hotspot_mean_pae')
            hs_sA     = hs.get('hotspot_size_A')
            hs_sB     = hs.get('hotspot_size_B')
            hs_sc_s   = f"{hs_score:.3f}" if hs_score is not None else '-'
            hs_pae_s  = f"{hs_pae:.1f} Å"  if hs_pae  is not None else '-'
            hs_size_s = f"{hs_sA}×{hs_sB}" if (hs_sA and hs_sB) else '-'

            it_hsc  = _NumericItem(hs_sc_s, hs_score)
            it_hpae = _NumericItem(hs_pae_s.replace(' Å',''), hs_pae)
            if hs_score is not None:
                it_hsc.setBackground(QColor(
                    '#C8E6C9' if hs_score >= 0.6
                    else '#FFF9C4' if hs_score >= 0.3
                    else '#FFCDD2'))
            if hs_pae is not None:
                it_hpae.setBackground(QColor(
                    '#C8E6C9' if hs_pae < 5.0
                    else '#FFF9C4' if hs_pae < 10.0
                    else '#FFCDD2'))
            table.setItem(row, 10, it_hsc)
            table.setItem(row, 11, it_hpae)
            table.setItem(row, 12, QTableWidgetItem(hs_size_s))

            # Column 13: numeric ORF order for bait-vs-genome screens.
            # This lets the user sort ORF1, ORF2, ORF3... correctly.
            orf_order_v = self._af3a_extract_orf_order_value(res)
            if orf_order_v is None:
                orf_order_s = '-'
                orf_order_sort = 1e18
            else:
                orf_order_s = f"ORF{int(orf_order_v)}"
                orf_order_sort = int(orf_order_v)
            table.setItem(row, 13, _NumericItem(orf_order_s, orf_order_sort))

            # Column 14: focal contact region description
            table.setItem(row, 14, QTableWidgetItem(
                res.get('contact_region', '-')))

            # Columns 15–16: direct amino-acid windows around the PAE-minimum anchor.
            # This replaces the previous bottom "Anchor-window summary" table.
            seqA_s, seqB_s = self._af3a_anchor_sequence_texts(res)
            it_seqA = QTableWidgetItem(seqA_s)
            it_seqB = QTableWidgetItem(seqB_s)
            it_seqA.setToolTip(seqA_s)
            it_seqB.setToolTip(seqB_s)
            table.setItem(row, 15, it_seqA)
            table.setItem(row, 16, it_seqB)

            # ── High-confidence highlight (v2.0) ───────────────────────────
            # Primary criterion: PAE_min < 4Å AND ipTM ≥ 0.50 = FOCAL HIT
            # v29.14: the second criterion used cp_ipTM, which is numerically
            # identical to the global ipTM for two-chain complexes; ipTM is
            # now used directly and cp_ipTM is no longer surfaced to the user.
            # Fallback: legacy ipTM > 0.75 AND PAEinter < 8Å
            iptm_v = res.get('iptm')
            paei_v = res.get('pae_inter')
            focal_hit = (pae_min_v is not None and pae_min_v < 4.0
                         and (iptm_v is None or iptm_v >= 0.50))
            legacy_hit = (iptm_v is not None and paei_v is not None
                          and iptm_v > 0.75 and paei_v < 8.0)
            if focal_hit or legacy_hit:
                bold = QFont()
                bold.setBold(True)
                for c in range(table.columnCount()):
                    it = table.item(row, c)
                    if it is not None:
                        it.setFont(bold)

        table.blockSignals(False)
        if was_sortable:
            table.setSortingEnabled(True)

        # Apply any active filters
        self._af3a_apply_filters()

    # ──────────────────────────────────────────────────────────────────
    #  Interaction Results — right-click context menu (v2.7)
    # ──────────────────────────────────────────────────────────────────
    #  Lets the user multi-select rows (Ctrl+click / Shift+click) and
    #  delete them, copy job names, open the folder of one row, or pick
    #  the ones that look interesting.  Deletion only removes the entry
    #  from the in-memory table — it never touches files on disk.
    def _af3a_table_right_click(self, pos):
        """Right-click on the Interaction Results table → context menu."""
        # Resolve the clicked row (so the menu still works even if the
        # user right-clicks an unselected row).
        idx_at_pos = self._af3a_table.indexAt(pos)
        clicked_row = idx_at_pos.row() if idx_at_pos.isValid() else -1

        # Selected rows (data-list indices, NOT view-row indices, because
        # the user may have re-sorted the table).
        view_rows = sorted(set(i.row()
                                for i in self._af3a_table.selectedIndexes()))
        # If the user right-clicked a row that wasn't yet selected, select
        # only that row so the menu acts on the visible target.
        if clicked_row >= 0 and clicked_row not in view_rows:
            self._af3a_table.clearSelection()
            self._af3a_table.selectRow(clicked_row)
            view_rows = [clicked_row]

        n = len(view_rows)
        menu = QMenu(self)

        # ── Open in file manager (single or multi-row, v29.11.1) ────────
        if n == 1:
            row = view_rows[0]
            menu.addAction(
                "📂  Open AF3 prediction folder",
                lambda _r=row: self._af3a_on_double_click(_r, 0))
            menu.addSeparator()
        elif n > 1:
            menu.addAction(
                f"📂  Open all {n} AF3 prediction folders",
                lambda _rs=list(view_rows): self._af3a_open_many(_rs))
            menu.addSeparator()

        # ── Selection helpers ────────────────────────────────────────────
        sel_menu = menu.addMenu("☑  Selection")
        sel_menu.addAction(
            "Select all",
            lambda: self._af3a_table.selectAll())
        sel_menu.addAction(
            "Deselect all",
            lambda: self._af3a_table.clearSelection())
        sel_menu.addAction(
            "Invert selection",
            lambda: self._af3a_invert_selection())
        sel_menu.addSeparator()
        sel_menu.addAction(
            "Select all HIGH-confidence rows  (PAE_min < 4 Å & cp_ipTM ≥ 0.5)",
            lambda: self._af3a_select_high_confidence())
        sel_menu.addAction(
            "Select all rows with no chain info  (n_chains = 0)",
            lambda: self._af3a_select_no_chain_info())
        # v2.5 Tier 1 — duplicate-related selection helpers
        sel_menu.addSeparator()
        sel_menu.addAction(
            "Select all DUPLICATE rows  (replicates only)",
            lambda: self._af3a_select_duplicates(role='replicate'))
        sel_menu.addAction(
            "Select all TRUE duplicates  (same seqs + same seeds)",
            lambda: self._af3a_select_duplicates(sub_role='true_duplicate'))
        sel_menu.addAction(
            "Select all CANONICAL rows of duplicate groups",
            lambda: self._af3a_select_duplicates(role='canonical'))
        # v2.5 Tier 2 — validation-issue selection helpers
        sel_menu.addSeparator()
        sel_menu.addAction(
            "Select rows with TRUNCATED chains",
            lambda: self._af3a_select_with_attribute('truncation_info'))
        sel_menu.addAction(
            "Select rows with AMBIGUOUS sequence matches",
            lambda: self._af3a_select_with_attribute('ambiguity_info'))
        sel_menu.addAction(
            "Select rows missing model.cif  (AF3 likely crashed)",
            lambda: self._af3a_select_completeness('no_model'))
        sel_menu.addAction(
            "Select rows with FOREIGN sequences  (different genome)",
            lambda: self._af3a_select_seq_status('name_foreign'))
        sel_menu.addAction(
            "Select rows with SWAPPED chain order",
            lambda: self._af3a_select_seq_status('name_swapped'))
        menu.addSeparator()

        # v2.5 Tier 1 — Validation Report (manual trigger)
        menu.addAction(
            "📊  Show Validation Report…",
            lambda: self._af3a_show_validation_report(
                self._af3_analysis_results,
                self._af3_analysis_dir or '(current)',
                after_scan=False))
        # v2.5 Tier 1 — Quick "delete all true duplicates" action
        n_true_dup = sum(1 for r in self._af3_analysis_results
                          if r.get('duplicate_role') == 'replicate'
                          and r.get('duplicate_sub_role') == 'true_duplicate')
        if n_true_dup > 0:
            menu.addAction(
                f"🧹  Remove all {n_true_dup} TRUE duplicate(s) from list",
                lambda: self._af3a_remove_all_true_duplicates())
        menu.addSeparator()

        # ── Clipboard ────────────────────────────────────────────────────
        if n >= 1:
            menu.addAction(
                f"📋  Copy job name{'s' if n > 1 else ''} ({n})",
                lambda: self._af3a_copy_selected_job_names(view_rows))
            menu.addAction(
                f"📋  Copy selected row{'s' if n > 1 else ''} as TSV ({n})",
                lambda: self._af3a_copy_selected_rows_tsv(view_rows))
            menu.addSeparator()

        # ── Delete (the headline action this menu was added for) ─────────
        if n >= 1:
            menu.addAction(
                f"🗑  Remove {n} selected row{'s' if n > 1 else ''} from list",
                lambda: self._af3a_delete_selected_rows(view_rows))
            menu.addSeparator()
            menu.addAction(
                "🧹  Clear ALL results",
                self._af3a_clear)

        menu.exec(self._af3a_table.viewport().mapToGlobal(pos))

    def _af3a_invert_selection(self):
        """Invert the current selection in the Interaction Results table."""
        sel_model = self._af3a_table.selectionModel()
        if sel_model is None:
            return
        sel_rows = set(i.row() for i in self._af3a_table.selectedIndexes())
        self._af3a_table.clearSelection()
        for r in range(self._af3a_table.rowCount()):
            if r not in sel_rows:
                self._af3a_table.selectRow(r)

    def _af3a_select_high_confidence(self):
        """Select rows where the PAE_min/cp_ipTM rule flags a focal hit."""
        self._af3a_table.clearSelection()
        for view_row in range(self._af3a_table.rowCount()):
            res = self._af3a_res_for_view_row(view_row)
            if res is None:
                continue
            pae_min_v = res.get('pae_min_inter')
            iptm_v   = res.get('iptm')
            paei_v   = res.get('pae_inter')
            # v29.14: ipTM replaces cp_ipTM here (identical for 2 chains).
            focal = (pae_min_v is not None and pae_min_v < 4.0
                     and (iptm_v is None or iptm_v >= 0.50))
            legacy = (iptm_v is not None and paei_v is not None
                      and iptm_v > 0.75 and paei_v < 8.0)
            if focal or legacy:
                self._af3a_table.selectRow(view_row)

    def _af3a_select_no_chain_info(self):
        """Select rows where chain info failed to load (n_chains == 0)."""
        self._af3a_table.clearSelection()
        for view_row in range(self._af3a_table.rowCount()):
            res = self._af3a_res_for_view_row(view_row)
            if res is None:
                continue
            if res.get('n_chains', 0) == 0:
                self._af3a_table.selectRow(view_row)

    # ──────────────────────────────────────────────────────────────────
    #  v2.5 Tier 1+2 — selection helpers for duplicates / completeness
    # ──────────────────────────────────────────────────────────────────
    def _af3a_select_duplicates(self, role=None, sub_role=None):
        """Select rows whose duplicate_role / sub_role matches.

        role='replicate'           — non-canonical members of any group
        role='canonical'           — the master row of each group
        sub_role='true_duplicate'  — replicates with same seqs AND seeds
        sub_role='replicate'       — replicates with same seqs but ≠ seeds
        """
        self._af3a_table.clearSelection()
        for view_row in range(self._af3a_table.rowCount()):
            res = self._af3a_res_for_view_row(view_row)
            if res is None:
                continue
            ok = True
            if role is not None and res.get('duplicate_role') != role:
                ok = False
            if sub_role is not None and res.get('duplicate_sub_role') != sub_role:
                ok = False
            # When sub_role is set, also require it's a non-canonical (otherwise
            # we'd select canonicals too, which doesn't make sense for "delete").
            if sub_role is not None and res.get('duplicate_role') != 'replicate':
                ok = False
            if ok:
                self._af3a_table.selectRow(view_row)

    def _af3a_select_with_attribute(self, attr_name):
        """Select rows where the given attribute is truthy (non-empty)."""
        self._af3a_table.clearSelection()
        for view_row in range(self._af3a_table.rowCount()):
            res = self._af3a_res_for_view_row(view_row)
            if res is None:
                continue
            if res.get(attr_name):
                self._af3a_table.selectRow(view_row)

    def _af3a_select_completeness(self, target_status):
        """Select rows whose completeness status matches `target_status`."""
        self._af3a_table.clearSelection()
        for view_row in range(self._af3a_table.rowCount()):
            res = self._af3a_res_for_view_row(view_row)
            if res is None:
                continue
            if res.get('completeness') == target_status:
                self._af3a_table.selectRow(view_row)

    def _af3a_select_seq_status(self, target_status):
        """Select rows whose seq_status matches `target_status`."""
        self._af3a_table.clearSelection()
        for view_row in range(self._af3a_table.rowCount()):
            res = self._af3a_res_for_view_row(view_row)
            if res is None:
                continue
            if res.get('seq_status') == target_status:
                self._af3a_table.selectRow(view_row)

    def _af3a_remove_all_true_duplicates(self):
        """One-click cleanup: remove every replicate flagged as true_duplicate.

        Keeps the canonical of each group.  Asks for confirmation first.
        Files on disk are never touched — this only edits the in-memory
        view (consistent with _af3a_delete_selected_rows behavior).
        """
        # Find indices to remove
        indices_to_remove = [
            i for i, r in enumerate(self._af3_analysis_results)
            if r.get('duplicate_role') == 'replicate'
            and r.get('duplicate_sub_role') == 'true_duplicate']
        n = len(indices_to_remove)
        if n == 0:
            QMessageBox.information(
                self, "Remove duplicates",
                "No true duplicates to remove.")
            return
        # Confirm
        try:
            yes = (QMessageBox.StandardButton.Yes
                   if QT_VERSION == 6 else QMessageBox.Yes)
            no  = (QMessageBox.StandardButton.No
                   if QT_VERSION == 6 else QMessageBox.No)
            ans = QMessageBox.question(
                self, "Remove all true duplicates",
                f"Remove {n} TRUE duplicate row{'s' if n > 1 else ''} "
                "from the list?\n\n"
                "Each removed row has the same sequences AND same model "
                "seeds as another row that will be kept (the canonical).\n\n"
                "This only updates the in-memory view — the AF3 result "
                "files on disk are NOT deleted.",
                yes | no)
            if ans != yes:
                return
        except Exception:
            pass

        idx_set = set(indices_to_remove)
        self._af3_analysis_results = [
            r for i, r in enumerate(self._af3_analysis_results)
            if i not in idx_set]
        # Re-assign duplicate groups (group sizes change after removal)
        self._af3a_assign_duplicate_groups(self._af3_analysis_results)
        self._af3a_populate_table()
        try:
            remaining = len(self._af3_analysis_results)
            self._af3a_status.setText(
                f"Removed {n} true duplicate(s) — "
                f"{remaining} job(s) remaining")
        except Exception:
            pass
        self._af3a_clear_plots()

    def _af3a_res_for_view_row(self, view_row):
        """Translate a view-row index → the underlying analysis result dict.

        Returns None when the row is missing or the data index is invalid.
        Required because the table is sortable, so view_row != data_idx.
        """
        item0 = self._af3a_table.item(view_row, 0)
        if item0 is None:
            return None
        res_idx = item0.data(self._af3a_user_role())
        if res_idx is None:
            res_idx = view_row
        try:
            res_idx = int(res_idx)
        except (TypeError, ValueError):
            return None
        if 0 <= res_idx < len(self._af3_analysis_results):
            return self._af3_analysis_results[res_idx]
        return None

    def _af3a_copy_selected_job_names(self, view_rows):
        names = []
        for r in view_rows:
            res = self._af3a_res_for_view_row(r)
            if res is not None:
                names.append(res.get('job_name', ''))
        if names:
            self._copy_to_clipboard('\n'.join(names))

    def _af3a_copy_selected_rows_tsv(self, view_rows):
        """Copy selected rows (with header) as TSV to the clipboard."""
        table = self._af3a_table
        cols = table.columnCount()
        header = []
        for c in range(cols):
            it = table.horizontalHeaderItem(c)
            header.append(it.text() if it is not None else '')
        lines = ['\t'.join(header)]
        for r in view_rows:
            row_vals = []
            for c in range(cols):
                it = table.item(r, c)
                row_vals.append(it.text() if it is not None else '')
            lines.append('\t'.join(row_vals))
        self._copy_to_clipboard('\n'.join(lines))

    def _af3a_delete_selected_rows(self, view_rows):
        """Remove the given view-rows from the in-memory results list.

        Notes:
        • Files on disk are never touched — this only edits the in-memory
          view.  Re-running 'Load AF3 results directory' brings them back.
        • Because we're going to rebuild the table from scratch, we map
          view-rows → data-indices first, then drop those indices.
        """
        if not view_rows:
            return
        # Map view-rows → data-list indices (set, so we can membership-test)
        data_indices = set()
        for r in view_rows:
            item0 = self._af3a_table.item(r, 0)
            if item0 is None:
                continue
            di = item0.data(self._af3a_user_role())
            try:
                data_indices.add(int(di))
            except (TypeError, ValueError):
                continue
        if not data_indices:
            return

        n = len(data_indices)
        # Confirm — this is destructive (in the UI sense) so make sure the
        # user really meant it.
        try:
            ans = QMessageBox.question(
                self, "Remove from list",
                f"Remove {n} selected entr{'ies' if n > 1 else 'y'} "
                "from the Interaction Results list?\n\n"
                "This only updates the in-memory view — the AF3 result "
                "files on disk are NOT deleted.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
                if QT_VERSION == 6 else
                QMessageBox.Yes | QMessageBox.No)
        except Exception:
            ans = None
        # Treat "Yes" (or any non-explicit-No) as confirmation
        try:
            yes_btn = (QMessageBox.StandardButton.Yes
                       if QT_VERSION == 6 else QMessageBox.Yes)
        except Exception:
            yes_btn = None
        if yes_btn is not None and ans is not None and ans != yes_btn:
            return

        # Build the surviving results list, preserving order
        self._af3_analysis_results = [
            r for i, r in enumerate(self._af3_analysis_results)
            if i not in data_indices]
        # v2.5 Tier 1 — re-assign duplicate groups now that some rows are gone
        # (a group of 2 may become a singleton; group sizes change).
        self._af3a_assign_duplicate_groups(self._af3_analysis_results)
        # Repopulate the table
        self._af3a_populate_table()
        # Update status bar text — keep it informative
        try:
            remaining = len(self._af3_analysis_results)
            self._af3a_status.setText(
                f"Removed {n} entr{'ies' if n > 1 else 'y'} — "
                f"{remaining} job(s) remaining")
        except Exception:
            pass
        # Clear the now-stale plots
        self._af3a_clear_plots()

    def _af3a_unload_heavy_except(self, keep_res=None):
        """Release PAE/contact/pLDDT arrays from all non-selected jobs.

        This keeps memory bounded when browsing hundreds or thousands of AF3
        predictions.  Summary-derived metrics remain in the table.
        """
        import gc
        for r in getattr(self, '_af3_analysis_results', []) or []:
            if r is keep_res:
                continue
            if r.get('heavy_loaded'):
                r['pae_matrix'] = None
                r['contact_probs'] = None
                r['plddt_arr'] = None
                r['token_res_ids'] = None
                # Keep small, already computed summaries.  Motif lists and
                # hotspot metrics are tiny compared with PAE/contact matrices
                # and should remain exportable after the heavy arrays are
                # unloaded.
                r['heavy_loaded'] = False
        try:
            gc.collect()
        except Exception:
            pass

    def _af3a_ensure_heavy_loaded(self, res: dict):
        """Load full PAE/contact matrices for one selected result only."""
        if not res or res.get('heavy_loaded'):
            return res
        sum_path = res.get('summary_path')
        if not sum_path:
            return res
        try:
            full = self._af3a_parse_job(
                Path(res.get('job_dir', '')),
                Path(sum_path),
                Path(res['conf_path']) if res.get('conf_path') else None,
                model_cif=Path(res['model_path']) if res.get('model_path') else None,
                ranking_csv=Path(res['ranking_csv_path']) if res.get('ranking_csv_path') else None,
                input_json=Path(res['input_json_path']) if res.get('input_json_path') else None,
                lazy=False)
            # Preserve duplicate/group annotations assigned during scan.
            preserve = {k: res.get(k) for k in (
                'duplicate_group_id', 'duplicate_role', 'duplicate_count',
                'duplicate_sub_role') if k in res}
            res.clear()
            res.update(full)
            res.update(preserve)
            res['heavy_loaded'] = True
            self._af3a_unload_heavy_except(res)
        except Exception as e:
            print(f"[AF3 Analysis] lazy load failed for {res.get('job_name')}: {e}")
        return res

    def _af3a_on_select(self):
        """Plot the selected job.

        BUG FIX (v1.15): retrieve the data-list index from the
        UserRole of column 0 instead of using the view row index
        (which is scrambled whenever the user sorts the table).
        """
        rows = set(idx.row() for idx in self._af3a_table.selectedIndexes())
        if not rows:
            return
        view_row = min(rows)
        item0 = self._af3a_table.item(view_row, 0)
        if item0 is None:
            return
        res_idx = item0.data(self._af3a_user_role())
        # Defensive fallback: if UserRole is missing (e.g. legacy project
        # files loaded into this build), fall back to view_row.
        if res_idx is None:
            res_idx = view_row
        try:
            res_idx = int(res_idx)
        except (TypeError, ValueError):
            return
        if not (0 <= res_idx < len(self._af3_analysis_results)):
            return

        res = self._af3_analysis_results[res_idx]
        res = self._af3a_ensure_heavy_loaded(res)
        self._af3a_plot_job(res)
        try:
            seqA_s, seqB_s = self._af3a_anchor_sequence_texts(res)
            if self._af3a_table.item(view_row, 15) is not None:
                self._af3a_table.item(view_row, 15).setText(seqA_s)
                self._af3a_table.item(view_row, 15).setToolTip(seqA_s)
            if self._af3a_table.item(view_row, 16) is not None:
                self._af3a_table.item(view_row, 16).setText(seqB_s)
                self._af3a_table.item(view_row, 16).setToolTip(seqB_s)
        except Exception:
            pass

        for orf_name in res.get('orf_names', []):
            m = re.match(r'ORF(\d+)', orf_name, re.IGNORECASE)
            if m:
                idx = int(m.group(1)) - 1
                if 0 <= idx < len(self.orfs):
                    self._select_and_center_orf(idx)
                    break

    def _open_af3_job_folder(self, job_dir):
        """v29.11.1 — cross-platform helper that opens an AF3 job directory
        in the user's file manager.  Used by the AF3 table double-click,
        the AF3 table right-click menu and the PPI Analysis dot right-click
        menu.  Tolerates missing or invalid paths gracefully (shows a
        dialog instead of raising).
        """
        if not job_dir:
            QMessageBox.information(
                self, "Open folder",
                "This row has no AF3 job folder recorded.")
            return
        p = Path(str(job_dir))
        if not p.is_dir():
            QMessageBox.information(
                self, "Open folder",
                f"Folder not found:\n{job_dir}")
            return
        try:
            if sys.platform == 'darwin':
                subprocess.Popen(['open', str(p)])
            elif sys.platform.startswith('win'):
                os.startfile(str(p))  # Windows-only API
            else:
                subprocess.Popen(['xdg-open', str(p)])
        except Exception as e:
            QMessageBox.warning(
                self, "Open folder",
                f"Could not open folder:\n{e}")

    def _af3a_on_double_click(self, row: int, _col: int):
        """Open the AF3 job folder of *row* in the OS file manager."""
        item0 = self._af3a_table.item(row, 0)
        if item0 is None:
            return
        res_idx = item0.data(self._af3a_user_role())
        if res_idx is None:
            return
        try:
            res = self._af3_analysis_results[int(res_idx)]
        except (IndexError, TypeError, ValueError):
            return
        self._open_af3_job_folder(res.get('job_dir', ''))


    def _af3a_open_many(self, view_rows):
        """v29.11.1 — open every selected AF3 prediction folder in sequence.

        Confirms with the user when more than 5 folders would open at once,
        because each one launches a separate file-manager window.
        """
        if not view_rows:
            return
        if len(view_rows) > 5:
            ok = QMessageBox.question(
                self, "Open AF3 prediction folders",
                f"This will open {len(view_rows)} folders in your file manager.\n"
                "Continue?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
                if QT_VERSION == 6 else
                QMessageBox.Yes | QMessageBox.No)
            yes_btn = (QMessageBox.StandardButton.Yes if QT_VERSION == 6
                       else QMessageBox.Yes)
            if ok != yes_btn:
                return
        opened = 0
        for row in view_rows:
            item0 = self._af3a_table.item(int(row), 0)
            if item0 is None:
                continue
            res_idx = item0.data(self._af3a_user_role())
            if res_idx is None:
                continue
            try:
                res = self._af3_analysis_results[int(res_idx)]
            except (IndexError, TypeError, ValueError):
                continue
            job_dir = res.get('job_dir', '')
            if job_dir and Path(job_dir).is_dir():
                self._open_af3_job_folder(job_dir)
                opened += 1
        try:
            self._status.showMessage(f"Opened {opened} AF3 folder(s)")
        except Exception:
            pass

    def _af3a_replot_selected(self):
        """Re-render plots for the currently selected row, re-using
        the latest contact threshold.

        BUG FIX (v1.15):
          • Uses UserRole-stored index (see _af3a_on_select).
          • Also refreshes the 'Best contact pair' cell in the table
            so the on-screen text matches the new threshold.
        """
        rows = set(idx.row() for idx in self._af3a_table.selectedIndexes())
        if not rows:
            return
        view_row = min(rows)
        item0 = self._af3a_table.item(view_row, 0)
        if item0 is None:
            return
        res_idx = item0.data(self._af3a_user_role())
        if res_idx is None:
            return
        try:
            res_idx = int(res_idx)
        except (TypeError, ValueError):
            return
        if not (0 <= res_idx < len(self._af3_analysis_results)):
            return

        res = self._af3_analysis_results[res_idx]
        res = self._af3a_ensure_heavy_loaded(res)
        try:
            thresh = self._af3a_thresh_spin.value()
            if res.get('pae_matrix') and res.get('n_chains', 1) >= 2:
                pae_np = np.array(res['pae_matrix'], dtype=float)
                chain_order = res['chain_order']
                chain_lens  = res['chain_lens']
                best_pair = res.get('best_pair', ('?', '?'))
                for (ca, cb) in list(res['pair_metrics'].keys()):
                    i_c = chain_order.index(ca)
                    j_c = chain_order.index(cb)
                    r0 = sum(chain_lens[chain_order[k]] for k in range(i_c))
                    r1 = r0 + chain_lens[ca]
                    c0 = sum(chain_lens[chain_order[k]] for k in range(j_c))
                    c1 = c0 + chain_lens[cb]
                    mA = pae_np[r0:r1, c0:c1].mean(axis=1)
                    mB = pae_np[c0:c1, r0:r1].mean(axis=1)
                    cr = self._af3a_contact_str(
                        mA, mB,
                        res['chain_to_orf'].get(ca, ca),
                        res['chain_to_orf'].get(cb, cb), thresh)
                    res['pair_metrics'][(ca, cb)]['contact_region'] = cr
                    res['pair_metrics'][(ca, cb)]['n_contacts'] = int(
                        (mA < thresh).sum() + (mB < thresh).sum())
                # Update 'best' contact_region for the table
                if best_pair in res['pair_metrics']:
                    res['contact_region'] = (
                        res['pair_metrics'][best_pair]['contact_region'])
                    # Refresh the table cell (col 15 = contact_region)
                    cell = self._af3a_table.item(view_row, 14)
                    if cell is not None:
                        cell.setText(res['contact_region'])
        except Exception as e:
            print(f"[AF3 Analysis] replot threshold update: {e}")
        self._af3a_plot_job(res)

    def _af3a_clear_plots(self):
        self._af3a_active_canvases = []
        # v1.16: drop motif-highlight references since the canvas they
        # point to is about to be deleted.
        self._af3a_last_pae_ax = None
        self._af3a_last_pae_canvas = None
        self._af3a_highlight_patches = []
        while self._af3a_plot_layout.count():
            item = self._af3a_plot_layout.takeAt(0)
            w = item.widget()
            if w:
                w.deleteLater()
        try:
            import matplotlib.pyplot as _plt
            _plt.close('all')
        except Exception:
            pass

    def _af3a_plot_job(self, res: dict):
        """Render interactive PAE heatmap(s) + pLDDT for one job."""
        if not MATPLOTLIB_AVAILABLE:
            return
        # Guard: we need a real Qt-based FigureCanvas class. The most reliable
        # signal is that it's a QWidget subclass (all QWidgets expose
        # setMinimumHeight). If the host IDE forced a non-Qt backend before
        # our script ran and we still ended up with an Agg canvas, this
        # attribute is missing — fall back to a clear diagnostic instead of
        # crashing later on canvas.setMinimumHeight().
        if FigureCanvas is None or not hasattr(FigureCanvas, "setMinimumHeight"):
            self._af3a_clear_plots()
            warn = QLabel(
                "<b>Interactive plots are unavailable.</b><br><br>"
                "matplotlib is not using a Qt canvas backend in this Python "
                "session. This usually happens when the app is launched from "
                "Spyder or JupyterLab, whose IPython console pre-sets the "
                "<i>inline</i> backend before this script can switch it.<br><br>"
                "<b>Fix:</b><br>"
                "&nbsp;• <b>Spyder:</b> Tools → Preferences → IPython console "
                "→ Graphics → Backend: change from <i>Inline</i> to "
                "<b>Qt5</b> or <b>Qt6</b>, then restart the kernel "
                "(Consoles → Restart kernel).<br>"
                "&nbsp;• <b>Or run ppigFinder from a normal terminal</b> "
                "(<code>python ppigfinder.py</code>) instead of from an "
                "IDE console — the Qt backend is picked automatically."
            )
            warn.setWordWrap(True)
            warn.setTextFormat(Qt.TextFormat.RichText if QT_VERSION == 6
                               else Qt.RichText)
            warn.setStyleSheet(
                "background:#FFF4E5;color:#7A4B00;border:1px solid #FFD7A0;"
                "border-radius:4px;padding:10px;")
            self._af3a_plot_layout.addWidget(warn)
            return
        res = self._af3a_ensure_heavy_loaded(res)

        self._af3a_clear_plots()
        from matplotlib.colors import LinearSegmentedColormap

        # ── ChimeraX PAE colormap ──────────────────────────────
        pae_cmap = LinearSegmentedColormap.from_list('pae_chimerax', [
            '#1E3A8A',  # 0 Å  dark blue
            '#2563EB',  # 5 Å  blue
            '#60A5FA',  # 10 Å light blue
            '#FCD34D',  # 15 Å yellow
            '#F97316',  # 20 Å orange
            '#D1D5DB',  # 25 Å light grey
            '#F9FAFB',  # 31 Å near white
        ], N=256)

        pae   = res.get('pae_matrix')
        plddt = res.get('plddt_arr')
        chain_order = res.get('chain_order', [])
        chain_lens  = res.get('chain_lens', {})
        chain_to_orf = res.get('chain_to_orf', {})
        n_chains    = res.get('n_chains', 1)
        thresh      = self._af3a_thresh_spin.value()

        # Build ORF-labelled axis tick positions and labels
        ticks_pos  = []
        ticks_lbl  = []
        dividers   = []
        cum = 0
        for ci, cid in enumerate(chain_order):
            clen = chain_lens.get(cid, 0)
            ticks_pos.append(cum + clen / 2)
            ticks_lbl.append(chain_to_orf.get(cid, cid))
            if ci > 0:
                dividers.append(cum - 0.5)
            cum += clen

        # ── Title + metrics header ─────────────────────────────
        iptm_s  = f"{res['iptm']:.3f}"  if res.get('iptm') is not None else 'N/A'
        ptm_s   = f"{res['ptm']:.3f}"   if res.get('ptm')  is not None else 'N/A'
        pl_s    = f"{res['mean_plddt']:.1f}" if res.get('mean_plddt') is not None else 'N/A'
        pi_s    = f"{res['pae_inter']:.1f} Å" if res.get('pae_inter') is not None else 'N/A'
        nc_s    = str(res['pair_metrics'].get(
                        res.get('best_pair', ()), {}).get('n_contacts', '-'))

        hdr = QLabel(
            f"<b>{res['job_name']}</b>  —  "
            f"Chains: {n_chains}  |  "
            f"ipTM={iptm_s}  ptm={ptm_s}  "
            f"mean_pLDDT={pl_s}  "
            f"Best PAE_inter={pi_s}  contacts={nc_s} res")
        hdr.setStyleSheet(
            "font-size:11px;padding:4px 8px;background:#E8EAF6;"
            "border-radius:4px;")
        self._af3a_plot_layout.addWidget(hdr)

        # QC line: fraction_disordered + has_clash + per-chain metrics
        qc_parts = []
        fd = res.get('fraction_disordered')
        if fd is not None:
            colour = '#E65100' if fd > 0.3 else '#2E7D32'
            qc_parts.append(
                f"<span style='color:{colour}'>"
                f"disordered={fd*100:.1f}%</span>")
        hc = res.get('has_clash')
        if hc is not None:
            has = (hc if isinstance(hc, bool) else hc >= 0.5)
            if has:
                qc_parts.append(
                    "<span style='color:#C62828'>⚠ clash</span>")
            else:
                qc_parts.append(
                    "<span style='color:#2E7D32'>no clash</span>")
        # Per-chain ipTM / ptm breakdown
        c_iptm = res.get('chain_iptm') or []
        c_ptm  = res.get('chain_ptm')  or []
        for i, cid in enumerate(chain_order):
            bits = []
            if i < len(c_iptm) and c_iptm[i] is not None:
                bits.append(f"ipTM={c_iptm[i]:.2f}")
            if i < len(c_ptm) and c_ptm[i] is not None:
                bits.append(f"pTM={c_ptm[i]:.2f}")
            if bits:
                qc_parts.append(
                    f"{chain_to_orf.get(cid, cid)}({','.join(bits)})")
        if qc_parts:
            qc = QLabel("  " + "   ".join(qc_parts))
            qc.setStyleSheet(
                "font-size:10px;padding:1px 8px;color:#455A64;")
            qc.setTextFormat(
                Qt.TextFormat.RichText if QT_VERSION == 6
                else Qt.RichText)
            self._af3a_plot_layout.addWidget(qc)

        # ── Sequence verification status line ─────────────────────────────
        _seq_st   = res.get('seq_status', 'no_input')
        _seq_html = {
            'verified':  ("<span style='color:#2E7D32;font-weight:500'>"
                          "✅ Sequences verified</span>"
                          " — ORF IDs confirmed by exact sequence match "
                          "with loaded genome"),
            'corrected': ("<span style='color:#1565C0;font-weight:500'>"
                          "🔁 ORF IDs corrected</span>"
                          " — folder name differed from current genome "
                          "numbering; correct IDs found by sequence match"),
            'mismatch':  ("<span style='color:#C62828;font-weight:500'>"
                          "⚠️ SEQUENCE MISMATCH</span>"
                          " — proteins in this job were NOT found in the "
                          "current genome. Results may belong to a different "
                          "genome or a re-analysed sequence. "
                          "Interpretation may be incorrect."),
            'no_input':  ("<span style='color:#888'>"
                          "📂 Not verified</span>"
                          " — no input JSON found; ORF IDs from folder name only"),
            'no_orfs':   ("<span style='color:#888'>"
                          "❔ Cannot verify</span>"
                          " — no genome loaded"),
        }.get(_seq_st, "")
        if _seq_html:
            seq_lbl = QLabel("  " + _seq_html)
            seq_lbl.setTextFormat(
                Qt.TextFormat.RichText if QT_VERSION == 6 else Qt.RichText)
            seq_lbl.setStyleSheet(
                "font-size:10px;padding:1px 8px;"
                "background:#f8f8f8;border-left:3px solid "
                + {
                    'verified':  '#2E7D32',
                    'corrected': '#1565C0',
                    'mismatch':  '#C62828',
                }.get(_seq_st, '#ccc') + ";")
            seq_lbl.setWordWrap(True)
            self._af3a_plot_layout.addWidget(seq_lbl)

        try:
            self._af3a_build_selected_interface_schematic(self._af3a_plot_layout, res)
        except Exception as _e:
            _warn = QLabel(f"Interface schematic could not be built: {_e}")
            _warn.setWordWrap(True)
            _warn.setStyleSheet('color:#b45309;')
            self._af3a_plot_layout.addWidget(_warn)


        # ── Hotspot summary line in plot area ──────────────────────────────
        hs = res.get('hotspot') or {}
        if hs:
            _hs_score = hs.get('hotspot_score')
            _hs_pae   = hs.get('hotspot_mean_pae')
            _hs_sA    = hs.get('hotspot_size_A')
            _hs_sB    = hs.get('hotspot_size_B')
            _hs_r0    = hs.get('hotspot_r0', 0)
            _hs_r1    = hs.get('hotspot_r1', 0)
            _hs_c0    = hs.get('hotspot_c0', 0)
            _hs_c1    = hs.get('hotspot_c1', 0)
            _hs_mr    = hs.get('min_row', 0)
            _hs_mc    = hs.get('min_col', 0)
            _conf_col = ('#2E7D32' if (_hs_score or 0) >= 0.6
                         else '#E65100' if (_hs_score or 0) >= 0.3
                         else '#C62828')
            _hs_html = (
                f"<span style='color:{_conf_col};font-weight:500'>"
                f"Hotspot score={_hs_score:.3f}</span> "
                f"mean_PAE={_hs_pae:.1f}Å  "
                f"size={_hs_sA}×{_hs_sB} res  "
                f"PAE_min at A:{_hs_mr+1}/B:{_hs_mc+1}  "
                f"window A:{_hs_r0+1}–{_hs_r1} / B:{_hs_c0+1}–{_hs_c1}")
            hs_lbl = QLabel("  " + _hs_html)
            hs_lbl.setTextFormat(
                Qt.TextFormat.RichText if QT_VERSION == 6 else Qt.RichText)
            hs_lbl.setStyleSheet(
                "font-size:10px;padding:1px 8px;"
                "background:#E8F5E9;border-left:3px solid #00C853;")
            self._af3a_plot_layout.addWidget(hs_lbl)

        # Contact regions + per-pair rich metrics
        if res.get('pair_metrics'):
            for (ca, cb), pm in res['pair_metrics'].items():
                extras = []
                if pm.get('pair_iptm') is not None:
                    extras.append(f"ipTM={pm['pair_iptm']:.2f}")
                if pm.get('pair_pae_min') is not None:
                    extras.append(f"PAE_min={pm['pair_pae_min']:.1f}Å")
                if pm.get('pae_inter') is not None:
                    extras.append(f"PAE_mean={pm['pae_inter']:.1f}Å")
                extras_s = (" [" + ", ".join(extras) + "]") if extras else ""
                cr_lbl = QLabel(
                    f"  {chain_to_orf.get(ca,ca)} ↔ "
                    f"{chain_to_orf.get(cb,cb)}{extras_s}: "
                    f"{pm.get('contact_region', '-')}")
                cr_lbl.setStyleSheet(
                    "font-size:10px;color:#1565C0;padding:1px 8px;")
                cr_lbl.setWordWrap(True)
                self._af3a_plot_layout.addWidget(cr_lbl)

        # ── PAE HEATMAP ────────────────────────────────────────
        if pae:
            pae_np = np.array(pae, dtype=float)
            n_total = len(pae_np)
            px_per_res = max(1.5, min(4.0, 600 / n_total))
            fig_size = max(5, n_total * px_per_res / 100)

            fig, ax = plt.subplots(
                figsize=(fig_size + 1.2, fig_size), dpi=90)
            fig.patch.set_facecolor('white')

            im = ax.imshow(pae_np, cmap=pae_cmap,
                           vmin=0, vmax=31.75,
                           aspect='equal',
                           interpolation='nearest',
                           origin='upper')

            cbar = fig.colorbar(im, ax=ax, fraction=0.035, pad=0.02)
            cbar.set_label('PAE (Å)', fontsize=9)
            cbar.ax.tick_params(labelsize=8)

            # Chain dividers
            for d in dividers:
                ax.axvline(d, color='black', lw=1.2)
                ax.axhline(d, color='black', lw=1.2)

            # Axis labels: one per chain block
            ax.set_xticks(ticks_pos)
            ax.set_xticklabels(ticks_lbl, fontsize=8, rotation=30, ha='right')
            ax.set_yticks(ticks_pos)
            ax.set_yticklabels(ticks_lbl, fontsize=8)
            ax.set_xlabel('Scored residue', fontsize=9, labelpad=4)
            ax.set_ylabel('Aligned residue', fontsize=9, labelpad=4)
            ax.set_title(
                f"PAE — {res['job_name']}  ({n_chains} chain(s))",
                fontsize=9, pad=6)

            # ── Hotspot overlay (v2.7) ──────────────────────────────────────
            # Draw the hotspot bounding box on the PAE heatmap when available.
            hs = res.get('hotspot') or {}
            if hs and n_chains == 2:
                _off_a = 0
                _off_b = chain_lens.get(chain_order[0], 0)
                _r0 = hs.get('hotspot_r0', 0) + _off_a
                _r1 = hs.get('hotspot_r1', 0) + _off_a
                _c0 = hs.get('hotspot_c0', 0) + _off_b
                _c1 = hs.get('hotspot_c1', 0) + _off_b
                _mr = hs.get('min_row', 0)    + _off_a
                _mc = hs.get('min_col', 0)    + _off_b
                # Semi-transparent fill
                ax.add_patch(plt.Rectangle(
                    (_c0 - 0.5, _r0 - 0.5), _c1 - _c0, _r1 - _r0,
                    linewidth=0, facecolor='#00C853', alpha=0.12, zorder=5))
                # Solid border
                ax.add_patch(plt.Rectangle(
                    (_c0 - 0.5, _r0 - 0.5), _c1 - _c0, _r1 - _r0,
                    linewidth=1.8, edgecolor='#00C853', facecolor='none',
                    alpha=0.9, zorder=6))
                # Star at PAE minimum
                ax.plot(_mc, _mr, marker='*', color='#FFD600',
                        markersize=9, zorder=7)
                # Score label
                _hscore = hs.get('hotspot_score')
                if _hscore is not None:
                    ax.text(_c0, _r0 - 1.5,
                            f"HS={_hscore:.2f}",
                            color='#00C853', fontsize=7, fontweight='bold',
                            va='bottom', ha='left', zorder=7)

            # Contact residue markers (<thresh Å in off-diag quadrants)
            #
            # v1.15 BUG FIX: the previous version drew every contact as
            # a single dot at the horizontal centre of the off-diagonal
            # block (x = cum_j + len_b/2), producing a vertical stripe
            # in the middle of each block instead of marking the actual
            # residue positions. It also only marked one quadrant per
            # pair. We now draw a small outline box at each (row_a,
            # col_b) cell whose inter-chain PAE is below the threshold,
            # for every (i_c, j_c) off-diagonal block — so both the AB
            # and BA quadrants are marked.
            marker_size = max(4, min(18, 900 / max(n_total, 1)))
            cum_i = 0
            for i_c, ca in enumerate(chain_order):
                len_a = chain_lens.get(ca, 0)
                cum_j = 0
                for j_c, cb in enumerate(chain_order):
                    len_b = chain_lens.get(cb, 0)
                    if i_c != j_c and len_a > 0 and len_b > 0:
                        sub = pae_np[cum_i:cum_i + len_a,
                                     cum_j:cum_j + len_b]
                        # Per-row mean in this quadrant → rows of chain
                        # ca that are in contact with chain cb.
                        mA = sub.mean(axis=1)
                        contact_rows = np.where(mA < thresh)[0]
                        if len(contact_rows):
                            # Draw one horizontal band per contact row,
                            # spanning the full width of the partner
                            # chain's block — this is what users expect
                            # for an "interface" annotation on a PAE map.
                            for rr in contact_rows:
                                ax.add_patch(plt.Rectangle(
                                    (cum_j - 0.5, cum_i + rr - 0.5),
                                    len_b, 1,
                                    facecolor='none',
                                    edgecolor='#00E676',
                                    linewidth=0.6,
                                    alpha=0.9,
                                    zorder=4))
                            # Emphasize the low-PAE cells themselves
                            # with small dots in each quadrant.
                            low = np.argwhere(sub < thresh)
                            if len(low):
                                # Sub-sample if too many points
                                if len(low) > 4000:
                                    step = max(1, len(low) // 4000)
                                    low = low[::step]
                                ax.scatter(
                                    cum_j + low[:, 1],
                                    cum_i + low[:, 0],
                                    s=marker_size * 0.15,
                                    color='#00E676',
                                    alpha=0.75,
                                    zorder=5, linewidths=0)
                    cum_j += len_b
                cum_i += len_a

            plt.tight_layout()

            # ── Interactive canvas with hover ───────────────────
            canvas = FigureCanvas(fig)
            canvas.setMinimumHeight(int(fig_size * 90))

            # Hover: show PAE value at cursor position
            hover_lbl = self._af3a_hover_lbl
            chain_order_ref = chain_order
            chain_lens_ref  = chain_lens
            c2o_ref         = chain_to_orf
            pae_np_ref      = pae_np
            tri_ref         = res.get('token_res_ids')

            def _on_hover(event, _pae=pae_np_ref,
                          _co=chain_order_ref, _cl=chain_lens_ref,
                          _c2o=c2o_ref, _tri=tri_ref,
                          _ax=ax, _lbl=hover_lbl):
                if event.inaxes != _ax:
                    _lbl.setText("")
                    return
                xi, yi = int(round(event.xdata)), int(round(event.ydata))
                n = len(_pae)
                if 0 <= xi < n and 0 <= yi < n:
                    val = _pae[yi, xi]
                    # Determine which chains xi and yi belong to
                    def _chain_of(pos):
                        cum = 0
                        for cid in _co:
                            cum += _cl.get(cid, 0)
                            if pos < cum:
                                return _c2o.get(cid, cid)
                        return '?'
                    cx = _chain_of(xi)
                    cy = _chain_of(yi)
                    # Use real residue numbers from token_res_ids when
                    # available (restarts at 1 per chain, matching AF3
                    # server display). Fall back to running index+1.
                    if _tri and len(_tri) == n:
                        rx = int(_tri[xi])
                        ry = int(_tri[yi])
                    else:
                        rx = xi + 1
                        ry = yi + 1
                    _lbl.setText(
                        f"  PAE  scored={cx} res{rx}  "
                        f"aligned={cy} res{ry}  →  "
                        f"{val:.2f} Å")

            # ── Motif overlays (v1.16) ────────────────────────────
            # Draw a numbered rectangle around every detected motif on
            # BOTH off-diagonal quadrants (A↔B solid, B↔A dashed mirror).
            # The number is the motif's global rank in the job. Uses a
            # warm red that is clearly visible against the blue PAE.
            motifs = res.get('motifs') or []
            for m in motifs:
                r0 = m['abs_row0']; r1 = m['abs_row1']
                c0 = m['abs_col0']; c1 = m['abs_col1']
                # Pick colour by score: green (strong) → amber → red
                if   m['score'] >= 60: colr = '#00C853'
                elif m['score'] >= 40: colr = '#FFAB00'
                else:                  colr = '#FF1744'
                # A↔B quadrant
                ax.add_patch(plt.Rectangle(
                    (c0 - 0.5, r0 - 0.5),
                    c1 - c0 + 1, r1 - r0 + 1,
                    facecolor='none', edgecolor=colr,
                    linewidth=1.6, zorder=7))
                # Rank label above upper-left corner, readable on any bg
                ax.annotate(
                    f"#{m['rank']}",
                    xy=(c0 - 0.5, r0 - 0.5),
                    xytext=(c0 + 1, r0 - 3),
                    fontsize=8, fontweight='bold',
                    color=colr,
                    bbox=dict(boxstyle='round,pad=0.15',
                              facecolor='white', edgecolor=colr,
                              linewidth=0.8, alpha=0.9),
                    zorder=8)
                # Mirrored B↔A quadrant (dashed, no label, lower alpha)
                ax.add_patch(plt.Rectangle(
                    (r0 - 0.5, c0 - 0.5),
                    r1 - r0 + 1, c1 - c0 + 1,
                    facecolor='none', edgecolor=colr,
                    linewidth=1.0, linestyle='--',
                    alpha=0.75, zorder=7))

            canvas.mpl_connect('motion_notify_event', _on_hover)

            # ── Right-click context menu on PAE canvas ────────────────────
            job_name_ref = res['job_name']
            def _pae_right_click(event, _fig=fig, _name=job_name_ref):
                if event.button != 3:   # 3 = right mouse button
                    return
                self._af3a_canvas_context_menu(_fig, _name + '_PAE')
            canvas.mpl_connect('button_press_event', _pae_right_click)

            self._af3a_active_canvases.append((fig, canvas,
                                                res['job_name'] + '_PAE'))
            # Stash refs so the motif-table click handler can draw a
            # highlight on the SAME axes without rebuilding the plot.
            self._af3a_last_pae_ax = ax
            self._af3a_last_pae_canvas = canvas
            self._af3a_highlight_patches = []
            plt.close(fig)
            self._af3a_plot_layout.addWidget(canvas)

        # ── pLDDT PLOT ─────────────────────────────────────────
        if plddt and chain_order:
            plddt_np = np.array(plddt, dtype=float)
            n_total  = len(plddt_np)
            fig_w    = max(6, n_total / 30)
            fig2, ax2 = plt.subplots(figsize=(fig_w, 2.6), dpi=90)
            fig2.patch.set_facecolor('white')

            chain_colors = ['#1565C0','#C62828','#2E7D32',
                            '#E65100','#6A1B9A','#00695C',
                            '#4A148C','#827717','#3E2723','#0D47A1']
            cum = 0
            for ci, cid in enumerate(chain_order):
                clen = chain_lens.get(cid, 0)
                if clen <= 0:
                    continue
                xs  = np.arange(cum, cum + clen)
                ys  = plddt_np[cum:cum + clen]
                col = chain_colors[ci % len(chain_colors)]
                lbl = chain_to_orf.get(cid, cid)
                ax2.plot(xs, ys, color=col, lw=0.9,
                         label=lbl, alpha=0.9)
                ax2.fill_between(xs, ys, alpha=0.12, color=col)
                cum += clen

            for d in dividers:
                ax2.axvline(d, color='black', lw=0.8)
            ax2.axhline(70, color='#2E7D32', lw=0.8, ls='--',
                        alpha=0.6, label='70 (good)')
            ax2.axhline(50, color='#E65100', lw=0.8, ls='--',
                        alpha=0.6, label='50 (low)')

            ax2.set_xticks(ticks_pos)
            ax2.set_xticklabels(ticks_lbl, fontsize=8,
                                rotation=20, ha='right')
            ax2.set_ylim(0, 100)
            ax2.set_ylabel('pLDDT', fontsize=9)
            ax2.set_title(
                f"pLDDT — {res['job_name']}", fontsize=9, pad=4)
            ax2.legend(fontsize=7, loc='lower right',
                       ncol=min(n_chains + 2, 6), framealpha=0.7)
            ax2.tick_params(labelsize=8)
            ax2.grid(axis='y', alpha=0.25)
            plt.tight_layout()

            canvas2 = FigureCanvas(fig2)
            canvas2.setMinimumHeight(220)

            # ── Right-click context menu on pLDDT canvas ─────────────────
            def _plddt_right_click(event, _fig=fig2,
                                   _name=res['job_name'] + '_pLDDT'):
                if event.button != 3:
                    return
                self._af3a_canvas_context_menu(_fig, _name)
            canvas2.mpl_connect('button_press_event', _plddt_right_click)

            self._af3a_active_canvases.append((fig2, canvas2,
                                                res['job_name'] + '_pLDDT'))
            plt.close(fig2)
            self._af3a_plot_layout.addWidget(canvas2)

        # ── Motif table (v1.16) ─────────────────────────────────────
        # Must come after both plots so it renders below them.
        try:
            self._af3a_build_motif_table(res)
        except Exception as e:
            print(f"[AF3 Analysis] motif table build failed: {e}")

        self._af3a_plot_layout.addStretch()

    def _af3a_canvas_context_menu(self, fig, default_name: str):
        """Show a right-click context menu on a matplotlib canvas.
        Allows saving/exporting the figure as PNG, PDF, SVG, or TIFF."""
        menu = QMenu(self)

        # ── PNG (high-res, lossless) ──────────────────────────────────────
        act_png = menu.addAction("🖼  Save as PNG (300 dpi)…")
        act_png.setToolTip("High-resolution raster image — best for presentations and papers.")

        act_png_screen = menu.addAction("🖼  Save as PNG (screen resolution)…")
        act_png_screen.setToolTip("Exact screen resolution — smaller file, good for quick sharing.")

        menu.addSeparator()

        # ── PDF (vector) ──────────────────────────────────────────────────
        act_pdf = menu.addAction("📄  Save as PDF (vector)…")
        act_pdf.setToolTip("Scalable vector PDF — best for publications and figure editors.")

        # ── SVG (vector) ──────────────────────────────────────────────────
        act_svg = menu.addAction("📐  Save as SVG (vector)…")
        act_svg.setToolTip("Scalable Vector Graphics — editable in Inkscape / Illustrator.")

        menu.addSeparator()

        # ── TIFF ─────────────────────────────────────────────────────────
        act_tif = menu.addAction("🔬  Save as TIFF (600 dpi, publication)…")
        act_tif.setToolTip("High-resolution TIFF at 600 dpi — standard format for journal submission.")

        menu.addSeparator()

        # ── Copy to clipboard ─────────────────────────────────────────────
        act_clip = menu.addAction("📋  Copy to clipboard (PNG)…")
        act_clip.setToolTip("Render to PNG and copy to system clipboard.")

        menu.addSeparator()

        # ── Export all canvases ───────────────────────────────────────────
        act_all_pdf = menu.addAction("📑  Export all plots to PDF…")
        act_all_pdf.setToolTip("Combine all currently visible PAE/pLDDT plots into one PDF.")

        chosen = menu.exec(
            QCursor.pos() if QT_VERSION == 6
            else QCursor.pos())
        if chosen is None:
            return

        safe = re.sub(r'[^\w\-.]', '_', default_name)

        if chosen == act_png:
            path, _ = QFileDialog.getSaveFileName(
                self, "Save as PNG", f"{safe}.png",
                "PNG Image (*.png);;All (*)")
            if path:
                try:
                    fig.savefig(path, dpi=300, bbox_inches='tight',
                                facecolor='white')
                    self._status.showMessage(f"✓ Saved: {path}")
                except Exception as e:
                    QMessageBox.critical(self, "Save PNG", str(e))

        elif chosen == act_png_screen:
            path, _ = QFileDialog.getSaveFileName(
                self, "Save as PNG (screen)", f"{safe}_screen.png",
                "PNG Image (*.png);;All (*)")
            if path:
                try:
                    fig.savefig(path, dpi=fig.dpi, bbox_inches='tight',
                                facecolor='white')
                    self._status.showMessage(f"✓ Saved: {path}")
                except Exception as e:
                    QMessageBox.critical(self, "Save PNG", str(e))

        elif chosen == act_pdf:
            path, _ = QFileDialog.getSaveFileName(
                self, "Save as PDF", f"{safe}.pdf",
                "PDF (*.pdf);;All (*)")
            if path:
                try:
                    fig.savefig(path, bbox_inches='tight',
                                facecolor='white')
                    self._status.showMessage(f"✓ Saved: {path}")
                except Exception as e:
                    QMessageBox.critical(self, "Save PDF", str(e))

        elif chosen == act_svg:
            path, _ = QFileDialog.getSaveFileName(
                self, "Save as SVG", f"{safe}.svg",
                "SVG (*.svg);;All (*)")
            if path:
                try:
                    fig.savefig(path, bbox_inches='tight',
                                facecolor='white')
                    self._status.showMessage(f"✓ Saved: {path}")
                except Exception as e:
                    QMessageBox.critical(self, "Save SVG", str(e))

        elif chosen == act_tif:
            path, _ = QFileDialog.getSaveFileName(
                self, "Save as TIFF", f"{safe}.tiff",
                "TIFF (*.tiff *.tif);;All (*)")
            if path:
                try:
                    fig.savefig(path, dpi=600, bbox_inches='tight',
                                facecolor='white')
                    self._status.showMessage(f"✓ Saved: {path}")
                except Exception as e:
                    QMessageBox.critical(self, "Save TIFF", str(e))

        elif chosen == act_clip:
            try:
                import io
                buf = io.BytesIO()
                fig.savefig(buf, format='png', dpi=150, bbox_inches='tight',
                            facecolor='white')
                buf.seek(0)
                try:
                    from PyQt6.QtGui import QImage
                except ImportError:
                    from PyQt5.QtGui import QImage
                data = buf.read()
                img  = QImage.fromData(data)
                QApplication.clipboard().setImage(img)
                self._status.showMessage("✓ PAE plot copied to clipboard")
            except Exception as e:
                QMessageBox.critical(self, "Copy to Clipboard", str(e))

        elif chosen == act_all_pdf:
            self._af3a_export_pdf()

    def _af3a_export_pdf(self):
        """Export all active PAE/pLDDT figures to a single PDF."""
        if not MATPLOTLIB_AVAILABLE:
            QMessageBox.warning(self, "Export PDF",
                "matplotlib not installed.")
            return
        canvases = getattr(self, '_af3a_active_canvases', [])
        if not canvases:
            QMessageBox.information(self, "Export PDF",
                "No plots to export.\nSelect a job first.")
            return
        path, _ = QFileDialog.getSaveFileName(
            self, "Export plots to PDF", "",
            "PDF (*.pdf);;All (*)")
        if not path:
            return
        try:
            from matplotlib.backends.backend_pdf import PdfPages
            with PdfPages(path) as pdf:
                for fig, canvas, name in canvases:
                    pdf.savefig(fig, bbox_inches='tight',
                                facecolor='white')
            self._status.showMessage(
                f"✓ Exported {len(canvases)} plot(s) → {Path(path).name}")
        except Exception as e:
            QMessageBox.critical(self, "Export PDF",
                                 f"Error:\n{e}")

    def _af3a_apply_filters(self):
        """Hide rows that fail the min-ipTM / max-PAEinter filters.

        Rows with None values in the filtered metric are shown only when
        the filter is at its permissive default (ipTM >= 0.0 or
        PAEinter <= 32.0). This prevents surprise hiding of legacy
        jobs that lack a given metric.
        """
        if not hasattr(self, '_af3a_filter_iptm'):
            return
        min_iptm = self._af3a_filter_iptm.value()
        max_paei = self._af3a_filter_paei.value()
        user_role = self._af3a_user_role()
        n_vis = 0
        for row in range(self._af3a_table.rowCount()):
            item0 = self._af3a_table.item(row, 0)
            if item0 is None:
                continue
            idx = item0.data(user_role)
            try:
                res = self._af3_analysis_results[int(idx)]
            except (IndexError, TypeError, ValueError):
                continue
            iptm = res.get('iptm')
            paei = res.get('pae_inter')
            hide = False
            if min_iptm > 0.0:
                if iptm is None or iptm < min_iptm:
                    hide = True
            if not hide and max_paei < 32.0:
                if paei is None or paei > max_paei:
                    hide = True
            self._af3a_table.setRowHidden(row, hide)
            if not hide:
                n_vis += 1
        total = self._af3a_table.rowCount()
        if total:
            extra = (f"  ({n_vis}/{total} shown)"
                     if n_vis != total else "")
            txt = self._af3a_status.text()
            # Strip any previous "(x/y shown)" suffix
            base = re.sub(r'\s*\(\d+/\d+ shown\)\s*$', '', txt)
            self._af3a_status.setText(base + extra)

    def _af3a_export_tsv(self):
        """Export the full AF3 Analysis results table to a TSV file."""
        results = getattr(self, '_af3_analysis_results', [])
        if not results:
            QMessageBox.information(
                self, "Export TSV",
                "No results to export.\nLoad an AF3 results folder first.")
            return
        path, _ = QFileDialog.getSaveFileName(
            self, "Export AF3 results to TSV",
            "af3_analysis.tsv",
            "TSV (*.tsv);;All (*)")
        if not path:
            return
        headers = [
            'job_name', 'job_dir', 'n_chains', 'chains',
            'iptm', 'ptm', 'mean_pLDDT', 'ranking_score',
            'pae_inter_mean', 'pae_min_inter', 'contact_frac_pct',
            'hotspot_score', 'hotspot_mean_pae', 'hotspot_size',
            'pae_min_best_pair',
            'best_pair', 'contact_region',
            'anchor_seq_A', 'anchor_seq_B',
            'chain_iptm', 'chain_ptm',
            'fraction_disordered', 'has_clash',
            'n_diffusion_samples',
            'high_confidence',
            # ── v2.5 — validation/duplicate metadata ──────────────────
            'seq_status',
            'seq_fingerprint',
            'duplicate_group_id',
            'duplicate_role',
            'duplicate_count',
            'completeness',
            'chain_layout_source',
            'truncated_chains',
            'ambiguous_chains',
            'validation_warnings',
        ]

        def _fmt(v, fmt='{:.4f}'):
            if v is None:
                return ''
            try:
                return fmt.format(v)
            except (TypeError, ValueError):
                return str(v)

        try:
            with open(path, 'w', encoding='utf-8') as f:
                f.write('\t'.join(headers) + '\n')
                for res in results:
                    chains = ';'.join(
                        f"{res['chain_to_orf'].get(c, c)}({res['chain_lens'][c]})"
                        for c in res.get('chain_order', []))
                    bp = res.get('best_pair', ('?', '?'))
                    bp_str = (f"{res['chain_to_orf'].get(bp[0], bp[0])}"
                              f"-{res['chain_to_orf'].get(bp[1], bp[1])}"
                              if isinstance(bp, tuple) and len(bp) == 2
                              else '')
                    iptm = res.get('iptm')
                    paei = res.get('pae_inter')
                    hc = ('yes' if (iptm is not None and paei is not None
                                    and iptm > 0.75 and paei < 8.0)
                          else 'no')
                    # Rich per-pair metrics for best pair
                    bp_pm = res.get('pair_metrics', {}).get(bp, {})
                    pae_min_s     = _fmt(bp_pm.get('pair_pae_min'), '{:.3f}')
                    contact_frac_s= _fmt((res.get('contact_frac') or 0) * 100, '{:.1f}')
                    _hs           = res.get('hotspot') or {}
                    hotspot_sc_s  = _fmt(_hs.get('hotspot_score'),    '{:.3f}')
                    hotspot_pae_s = _fmt(_hs.get('hotspot_mean_pae'), '{:.2f}')
                    _hsa, _hsb    = _hs.get('hotspot_size_A'), _hs.get('hotspot_size_B')
                    hotspot_sz_s  = f"{_hsa}x{_hsb}" if (_hsa and _hsb) else ''
                    anchor_seq_a, anchor_seq_b = self._af3a_anchor_sequence_texts(res)
                    anchor_seq_a = anchor_seq_a.replace('\t', ' ').replace('\n', ' ')
                    anchor_seq_b = anchor_seq_b.replace('\t', ' ').replace('\n', ' ')
                    # Per-chain metric stringification
                    ci_s = (';'.join(_fmt(x, '{:.3f}')
                                     for x in res['chain_iptm'])
                            if res.get('chain_iptm') else '')
                    cp_s = (';'.join(_fmt(x, '{:.3f}')
                                     for x in res['chain_ptm'])
                            if res.get('chain_ptm') else '')
                    has_clash = res.get('has_clash')
                    clash_s = ('yes' if (has_clash is True
                                         or (isinstance(has_clash,
                                                         (int, float))
                                             and has_clash >= 0.5))
                               else ('no' if has_clash is not None else ''))
                    row = [
                        res.get('job_name', ''),
                        res.get('job_dir', ''),
                        str(res.get('n_chains', '')),
                        chains,
                        _fmt(iptm),
                        _fmt(res.get('ptm')),
                        _fmt(res.get('mean_plddt'), '{:.2f}'),
                        _fmt(res.get('ranking_score')),
                        _fmt(paei, '{:.3f}'),
                        pae_min_s,
                        contact_frac_s,
                        hotspot_sc_s,
                        hotspot_pae_s,
                        hotspot_sz_s,
                        pae_min_s,
                        bp_str,
                        (res.get('contact_region') or '')
                            .replace('\t', ' ').replace('\n', ' '),
                        anchor_seq_a,
                        anchor_seq_b,
                        ci_s,
                        cp_s,
                        _fmt(res.get('fraction_disordered'), '{:.4f}'),
                        clash_s,
                        str(len(res.get('ranking_samples', []))),
                        hc,
                        # ── v2.5 fields ────────────────────────────────
                        res.get('seq_status', '') or '',
                        res.get('seq_fingerprint', '') or '',
                        str(res.get('duplicate_group_id', -1)),
                        res.get('duplicate_role', '') or '',
                        str(res.get('duplicate_count', 1)),
                        res.get('completeness', '') or '',
                        res.get('chain_layout_source', '') or '',
                        # Truncation info → semicolon-joined "chain:modeled/expected"
                        ';'.join(
                            f"{t['chain']}:{t['modeled']}/{t['expected']}"
                            for t in (res.get('truncation_info') or [])),
                        # Ambiguity info → semicolon-joined "chain:cands"
                        ';'.join(
                            f"{chr(65 + a['chain_index'])}:"
                            f"{'|'.join(a['candidates'])}"
                            for a in (res.get('ambiguity_info') or [])),
                        # Validation warnings → joined with " || " (no tabs)
                        ' || '.join(
                            (res.get('validation_warnings') or []))
                            .replace('\t', ' ').replace('\n', ' '),
                    ]
                    f.write('\t'.join(row) + '\n')
            self._status.showMessage(
                f"✓ Exported {len(results)} row(s) → {Path(path).name}")
        except Exception as e:
            QMessageBox.critical(self, "Export TSV",
                                 f"Error:\n{e}")

    # ═══════════════════════════════════════════════════════════
    # Motif detection — UI handlers (v1.16)
    # ═══════════════════════════════════════════════════════════

    def _af3a_selected_result_index(self):
        """Return (view_row, result_index, result_dict) for current table selection."""
        rows = set(idx.row() for idx in self._af3a_table.selectedIndexes())
        if not rows:
            return None, None, None
        view_row = min(rows)
        item0 = self._af3a_table.item(view_row, 0)
        if item0 is None:
            return None, None, None
        res_idx = item0.data(self._af3a_user_role())
        if res_idx is None:
            res_idx = view_row
        try:
            res_idx = int(res_idx)
        except (TypeError, ValueError):
            return None, None, None
        if not (0 <= res_idx < len(self._af3_analysis_results)):
            return None, None, None
        return view_row, res_idx, self._af3_analysis_results[res_idx]

    def _af3a_refresh_hotspot_status(self):
        """Update the motif/hotspot summary label without scanning heavy files."""
        results = getattr(self, '_af3_analysis_results', []) or []
        n_hot = sum(1 for r in results if (r.get('hotspot') or {}).get('hotspot_score') is not None)
        total_motifs = sum(len(r.get('motifs') or []) for r in results)
        if hasattr(self, '_af3a_motif_count_lbl'):
            self._af3a_motif_count_lbl.setText(
                f"hotspots {n_hot}/{len(results)} job(s); motifs {total_motifs}")

    def _af3a_rerun_motifs(self):
        """Lazy-safe rerun: process only the selected job.

        Older builds re-ran motif detection across every loaded result when a
        parameter changed.  That is incompatible with lazy loading for large
        interactomes because it can force thousands of PAE matrices into memory.
        This method now delegates to the explicit selected-row command.
        """
        self._af3a_run_hotspots_selected()

    def _af3a_run_hotspots_selected(self):
        """Load heavy arrays and run hotspot/motif analysis for one row."""
        view_row, res_idx, res = self._af3a_selected_result_index()
        if res is None:
            QMessageBox.information(
                self, "Run hotspot",
                "Select one AF3 result row first.")
            return
        self._af3a_run_hotspots_for_results([res], label="selected job")
        # Re-select the same row if possible and refresh the visible plot.
        try:
            self._af3a_table.selectRow(view_row)
        except Exception:
            pass
        self._af3a_replot_selected()

    def _af3a_visible_ranked_candidates(self, limit=None):
        """Return visible rows ranked by PAE_min ascending, cp_ipTM descending.

        This implements the intended large-screen workflow:
            summary scan -> rank/filter -> user clicks Run visible/top.
        Only rows currently visible after table filters are considered.
        """
        table = self._af3a_table
        candidates = []
        for view_row in range(table.rowCount()):
            if table.isRowHidden(view_row):
                continue
            res = self._af3a_res_for_view_row(view_row)
            if res is None:
                continue
            pae_min = res.get('pae_min_inter')
            cp_iptm = res.get('cp_iptm_inter')
            iptm = res.get('iptm')
            # rows without PAE_min go to the end, but remain eligible
            pae_rank = float(pae_min) if pae_min is not None else float('inf')
            cp_rank = float(cp_iptm) if cp_iptm is not None else -1.0
            iptm_rank = float(iptm) if iptm is not None else -1.0
            candidates.append((pae_rank, -cp_rank, -iptm_rank, view_row, res))
        candidates.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        if limit is not None:
            candidates = candidates[:max(0, int(limit))]
        return [res for *_rest, res in candidates]

    def _af3a_run_hotspots_visible_top(self):
        """Run hotspot/motif analysis on the top N visible candidates only."""
        if not getattr(self, '_af3_analysis_results', []):
            QMessageBox.information(
                self, "Run hotspots",
                "No AF3 results loaded.")
            return
        try:
            limit = self._af3a_hotspot_topn_spin.value()
        except Exception:
            limit = 100
        selected = self._af3a_visible_ranked_candidates(limit=limit)
        if not selected:
            QMessageBox.information(
                self, "Run hotspots",
                "No visible candidates to process. Adjust the filters first.")
            return
        try:
            yes = (QMessageBox.StandardButton.Yes
                   if QT_VERSION == 6 else QMessageBox.Yes)
            no = (QMessageBox.StandardButton.No
                  if QT_VERSION == 6 else QMessageBox.No)
            ans = QMessageBox.question(
                self, "Run hotspots on visible/top candidates",
                f"Run hotspot/motif analysis on the top {len(selected)} visible "
                "candidate(s)?\n\n"
                "Ranking: PAE_min ascending, then cp_ipTM descending.\n"
                "Only these jobs will load full PAE/contact matrices; the rest "
                "remain summary-only.",
                yes | no)
            if ans != yes:
                return
        except Exception:
            pass
        self._af3a_run_hotspots_for_results(
            selected, label=f"top {len(selected)} visible job(s)")
        self._af3a_populate_table()
        self._af3a_apply_filters()

    def _af3a_run_hotspots_for_results(self, results, label="candidate jobs"):
        """Core lazy batch runner for hotspots and motifs.

        Each job is loaded, hotspot/motif summaries are computed, then heavy
        PAE/contact/pLDDT arrays from other jobs are released.  Only compact
        summaries remain in memory and in the export table.
        """
        if not results:
            return
        # Read current motif parameters once.
        try:
            pae_core = self._af3a_motif_core_spin.value()
            pae_ext = self._af3a_motif_ext_spin.value()
            min_ct = self._af3a_motif_contact_spin.value()
            min_sz = self._af3a_motif_size_spin.value()
            recip = self._af3a_motif_recip_cb.isChecked()
        except Exception:
            pae_core = self._AF3_MOTIF_PAE_CORE
            pae_ext = self._AF3_MOTIF_PAE_EXT
            min_ct = self._AF3_MOTIF_MIN_CONTACT
            min_sz = self._AF3_MOTIF_MIN_SIZE
            recip = True
        if pae_ext <= pae_core:
            pae_ext = pae_core + 1.0

        # Progress dialog for long runs.
        try:
            from PyQt6.QtWidgets import QProgressDialog
        except Exception:
            try:
                from PyQt5.QtWidgets import QProgressDialog
            except Exception:
                QProgressDialog = None
        progress = None
        if QProgressDialog and len(results) > 1:
            progress = QProgressDialog(
                f"Running hotspots on {label}...", "Cancel", 0, len(results), self)
            progress.setWindowTitle("ppigFinder hotspot analysis")
            progress.setMinimumDuration(0)
            progress.setValue(0)

        processed = 0
        failed = []
        total_motifs = 0
        for i, res in enumerate(results, start=1):
            if progress is not None:
                progress.setLabelText(
                    f"Running hotspot/motif analysis ({i}/{len(results)})\n"
                    f"{res.get('job_name', '')}")
                progress.setValue(i - 1)
                QApplication.processEvents()
                if progress.wasCanceled():
                    break
            try:
                # v29.14 FIX: force a re-parse so hotspot metrics are actually
                # recomputed with the CURRENT radius.  Previously
                # _af3a_ensure_heavy_loaded returned immediately for any job
                # already marked heavy_loaded, so pressing "Run hotspots" a
                # second time (or after changing Hotspot+/-) silently reused
                # stale hotspot values and only refreshed the motifs.
                res['heavy_loaded'] = False
                # This loads full PAE/contact matrices only for this job and
                # recomputes hotspot metrics inside _af3a_parse_job(lazy=False).
                res = self._af3a_ensure_heavy_loaded(res)
                # Motifs are recomputed here with the current parameters so the
                # run button is authoritative after parameter changes.
                motifs = self._af3a_detect_motifs(
                    res, pae_core, pae_ext, min_ct, min_sz,
                    require_reciprocal=recip)
                res['motifs'] = motifs
                total_motifs += len(motifs)
                processed += 1
                # Immediately release other heavy results and keep this one
                # only until the next iteration; summary fields stay stored.
                self._af3a_unload_heavy_except(res)
            except Exception as e:
                failed.append(f"{res.get('job_name','?')}: {e}")

        if progress is not None:
            progress.setValue(len(results))
        # Leave memory bounded: unload every heavy job except the currently
        # selected row, so browsing still feels immediate.
        _, _, selected_res = self._af3a_selected_result_index()
        self._af3a_unload_heavy_except(selected_res)
        self._af3a_refresh_hotspot_status()
        try:
            self._af3a_status.setText(
                f"Hotspots computed for {processed}/{len(results)} job(s); "
                f"motifs={total_motifs}")
        except Exception:
            pass
        if failed:
            QMessageBox.warning(
                self, "Run hotspots",
                "Some jobs failed during hotspot analysis:\n\n" +
                "\n".join(failed[:12]) +
                (f"\n... plus {len(failed)-12} more" if len(failed) > 12 else ""))

    def _af3a_export_motifs_tsv(self):
        """Export every detected motif from every loaded job to TSV."""
        results = getattr(self, '_af3_analysis_results', [])
        if not results:
            QMessageBox.information(
                self, "Export motifs TSV",
                "No results loaded.")
            return
        # Count motifs up front so we don't prompt for a path then
        # write an empty file.
        total = sum(len(r.get('motifs') or []) for r in results)
        if total == 0:
            QMessageBox.information(
                self, "Export motifs TSV",
                "No motifs detected with the current thresholds.\n"
                "Try relaxing 'core PAE' or 'min contact'.")
            return
        path, _ = QFileDialog.getSaveFileName(
            self, "Export motifs TSV",
            "af3_motifs.tsv",
            "TSV (*.tsv);;All (*)")
        if not path:
            return

        def _fmt(v, f='{:.4f}'):
            if v is None: return ''
            try: return f.format(v)
            except (TypeError, ValueError): return str(v)

        headers = [
            'job_name', 'rank', 'score',
            'chain_A', 'orf_A', 'a_start', 'a_end', 'len_A_motif',
            'chain_B', 'orf_B', 'b_start', 'b_end', 'len_B_motif',
            'mean_PAE', 'min_PAE', 'density',
            'mean_contact', 'max_contact',
            'plddt_A', 'plddt_B', 'plddt_mean',
            'reciprocal', 'recip_overlap',
            'label',
        ]
        try:
            with open(path, 'w', encoding='utf-8') as f:
                f.write('\t'.join(headers) + '\n')
                for res in results:
                    for m in (res.get('motifs') or []):
                        row = [
                            res.get('job_name', ''),
                            str(m.get('rank', '')),
                            _fmt(m.get('score'), '{:.2f}'),
                            m.get('chain_A', ''),
                            m.get('name_A', ''),
                            str(m.get('a_start', '')),
                            str(m.get('a_end', '')),
                            str(m.get('height', '')),
                            m.get('chain_B', ''),
                            m.get('name_B', ''),
                            str(m.get('b_start', '')),
                            str(m.get('b_end', '')),
                            str(m.get('width', '')),
                            _fmt(m.get('mean_pae'), '{:.3f}'),
                            _fmt(m.get('min_pae'),  '{:.3f}'),
                            _fmt(m.get('density'),  '{:.3f}'),
                            _fmt(m.get('mean_contact')),
                            _fmt(m.get('max_contact')),
                            _fmt(m.get('plddt_A'), '{:.2f}'),
                            _fmt(m.get('plddt_B'), '{:.2f}'),
                            _fmt(m.get('plddt_mean'), '{:.2f}'),
                            'yes' if m.get('reciprocal') else 'no',
                            _fmt(m.get('recip_overlap'), '{:.2f}'),
                            m.get('label', ''),
                        ]
                        f.write('\t'.join(row) + '\n')
            self._status.showMessage(
                f"✓ Exported {total} motif(s) → {Path(path).name}")
        except OSError as e:
            QMessageBox.critical(self, "Export motifs TSV",
                                 f"Error:\n{e}")

    def _af3a_build_motif_table(self, res: dict):
        """Build a QTableWidget listing every detected motif for the
        selected job. Appended to the plot layout below the pLDDT plot.

        Clicking a row highlights that motif on the PAE heatmap.
        """
        motifs = res.get('motifs') or []
        lbl = QLabel(
            f"<b>🎯 Detected interaction motifs</b>  "
            f"— {len(motifs)} found"
            + ("" if motifs
               else "  <span style='color:#888'>(try relaxing thresholds)</span>"))
        lbl.setStyleSheet(
            "font-size:11px;padding:6px 8px;"
            "background:#ECEFF1;border-radius:4px;margin-top:8px;")
        lbl.setTextFormat(
            Qt.TextFormat.RichText if QT_VERSION == 6 else Qt.RichText)
        self._af3a_plot_layout.addWidget(lbl)

        if not motifs:
            return

        table = QTableWidget()
        # NB: no sorting — rows are already sorted by score desc and the
        # row index must match `motifs[i]` for the highlight click.
        table.setColumnCount(10)
        table.setHorizontalHeaderLabels([
            '#', 'Score', 'ORF A region', 'ORF B region',
            'Size (aa)', 'PAE mean', 'PAE min',
            'Density', 'pLDDT', 'Recip.'])
        table.setRowCount(len(motifs))
        table.setAlternatingRowColors(True)
        table.setSelectionBehavior(
            QAbstractItemView.SelectionBehavior.SelectRows
            if QT_VERSION == 6 else QAbstractItemView.SelectRows)
        table.setEditTriggers(
            QAbstractItemView.EditTrigger.NoEditTriggers
            if QT_VERSION == 6 else QAbstractItemView.NoEditTriggers)
        table.verticalHeader().setVisible(False)
        # Compact; it sits below the plots and is scrollable via parent
        row_h = 22
        table.setMaximumHeight(
            min(8, len(motifs)) * row_h + table.horizontalHeader().height()
            + 4)

        def _plddt_color(v):
            if v is None: return None
            if v >= 90: return QColor('#0D47A1')   # very high
            if v >= 70: return QColor('#1976D2')   # confident
            if v >= 50: return QColor('#FBC02D')   # low
            return QColor('#E64A19')               # very low

        for i, m in enumerate(motifs):
            size_s = f"{m['height']}×{m['width']}"
            pae_mean_s = f"{m['mean_pae']:.1f}"
            pae_min_s  = f"{m['min_pae']:.1f}"
            dens_s     = f"{m['density']*100:.0f}%"
            plddt_s    = (f"{m['plddt_mean']:.0f}"
                          if m.get('plddt_mean') is not None else '-')
            recip_s    = ('✓ {:.0%}'.format(m['recip_overlap'])
                          if m.get('reciprocal') else '✗')
            cells = [
                f"#{m['rank']}",
                f"{m['score']:.1f}",
                f"{m['name_A']} {m['a_start']}-{m['a_end']}",
                f"{m['name_B']} {m['b_start']}-{m['b_end']}",
                size_s,
                pae_mean_s, pae_min_s, dens_s, plddt_s, recip_s,
            ]
            for c, val in enumerate(cells):
                it = QTableWidgetItem(val)
                it.setTextAlignment(
                    Qt.AlignmentFlag.AlignCenter if QT_VERSION == 6
                    else Qt.AlignCenter)
                if c == 1:   # Score column — colour by value
                    if m['score'] >= 60:
                        it.setBackground(QColor('#C8E6C9'))
                    elif m['score'] >= 40:
                        it.setBackground(QColor('#FFF9C4'))
                    else:
                        it.setBackground(QColor('#FFCDD2'))
                if c == 8 and m.get('plddt_mean') is not None:
                    pc = _plddt_color(m['plddt_mean'])
                    if pc is not None:
                        f = it.font(); f.setBold(True); it.setFont(f)
                        it.setForeground(pc)
                table.setItem(i, c, it)
        table.resizeColumnsToContents()
        table.horizontalHeader().setStretchLastSection(True)
        self._af3a_plot_layout.addWidget(table)

        # Clicking a row highlights the motif in the PAE heatmap. We
        # do this by storing the latest PAE axes reference on self and
        # drawing a highlight rectangle that survives until another
        # motif is clicked.
        def _on_motif_select():
            rows = set(idx.row() for idx in table.selectedIndexes())
            if not rows:
                return
            i = min(rows)
            if 0 <= i < len(motifs):
                self._af3a_highlight_motif(motifs[i])
        table.selectionModel().selectionChanged.connect(
            lambda *_: _on_motif_select())

    def _af3a_highlight_motif(self, motif: dict):
        """Flash a highlight rectangle around a motif on the PAE axes.

        Uses the matplotlib axes reference stashed on self during the
        last plot, if any.
        """
        ax = getattr(self, '_af3a_last_pae_ax', None)
        canvas = getattr(self, '_af3a_last_pae_canvas', None)
        if ax is None or canvas is None:
            return
        # Remove previous highlight if any
        prev = getattr(self, '_af3a_highlight_patches', [])
        for p in prev:
            try: p.remove()
            except Exception: pass
        patches = []
        # Draw on A↔B quadrant
        r0 = motif['abs_row0']; r1 = motif['abs_row1']
        c0 = motif['abs_col0']; c1 = motif['abs_col1']
        patches.append(ax.add_patch(plt.Rectangle(
            (c0 - 0.5, r0 - 0.5), c1 - c0 + 1, r1 - r0 + 1,
            facecolor='none', edgecolor='#FF1744',
            linewidth=2.5, linestyle='-', zorder=10)))
        # And the mirrored B↔A quadrant (show the user both sides)
        patches.append(ax.add_patch(plt.Rectangle(
            (r0 - 0.5, c0 - 0.5), r1 - r0 + 1, c1 - c0 + 1,
            facecolor='none', edgecolor='#FF1744',
            linewidth=2.5, linestyle='--', alpha=0.8, zorder=10)))
        self._af3a_highlight_patches = patches
        canvas.draw_idle()

    # ═══════════════════════════════════════════════════════════
    # HPC SERVER TAB (generic)
    # ═══════════════════════════════════════════════════════════

    # ══════════════════════════════════════════════════════════════════════
    # PPI GENOMIC ARC MAP TAB  (Tab 11, v2.0)
    # Shows all AF3-predicted interactions as arcs drawn above a linear
    # genome map. Arcs are coloured by PAE_min / ipTM and height-scaled
    # by genomic distance between the two partners.
    # ══════════════════════════════════════════════════════════════════════




    def _ppi_arc_update_legend(self):
        """Refresh the bottom legend of the Genomic PPI Map so its three
        PAE labels reflect the current user-set HIGH/MED thresholds.

        Robust to the exact way the legend was originally built: walks every
        QLabel that lives inside the legend bar and rewrites text starting
        with 'PAE_min'.  Other legend items (HMM hit ORF / Custom / etc.)
        are left untouched.
        """
        try:
            hi = float(_PpiArcMapWidget._PAE_HIGH)
            md = float(_PpiArcMapWidget._PAE_MED)
        except Exception:
            return
        try:
            host = getattr(self, '_ppi_map_tab_widget', None)
            if host is None:
                return
            from PyQt6.QtWidgets import QLabel as _QLabel
        except Exception:
            try:
                from PyQt5.QtWidgets import QLabel as _QLabel
            except Exception:
                return
        try:
            host = self._ppi_map_tab_widget
            for child in host.findChildren(_QLabel):
                txt = child.text() or ""
                low = txt.lower()
                if "pae_min" not in low:
                    continue
                if "high" in low:
                    child.setText(f"PAE_min < {hi:g} Å (HIGH)")
                elif "med" in low:
                    child.setText(f"PAE_min {hi:g}–{md:g} Å (MED)")
                elif "low" in low:
                    child.setText(f"PAE_min > {md:g} Å (LOW)")
        except Exception as e:
            print(f"[ppigFinder] _ppi_arc_update_legend: {e}")

    def _ppi_thresholds_changed(self, *_):
        """Propagate user-set thresholds to every dependent computation.

        Updates the class-level PAE_HIGH / PAE_MED / cp_ipTM constants used
        by the arc widget and all analytical views, then triggers a full
        refresh of the Genomic PPI Map and (if visible) the PPI Analysis
        tab.  Called whenever any of the three spinboxes changes value.
        """
        try:
            hi = float(self._ppi_thr_high.value())
            md = float(self._ppi_thr_med.value())
            cp = float(self._ppi_thr_cpip.value())
            # Sanity: MED must be strictly greater than HIGH
            if md <= hi:
                md = hi + 0.1
                # update the spinbox silently
                self._ppi_thr_med.blockSignals(True)
                self._ppi_thr_med.setValue(md)
                self._ppi_thr_med.blockSignals(False)
            _PpiArcMapWidget._PAE_HIGH = hi
            _PpiArcMapWidget._PAE_MED  = md
            _PpiArcMapWidget._CP_IPTM_FOCAL = cp
            # Re-classify and redraw the Genomic PPI Map
            try:
                self._ppi_arc_map_refresh()
            except Exception:
                pass
            try:
                self._ppi_arc_widget.update()
            except Exception:
                pass
            # Refresh the analysis suite if its widgets exist
            try:
                if hasattr(self, '_ppi_an_subtabs'):
                    self._ppi_analysis_refresh()
            except Exception:
                pass
            # Refresh the bottom legend (HIGH/MED text)
            try:
                self._ppi_arc_update_legend()
            except Exception:
                pass
        except Exception as e:
            print(f"[ppigFinder] _ppi_thresholds_changed: {e}")


    def _ppi_an_on_dot_click(self, orf_idx):
        """Left-click on a PPI Analysis dot — select & centre the ORF."""
        try:
            if 0 <= int(orf_idx) < len(self.orfs):
                self._select_and_center_orf(int(orf_idx))
        except Exception as e:
            print(f"[ppigFinder] _ppi_an_on_dot_click: {e}")

    def _ppi_predictions_for_orf(self, orf_idx):
        """v29.11.2 — return every AF3 prediction (analysis-results dict)
        that includes ORF *orf_idx* as one of its chains.  Sorted by best
        (lowest) PAE_min first so the most informative hit is on top.

        BUG FIX (v29.11.2): the analysis-result dict does NOT store
        'orf_a_index' / 'orf_b_index'.  It stores
            • 'orf_names'    — list of 'ORF<n>' strings
            • 'chain_to_orf' — dict chain_id → 'ORF<n>'  (or ORF dict)
        We resolve the 1-based suffix in each name (matching the rest of
        the application) and accept either field as a source.
        """
        out = []
        target_name_upper = f"ORF{int(orf_idx) + 1}"

        def _name_to_idx(name):
            """Resolve 'ORF<n>' → 0-based int; return -1 if not resolvable."""
            if name is None:
                return -1
            if isinstance(name, dict):
                # chain_to_orf may store ORF dicts directly
                try:
                    o_in_orfs = name in (getattr(self, 'orfs', []) or [])
                    if o_in_orfs:
                        return (getattr(self, 'orfs', []) or []).index(name)
                except Exception:
                    pass
                return -1
            try:
                s = str(name).upper().strip()
            except Exception:
                return -1
            if s.startswith('ORF'):
                try:
                    return int(s[3:]) - 1
                except (ValueError, TypeError):
                    pass
            # Last-resort: trailing digits in the string
            try:
                import re as _re
                nums = _re.findall(r'\d+', s)
                if nums:
                    return int(nums[-1]) - 1
            except Exception:
                pass
            return -1

        for r in getattr(self, '_af3_analysis_results', []) or []:
            try:
                hit = False
                # Primary path: 'orf_names' list (1 entry per chain)
                for nm in (r.get('orf_names') or []):
                    if _name_to_idx(nm) == orf_idx:
                        hit = True
                        break
                # Fallback path: 'chain_to_orf' dict
                if not hit:
                    cmap = r.get('chain_to_orf') or {}
                    for v in cmap.values():
                        if _name_to_idx(v) == orf_idx:
                            hit = True
                            break
                if hit:
                    out.append(r)
            except Exception as _e:
                continue

        def _key(r):
            for fld in ('chain_pair_pae_min', 'pae_min_inter', 'pae_min'):
                v = r.get(fld)
                if v is not None:
                    try:
                        return float(v)
                    except (TypeError, ValueError):
                        continue
            return 1e9

        out.sort(key=_key)
        return out

    def _ppi_open_af3_prediction_for_orf(self, orf_idx):
        """v29.11.1 — open the AF3 prediction folder of the strongest
        interaction involving *orf_idx*.  If more than one prediction
        involves the ORF, the user is asked to choose.
        """
        preds = self._ppi_predictions_for_orf(orf_idx)
        if not preds:
            QMessageBox.information(
                self, "Open AF3 prediction folder",
                f"ORF{orf_idx+1} does not appear in any loaded AF3 prediction.")
            return
        if len(preds) == 1:
            self._open_af3_job_folder(preds[0].get('job_dir', ''))
            return
        # Show a small picker dialog
        try:
            from PyQt6.QtWidgets import (QDialog, QVBoxLayout, QListWidget,
                                          QListWidgetItem, QDialogButtonBox,
                                          QLabel)
        except ImportError:
            from PyQt5.QtWidgets import (QDialog, QVBoxLayout, QListWidget,
                                          QListWidgetItem, QDialogButtonBox,
                                          QLabel)
        dlg = QDialog(self)
        dlg.setWindowTitle(f"AF3 predictions involving ORF{orf_idx+1}")
        dlg.resize(640, 360)
        v = QVBoxLayout(dlg)
        v.addWidget(QLabel(
            f"ORF{orf_idx+1} appears in {len(preds)} AF3 predictions. "
            "Select one to open its folder:"))
        lst = QListWidget()
        # v29.11.2 — robust partner-name resolution from orf_names list
        def _other_label(r, this_idx):
            names = r.get('orf_names') or []
            target = f"ORF{this_idx + 1}"
            others = [nm for nm in names if str(nm).upper() != target.upper()]
            if others:
                return ", ".join(others[:3]) + (" …" if len(others) > 3 else "")
            cmap = r.get('chain_to_orf') or {}
            others = [str(v) for v in cmap.values()
                      if str(v).upper() != target.upper()]
            if others:
                return ", ".join(others[:3])
            return "?"

        for r in preds:
            jn = r.get('job_name', '?')
            other_lbl = _other_label(r, orf_idx)
            pae = (r.get('chain_pair_pae_min')
                   or r.get('pae_min_inter')
                   or r.get('pae_min'))
            pae_lbl = f"PAE_min={pae:.2f} Å" if pae is not None else "PAE_min=?"
            cp = (r.get('chain_pair_iptm')
                  or r.get('cp_iptm_inter')
                  or r.get('cp_iptm'))
            cp_lbl = f"cp_ipTM={cp:.2f}" if cp is not None else ""
            txt = f"{jn}   ({other_lbl},  {pae_lbl}{('   '+cp_lbl) if cp_lbl else ''})"
            it = QListWidgetItem(txt)
            it.setData(32, r.get('job_dir', ''))  # 32 = Qt::UserRole
            lst.addItem(it)
        v.addWidget(lst, 1)
        btns = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Open
            | QDialogButtonBox.StandardButton.Cancel
            if QT_VERSION == 6 else
            QDialogButtonBox.Open | QDialogButtonBox.Cancel)
        btns.accepted.connect(dlg.accept)
        btns.rejected.connect(dlg.reject)
        v.addWidget(btns)
        if lst.count() > 0:
            lst.setCurrentRow(0)
        if (dlg.exec() if QT_VERSION == 6 else dlg.exec_()):
            it = lst.currentItem()
            if it is not None:
                self._open_af3_job_folder(it.data(32) or '')

    def _ppi_an_on_dot_context(self, orf_idx, global_pos):
        """Right-click on a PPI Analysis dot — focused context menu."""
        try:
            from PyQt6.QtWidgets import QMenu, QApplication
        except ImportError:
            from PyQt5.QtWidgets import QMenu, QApplication
        try:
            orf_idx = int(orf_idx)
            if not (0 <= orf_idx < len(self.orfs)):
                return
            orf = self.orfs[orf_idx]
            n_preds = len(self._ppi_predictions_for_orf(orf_idx))
            menu = QMenu(self)
            menu.addAction(
                f"📍 Center Genome Map on ORF{orf_idx+1}",
                lambda: self._select_and_center_orf(orf_idx))
            menu.addAction(
                f"📋 Select ORF{orf_idx+1} in table",
                lambda: self._select_and_center_orf(orf_idx))
            menu.addSeparator()
            # v29.11.1 — Open AF3 prediction folder action.  Always shown,
            # but disabled when no prediction exists.
            act_open = menu.addAction(
                f"📂 Open AF3 prediction folder"
                + (f"  ({n_preds} predictions)" if n_preds > 1 else ""),
                lambda: self._ppi_open_af3_prediction_for_orf(orf_idx))
            act_open.setEnabled(n_preds > 0)
            if n_preds == 0:
                act_open.setToolTip(
                    "No AF3 prediction loaded for this ORF.")
            menu.addSeparator()
            menu.addAction(
                f"⎘ Copy ORF ID  (ORF{orf_idx+1})",
                lambda: QApplication.clipboard().setText(f"ORF{orf_idx+1}"))
            menu.addAction(
                "⎘ Copy protein sequence",
                lambda: QApplication.clipboard().setText(
                    orf.get('protein', '') or ''))
            menu.addAction(
                "⎘ Copy DNA sequence",
                lambda: QApplication.clipboard().setText(
                    orf.get('dna', '') or ''))
            menu.addSeparator()
            menu.addAction(
                f"➕ Add ORF{orf_idx+1} to AF3 list",
                lambda: self._orf_table_af3_add_multi([orf_idx], switch_tab=True))
            menu.addAction(
                f"🔎 Pfam-A search on ORF{orf_idx+1} (with alignment)",
                lambda: self._pfam_search_selection([orf_idx]))
            menu.addSeparator()
            details = []
            details.append(f"ORF{orf_idx+1}  ({orf.get('size_aa', 0)} aa)")
            details.append(f"  pos: {orf.get('start','?')}–{orf.get('end','?')}")
            details.append(f"  strand: {orf.get('strand','?')}")
            details.append(f"  source: {orf.get('source','?')}")
            hmm_hits = orf.get('hmm_hits') or []
            if hmm_hits:
                details.append(f"  HMM hits: {len(hmm_hits)}")
            if n_preds > 0:
                details.append(f"  AF3 predictions: {n_preds}")
            menu.addAction("ℹ Show ORF details",
                lambda d="\n".join(details): QMessageBox.information(
                    self, f"ORF{orf_idx+1} details", d))
            menu.exec(global_pos) if QT_VERSION == 6 else menu.exec_(global_pos)
        except Exception as e:
            print(f"[ppigFinder] _ppi_an_on_dot_context: {e}")

