    def _ppi_detect_query(self, arcs):
        """Return the index of the ORF that appears as either side of every
        arc, or None if there is no such global query ORF."""
        if not arcs:
            return None
        # Build sets of orf ids that appear on each side
        a_set = set()
        b_set = set()
        for a in arcs:
            oa = a.get('orf_idx_a')
            ob = a.get('orf_idx_b')
            if oa is not None: a_set.add(oa)
            if ob is not None: b_set.add(ob)
        # An ORF is a "query" if it appears in EVERY arc.
        # Equivalently, it is in (a_set ∩ b_set complement) OR appears on
        # only one side in all arcs.  We check by counting.
        from collections import Counter
        count = Counter()
        for a in arcs:
            oa = a.get('orf_idx_a')
            ob = a.get('orf_idx_b')
            if oa is not None: count[oa] += 1
            if ob is not None: count[ob] += 1
        # An ORF that is present in every arc has count >= len(arcs)
        candidates = [orf for orf, c in count.items() if c >= len(arcs)]
        if len(candidates) == 1:
            return candidates[0]
        if len(candidates) > 1:
            # ambiguous (e.g. a homodimer screen); return the most-paired one
            return max(candidates, key=lambda o: count[o])
        return None

    def _ppi_populate_posset(self, hmm_p):
        """Populate the positive-set dropdown with current HMM profiles."""
        try:
            cur = self._ppi_an_posset.currentText()
        except Exception:
            cur = "(none)"
        self._ppi_an_posset.blockSignals(True)
        self._ppi_an_posset.clear()
        items = ["(none)", "(any HMM-annotated ORF)"]
        for prof in hmm_p:
            nm = prof.get('name', '') or '?'
            items.append(nm)
        self._ppi_an_posset.addItems(items)
        # restore previous selection if still present
        idx = self._ppi_an_posset.findText(cur)
        self._ppi_an_posset.setCurrentIndex(idx if idx >= 0 else 0)
        self._ppi_an_posset.blockSignals(False)

    def _ppi_analysis_refresh(self):
        """Recompute all six analytical views — fully generic."""
        try:
            arcs   = getattr(self._ppi_arc_widget, '_arcs', []) \
                     if hasattr(self, '_ppi_arc_widget') else []
            orfs   = getattr(self._ppi_arc_widget, '_orfs', []) \
                     if hasattr(self, '_ppi_arc_widget') else []
            hmm_p  = getattr(self._ppi_arc_widget, '_hmm_profiles', []) \
                     if hasattr(self, '_ppi_arc_widget') else []
            dna_n  = getattr(self._ppi_arc_widget, '_dna_length', 0) \
                     if hasattr(self, '_ppi_arc_widget') else 0
            if not hmm_p:
                hmm_p = getattr(self, 'hmm_profiles', []) or \
                        getattr(self, '_hmm_profiles', [])

            # Populate the positive-set dropdown lazily (also after the
            # HMM library has changed)
            try:
                if self._ppi_an_posset.count() != len(hmm_p) + 2:
                    self._ppi_populate_posset(hmm_p)
            except Exception:
                pass

            metric    = self._ppi_an_metric.currentText()
            transform = self._ppi_an_transform.currentText()
            xaxis_rule = self._ppi_an_xaxis.currentText()

            if not arcs:
                self._ppi_an_status.setText(
                    "No arcs yet. Open Genomic PPI Map and press ⟳ Refresh there first.")
                self._ppi_an_query_info.setText("Query detection: no data")
                self._ppi_an_scatter.set_data([], [], metric)
                self._ppi_an_hist.set_data([], 'PAE_min')
                self._ppi_an_roc.set_data([], set(), "(none)")
                self._ppi_an_2d.set_data([], [])
                self._ppi_an_heatmap.set_data(None, [])
                return

            # ── Detect query ORF ────────────────────────────────────────
            query_orf = self._ppi_detect_query(arcs)
            if query_orf is not None:
                qname = orfs[query_orf].get('name', f'ORF{query_orf+1}') \
                        if 0 <= query_orf < len(orfs) else f'ORF{query_orf+1}'
                self._ppi_an_query_info.setText(
                    f"Query detected: {qname} (idx={query_orf})")
            else:
                self._ppi_an_query_info.setText(
                    "Query detection: no global query (all-vs-all mode)")

            # ── ORF index → HMM profile index lookup ───────────────────
            orf_to_prof = {}
            for pi, prof in enumerate(hmm_p):
                for hit in (prof.get('hits') or []):
                    oi = hit.get('orf_index')
                    if oi is not None:
                        orf_to_prof[oi] = pi

            # ── hotspot_mean_pae lookup from raw AF3 results ───────────
            hotspot_map = {}
            # v29.11.1 — map (orf_a, orf_b) → AF3 job_dir for use by the
            # PPI Analysis dot context menu ("Open AF3 prediction folder").
            self._ppi_an_jobdir_by_pair = {}
            self._ppi_an_jobdir_by_jobname = {}
            for r in getattr(self, '_af3_analysis_results', []) or []:
                try:
                    a = r.get('orf_a_index')
                    b = r.get('orf_b_index')
                    h = (r.get('hotspot_mean_pae')
                         or (r.get('hotspot') or {}).get('hotspot_mean_pae'))
                    # v29.14 FIX: key by job_name.  'orf_a_index'/'orf_b_index'
                    # are never set on analysis-result dicts, so the previous
                    # (a, b) key left this map permanently empty.
                    if h is not None and r.get('job_name'):
                        hotspot_map[r.get('job_name')] = h
                    jd = r.get('job_dir', '')
                    jn = r.get('job_name', '')
                    if jn:
                        self._ppi_an_jobdir_by_jobname[jn] = jd
                    if a is not None and b is not None and jd:
                        # Prefer the first-seen entry for each pair to avoid
                        # overwriting with a duplicate / replicate run.
                        key = tuple(sorted((a, b)))
                        self._ppi_an_jobdir_by_pair.setdefault(key, jd)
                except Exception:
                    continue

            profiles_palette = [(p.get('name', '') or '?',
                                 p.get('color', '#1D9E75')) for p in hmm_p]

            # ── helper: which ORF index(es) of an arc to plot ───────────
            def _arc_partner_indices(a):
                oa = a.get('orf_idx_a')
                ob = a.get('orf_idx_b')
                if xaxis_rule == "ORF A":
                    return [oa] if oa is not None and oa >= 0 else []
                elif xaxis_rule == "ORF B":
                    return [ob] if ob is not None and ob >= 0 else []
                elif xaxis_rule.startswith("Either"):
                    out = []
                    if oa is not None and oa >= 0: out.append(oa)
                    if ob is not None and ob >= 0: out.append(ob)
                    return out
                else:  # Auto
                    if query_orf is not None:
                        # plot the side that is NOT the query (the partner)
                        if oa == query_orf and ob is not None and ob >= 0:
                            return [ob]
                        if ob == query_orf and oa is not None and oa >= 0:
                            return [oa]
                        # arc does not involve the query — skip
                        return []
                    else:
                        # no query → plot ORF B by default
                        if ob is not None and ob >= 0: return [ob]
                        if oa is not None and oa >= 0: return [oa]
                        return []

            # ── (1) Per-ORF scatter — generic Y = transform(base_metric) ─
            import math as _math
            EPS = 1e-6
            def _apply_transform(x, tname):
                """Safe transform with clamps to avoid 1/0, log(0), sqrt(<0)."""
                if x is None:
                    return 0.0
                try:
                    xv = float(x)
                except (TypeError, ValueError):
                    return 0.0
                if tname == 'Identity':
                    return xv
                if tname == 'Inverse (1/x)':
                    return 1.0 / (xv if abs(xv) > EPS else EPS)
                if tname == 'Squared (x²)':
                    return xv * xv
                if tname == 'Square root (√x)':
                    return _math.sqrt(xv) if xv > 0 else 0.0
                if tname == 'Log10':
                    return _math.log10(xv) if xv > EPS else _math.log10(EPS)
                if tname == 'Negative log (-log10)':
                    return -_math.log10(xv) if xv > EPS else -_math.log10(EPS)
                return xv

            def _base_value(a, base, hotspot_map):
                """Return the raw value of `base` for arc `a`, or None."""
                pae  = a.get('pae_min')
                ipt  = a.get('iptm')
                cf   = a.get('contact_frac')
                cf01 = cf if (cf is not None and cf <= 1.5) else \
                       (cf / 100.0 if cf is not None else None)
                # v29.14: hotspot comes from the arc, with the job_name map as
                # a fallback.  When it is genuinely absent the point is OMITTED
                # (None) instead of being silently replaced by PAE_min, which
                # previously made the two plots identical.  Run "Run hotspots"
                # in Interaction Results to populate this metric.
                hot = a.get('hotspot_pae')
                if hot is None:
                    hot = hotspot_map.get(a.get('job_name'))
                if base == 'PAE_min':    return pae
                if base == 'HotSpotPAE': return hot
                if base == 'Contact%':   return cf01
                if base == 'iptm':       return a.get('iptm')
                if base == 'score':      return a.get('score')
                return None

            # Default base thresholds for the dashed reference line
            BASE_THRESHOLDS = {
                'PAE_min':    _PpiArcMapWidget._PAE_HIGH,
                'HotSpotPAE': _PpiArcMapWidget._PAE_HIGH,
                'Contact%':   0.10,
                'iptm':       0.50,
                'score':      None,
            }
            base_thr = BASE_THRESHOLDS.get(metric)
            y_thr    = _apply_transform(base_thr, transform) if base_thr is not None else None

            # Pretty label for the Y axis
            tlbl = {
                'Identity'              : '{}',
                'Inverse (1/x)'         : '1 / {}',
                'Squared (x²)'          : '({})²',
                'Square root (√x)'      : '√({})',
                'Log10'                 : 'log\u2081\u2080({})',
                'Negative log (-log10)' : '−log\u2081\u2080({})',
            }[transform]
            y_label = tlbl.format(metric)

            points = []
            for a in arcs:
                base = _base_value(a, metric, hotspot_map)
                yv = _apply_transform(base, transform)
                for oi in _arc_partner_indices(a):
                    xv = oi + 1
                    prof_idx = orf_to_prof.get(oi, -1)
                    label = f"ORF{oi+1}" if prof_idx >= 0 else ""
                    points.append((oi, xv, yv, prof_idx, label))

            self._ppi_an_scatter.set_data_generic(
                points, profiles_palette,
                y_label=y_label,
                threshold=y_thr)

            # ── (2) Distribution ────────────────────────────────────────
            self._ppi_an_hist.set_data(
                [a.get('pae_min') for a in arcs], 'PAE_min',
                threshold=_PpiArcMapWidget._PAE_HIGH)

            # ── (3) ROC enrichment with user-selected positive set ──────
            pos_label = self._ppi_an_posset.currentText() or "(none)"
            curated = set()
            if pos_label == "(none)":
                pass  # empty
            elif pos_label == "(any HMM-annotated ORF)":
                for prof in hmm_p:
                    for hit in (prof.get('hits') or []):
                        oi = hit.get('orf_index')
                        if oi is not None:
                            curated.add(oi)
            else:
                # match a specific HMM profile name
                for prof in hmm_p:
                    if (prof.get('name', '') or '') == pos_label:
                        for hit in (prof.get('hits') or []):
                            oi = hit.get('orf_index')
                            if oi is not None:
                                curated.add(oi)
                        break

            ranked = sorted(arcs, key=lambda a: a.get('pae_min') or 99)
            ranked_ids = []
            for a in ranked:
                ob = a.get('orf_idx_b')
                oa = a.get('orf_idx_a')
                if ob in curated:    ranked_ids.append(ob)
                elif oa in curated:  ranked_ids.append(oa)
                else:                ranked_ids.append(ob if ob is not None else oa)
            self._ppi_an_roc.set_data(ranked_ids, curated, positive_label=pos_label)

            # ── (4) Correlative graph — arbitrary X = f(base) vs Y = ... ──
            x_transform_name = self._ppi_an_xtransform.currentText() \
                if hasattr(self, "_ppi_an_xtransform") else "Identity"
            x_metric_name    = self._ppi_an_xmetric.currentText() \
                if hasattr(self, "_ppi_an_xmetric") else "PAE_min"

            def _x_label_format(tname, base):
                fmt = {
                    "Identity":              "{}",
                    "Inverse (1/x)":         "1 / {}",
                    "Squared (x²)":          "({})²",
                    "Square root (√x)":      "√({})",
                    "Log10":                 "log\u2081\u2080({})",
                    "Negative log (-log10)": "−log\u2081\u2080({})",
                }[tname]
                return fmt.format(base)

            x_label = _x_label_format(x_transform_name, x_metric_name)
            # The Y label was already computed above as `y_label`
            pts2d = []
            self._ppi_an_2d_orfmap = []   # v29.11 — parallel ORF-index map
            for a in arcs:
                x_base_val = _base_value(a, x_metric_name, hotspot_map)
                xv_val     = _apply_transform(x_base_val, x_transform_name)
                y_base_val = _base_value(a, metric, hotspot_map)
                yv_val     = _apply_transform(y_base_val, transform)
                for oi in _arc_partner_indices(a):
                    prof_idx = orf_to_prof.get(oi, -1)
                    label = f"ORF{oi+1}" if prof_idx >= 0 else ""
                    pts2d.append((xv_val, yv_val, prof_idx, label))
                    self._ppi_an_2d_orfmap.append(int(oi))
            show_high_quadrant = (
                x_metric_name == "PAE_min" and metric == "cp_ipTM"
                and x_transform_name == "Identity" and transform == "Identity"
            )
            self._ppi_an_2d.set_data_generic(
                pts2d, profiles_palette,
                x_label=x_label, y_label=y_label,
                show_high_quadrant=show_high_quadrant)

            # (v29.9.3: Genomic density sub-tab removed — no update needed.)

            # ── (5) Domain × Domain heatmap ─────────────────────────────
            n = len(hmm_p)
            if n > 0:
                mat = [[0]*n for _ in range(n)]
                for a in arcs:
                    if (a.get('pae_min') or 99) >= _PpiArcMapWidget._PAE_HIGH:
                        continue
                    pa = orf_to_prof.get(a.get('orf_idx_a'))
                    pb = orf_to_prof.get(a.get('orf_idx_b'))
                    if pa is None or pb is None:
                        continue
                    mat[pa][pb] += 1
                    if pa != pb:
                        mat[pb][pa] += 1
                labels = [p.get('name', '') for p in hmm_p]
                self._ppi_an_heatmap.set_data(mat, labels)
            else:
                self._ppi_an_heatmap.set_data(None, [])

            n_high = sum(1 for a in arcs if (a.get('pae_min') or 99) < _PpiArcMapWidget._PAE_HIGH)
            self._ppi_an_status.setText(
                f"Refreshed: {len(arcs)} arcs · {n_high} HIGH · "
                f"|positive_set|={len(curated)} ('{pos_label}') · "
                f"{n} HMM profiles · "
                f"thresholds: HIGH<{_PpiArcMapWidget._PAE_HIGH:.1f}Å "
                f"MED<{_PpiArcMapWidget._PAE_MED:.1f}Å "
                f"cp_ipTM≥{_PpiArcMapWidget._CP_IPTM_FOCAL:.2f}")
        except Exception as e:
            self._ppi_an_status.setText(f"Refresh error: {e}")
            print(f"[ppigFinder] _ppi_analysis_refresh: {e}")
            import traceback
            traceback.print_exc()

    def _create_ppi_arc_map_tab(self):
        w = QWidget()
        self._ppi_map_tab_widget = w
        lay = QVBoxLayout(w)
        lay.setContentsMargins(2, 2, 2, 2)
        lay.setSpacing(2)

        # ── toolbar ─────────────────────────────────────────────────────
        tb = QHBoxLayout()
        tb.setSpacing(4)

        tb.addWidget(QLabel("Show:"))
        self._ppi_arc_filter_combo = QComboBox()
        self._ppi_arc_filter_combo.addItems([
            "All results",
            "HIGH only  (PAE_min < HIGH cutoff)",
            "HIGH + MED  (PAE_min < MED cutoff)",
            "Focal hits  (PAE_min < HIGH & cp_ipTM ≥ cutoff)",
        ])
        self._ppi_arc_filter_combo.setToolTip(
            "Filter which interaction arcs are drawn.\n"
            "HIGH = PAE_min < 4 Å (focal domain contact confirmed)\n"
            "MED  = PAE_min 4–8 Å (possible contact, check motifs)\n"
            "Focal = HIGH AND cp_ipTM ≥ 0.50 (strictest)")
        self._ppi_arc_filter_combo.currentIndexChanged.connect(
            self._ppi_arc_map_refresh)
        tb.addWidget(self._ppi_arc_filter_combo)

        tb.addWidget(QLabel("Color by:"))
        self._ppi_arc_color_combo = QComboBox()
        self._ppi_arc_color_combo.addItems(
            ["PAE_min ★", "ipTM", "Contact%"])
        self._ppi_arc_color_combo.setToolTip(
            "Metric used to determine arc colour:\n"
            "  PAE_min ★ — minimum inter-chain PAE (recommended)\n"
            "  ipTM      — global interface pTM score\n"
            "  cp_ipTM ★ — chain-pair ipTM (focal, from summary JSON)\n"
            "  Contact%  — fraction of residue pairs with PAE < 5 Å")
        self._ppi_arc_color_combo.currentIndexChanged.connect(
            self._ppi_arc_map_refresh)
        tb.addWidget(self._ppi_arc_color_combo)

        tb.addWidget(QLabel("Arc height:"))
        self._ppi_arc_height_combo = QComboBox()
        self._ppi_arc_height_combo.addItems(
            ["By genomic distance", "By score (better = lower)", "Fixed"])
        self._ppi_arc_height_combo.setToolTip(
            "How arc height is determined:\n"
            "  By genomic distance — neighboring ORFs get low arcs,\n"
            "    distant ORFs get tall arcs (like published operon figures)\n"
            "  By score — high-confidence interactions drawn lower/closer\n"
            "  Fixed — all arcs same height")
        self._ppi_arc_height_combo.currentIndexChanged.connect(
            self._ppi_arc_map_refresh)
        tb.addWidget(self._ppi_arc_height_combo)

        btn_refresh = QPushButton("⟳ Refresh")
        btn_refresh.setToolTip("Rebuild the arc map from current AF3 results")
        btn_refresh.clicked.connect(self._ppi_arc_map_refresh)
        btn_refresh.setStyleSheet(
            "QPushButton{background:#2e7d32;color:white;font-weight:bold;"
            "border-radius:4px;padding:2px 8px;}"
            "QPushButton:hover{background:#388e3c;}")
        tb.addWidget(btn_refresh)

        btn_svg = QPushButton("↓ Export SVG")
        btn_svg.setToolTip("Export the arc map as a scalable vector SVG file")
        btn_svg.clicked.connect(self._ppi_arc_map_export_svg)
        tb.addWidget(btn_svg)

        btn_tsv = QPushButton("↓ Export TSV")
        btn_tsv.setToolTip("Export the displayed interactions as a TSV table")
        btn_tsv.clicked.connect(self._ppi_arc_map_export_tsv)
        tb.addWidget(btn_tsv)

        tb.addStretch()
        self._ppi_arc_count_lbl = QLabel("0 interactions")
        self._ppi_arc_count_lbl.setStyleSheet(
            "font-weight:500;color:#1D9E75;")
        tb.addWidget(self._ppi_arc_count_lbl)

        lay.addLayout(tb)

        tb2 = QHBoxLayout()
        tb2.setSpacing(6)
        self._ppi_arc_cb_labels = QCheckBox("Show labels")
        self._ppi_arc_cb_labels.setChecked(True)
        self._ppi_arc_cb_labels.setToolTip(
            "Show or hide the numeric PAE_min labels at each arc apex.")
        self._ppi_arc_cb_labels.toggled.connect(self._ppi_arc_set_labels)
        tb2.addWidget(self._ppi_arc_cb_labels)

        self._ppi_arc_cb_bidir = QCheckBox("Bidirectional arcs")
        self._ppi_arc_cb_bidir.setChecked(True)
        self._ppi_arc_cb_bidir.setToolTip(
            "Draw HIGH and MEDIUM arcs above the genome and LOW arcs below.")
        self._ppi_arc_cb_bidir.toggled.connect(self._ppi_arc_set_bidir)
        tb2.addWidget(self._ppi_arc_cb_bidir)

        tb2.addWidget(QLabel("Label top-N:"))
        self._ppi_arc_topn = QSpinBox()
        self._ppi_arc_topn.setRange(0, 500)
        self._ppi_arc_topn.setValue(0)
        self._ppi_arc_topn.setSpecialValueText("all")
        self._ppi_arc_topn.setToolTip(
            "Label only the N strongest interactions by PAE_min (0 = label all).")
        self._ppi_arc_topn.valueChanged.connect(self._ppi_arc_set_topn)
        tb2.addWidget(self._ppi_arc_topn)

        # ── v29.9 user-configurable PAE / cp_ipTM thresholds ─────────────
        tb2.addSpacing(20)
        tb2.addWidget(QLabel("HIGH <"))
        self._ppi_thr_high = QDoubleSpinBox()
        self._ppi_thr_high.setDecimals(1)
        self._ppi_thr_high.setRange(0.1, 30.0)
        self._ppi_thr_high.setSingleStep(0.5)
        self._ppi_thr_high.setValue(3.0)
        self._ppi_thr_high.setSuffix(" Å")
        self._ppi_thr_high.setToolTip(
            "PAE_min cutoff for HIGH-confidence interactions.\n"
            "Default 3.0 Å (canonical AlphaFold value is 4.0 Å).\n"
            "Changes apply to the arc colouring, the Show filter,\n"
            "and to every analytical view in PPI Analysis.")
        self._ppi_thr_high.valueChanged.connect(self._ppi_thresholds_changed)
        tb2.addWidget(self._ppi_thr_high)

        tb2.addWidget(QLabel("MED <"))
        self._ppi_thr_med = QDoubleSpinBox()
        self._ppi_thr_med.setDecimals(1)
        self._ppi_thr_med.setRange(0.2, 50.0)
        self._ppi_thr_med.setSingleStep(0.5)
        self._ppi_thr_med.setValue(8.0)
        self._ppi_thr_med.setSuffix(" Å")
        self._ppi_thr_med.setToolTip(
            "PAE_min cutoff for MEDIUM-confidence interactions.\n"
            "Must be greater than the HIGH cutoff. Default 8.0 Å.")
        self._ppi_thr_med.valueChanged.connect(self._ppi_thresholds_changed)
        tb2.addWidget(self._ppi_thr_med)

        tb2.addWidget(QLabel("ipTM ≥"))
        self._ppi_thr_cpip = QDoubleSpinBox()
        self._ppi_thr_cpip.setDecimals(2)
        self._ppi_thr_cpip.setRange(0.00, 1.00)
        self._ppi_thr_cpip.setSingleStep(0.05)
        self._ppi_thr_cpip.setValue(0.50)
        self._ppi_thr_cpip.setToolTip(
            "Minimum interface predicted TM-score (ipTM) for the 'Focal hits'\n"
            "filter (Show menu). Default 0.50.")
        self._ppi_thr_cpip.valueChanged.connect(self._ppi_thresholds_changed)
        tb2.addWidget(self._ppi_thr_cpip)
        tb2.addStretch()
        lay.addLayout(tb2)

        # ── info label (shows hovered/clicked arc) ───────────────────────
        self._ppi_arc_info_lbl = QLabel(
            "Click an arc to see interaction details  |  "
            "Click an ORF to center genome map  |  "
            "Scroll = zoom  ·  Drag = pan")
        self._ppi_arc_info_lbl.setStyleSheet(
            "font-size:11px; color:#085041; background:#E1F5EE;"
            "padding:3px 7px; border-bottom:1px solid #9FE1CB;")
        self._ppi_arc_info_lbl.setWordWrap(True)
        lay.addWidget(self._ppi_arc_info_lbl)

        # ── arc map canvas ────────────────────────────────────────────────
        self._ppi_arc_widget = _PpiArcMapWidget(self)
        self._ppi_arc_widget.arc_clicked.connect(self._ppi_arc_on_click)
        self._ppi_arc_widget.orf_clicked.connect(self._ppi_arc_on_orf_click)
        self._ppi_arc_widget.arc_hovered.connect(self._ppi_arc_on_hover)
        lay.addWidget(self._ppi_arc_widget, stretch=1)

        # ── legend ────────────────────────────────────────────────────────
        leg = QHBoxLayout()
        leg.setSpacing(12)

        def _leg_line(color, dash=False):
            lbl = QLabel()
            lbl.setFixedSize(32, 12)
            lbl.setStyleSheet(
                f"border-top: {'3px solid' if not dash else '2px dashed'} {color};"
                f"margin-top:5px;")
            return lbl

        def _leg_rect(color, border):
            lbl = QLabel()
            lbl.setFixedSize(14, 10)
            lbl.setStyleSheet(
                f"background:{color};border:1px solid {border};"
                f"border-radius:2px;margin-top:1px;")
            return lbl

        for widget, text in [
            (_leg_line("#1D9E75"),          "PAE_min < 4 Å (HIGH)"),
            (_leg_line("#BA7517", dash=True),"PAE_min 4–8 Å (MED)"),
            (_leg_line("#E24B4A", dash=True),"PAE_min > 8 Å (LOW)"),
            (_leg_rect("#9FE1CB","#0F6E56"), "HMM hit ORF"),
            (_leg_rect("#FAC775","#BA7517"), "Custom / other"),
            (_leg_rect("#D3D1C7","#888780"), "No annotation"),
        ]:
            row = QHBoxLayout()
            row.setSpacing(4)
            row.addWidget(widget)
            row.addWidget(QLabel(text))
            leg.addLayout(row)
        leg.addStretch()

        leg_widget = QWidget()
        leg_widget.setLayout(leg)
        leg_widget.setStyleSheet(
            "background:var(--color-background-secondary);"
            "border-top:0.5px solid #ddd;padding:3px 0;")
        lay.addWidget(leg_widget)

        self._tabs.addTab(w, "🧬 Genomic PPI Map")
        # v29.9.1: refresh the legend right after creation
        try:
            self._ppi_arc_update_legend()
        except Exception:
            pass

    def _ppi_arc_map_refresh(self):
        """Rebuild arc data from _af3_analysis_results and repaint."""
        results = getattr(self, '_af3_analysis_results', [])
        orfs    = getattr(self, 'orfs', [])

        filter_idx = self._ppi_arc_filter_combo.currentIndex()
        color_by   = self._ppi_arc_color_combo.currentText()
        height_by  = self._ppi_arc_height_combo.currentText()

        arcs = []
        for res in results:
            names = res.get('orf_names', [])
            if len(names) < 2:
                continue
            pae_min  = res.get('pae_min_inter')
            cp_iptm  = res.get('cp_iptm_inter')
            iptm     = res.get('iptm') or 0
            cfrac    = res.get('contact_frac') or 0

            # Apply filter — uses user-set thresholds (v29.9)
            _hi = _PpiArcMapWidget._PAE_HIGH
            _md = _PpiArcMapWidget._PAE_MED
            _cp = _PpiArcMapWidget._CP_IPTM_FOCAL
            if filter_idx == 1 and (pae_min is None or pae_min >= _hi):
                continue
            if filter_idx == 2 and (pae_min is None or pae_min >= _md):
                continue
            # v29.14: 'Focal hits' now uses the global ipTM instead of
            # cp_ipTM (numerically identical for two-chain complexes).
            if filter_idx == 3 and (pae_min is None or pae_min >= _hi
                                    or (iptm is not None and iptm < _cp)):
                continue

            # Resolve ORF positions — extract numeric index from name "ORF1234"
            def _find_orf(name, _orfs=orfs):
                # Primary: exact "ORF{n}" match
                if name.upper().startswith('ORF'):
                    try:
                        idx = int(name[3:]) - 1
                        if 0 <= idx < len(_orfs):
                            return idx, _orfs[idx]
                    except (ValueError, TypeError):
                        pass
                # Secondary: any digit run in the name
                try:
                    import re as _re
                    nums = _re.findall(r'\d+', name)
                    if nums:
                        idx = int(nums[-1]) - 1
                        if 0 <= idx < len(_orfs):
                            return idx, _orfs[idx]
                except (ValueError, TypeError):
                    pass
                return -1, None

            i_a, o_a = _find_orf(names[0])
            i_b, o_b = _find_orf(names[1])
            if o_a is None or o_b is None:
                continue

            # Score for colour
            if color_by.startswith("PAE_min"):
                score = pae_min
                score_inv = True   # lower = better = greener
            elif color_by.startswith("Contact"):
                score = cfrac * 100
                score_inv = False
            else:
                score = iptm
                score_inv = False

            arcs.append({
                'name_a':   names[0],
                'name_b':   names[1],
                'orf_idx_a': i_a,
                'orf_idx_b': i_b,
                'start_a':  o_a['start'],
                'end_a':    o_a['end'],
                'start_b':  o_b['start'],
                'end_b':    o_b['end'],
                'pae_min':  pae_min,
                'iptm':     iptm,
                'cp_iptm':  cp_iptm,
                # v29.14 FIX: carry hotspot metrics on the arc itself.  The
                # PPI Analysis lookup used to key a side map by
                # 'orf_a_index'/'orf_b_index', which the analysis-result dict
                # NEVER defines (it stores 'orf_names' / 'chain_to_orf').  The
                # map was therefore always empty and every HotSpotPAE query
                # fell through to the PAE_min fallback, making the HotSpotPAE
                # and PAE_min plots byte-identical.
                'hotspot_pae':   (res.get('hotspot') or {}).get('hotspot_mean_pae'),
                'hotspot_score': (res.get('hotspot') or {}).get('hotspot_score'),
                'contact_frac': cfrac,
                'score':    score,
                'score_inv': score_inv,
                'job_name': res.get('job_name', ''),
                'contact_region': res.get('contact_region', ''),
                'height_mode': height_by,
            })

        self._ppi_arc_widget.set_data(
            dna_length=len(getattr(self, 'dna_sequence', '') or ''),
            orfs=orfs,
            hmm_profiles=getattr(self, 'hmm_profiles', []),
            arcs=arcs,
        )
        self._ppi_arc_count_lbl.setText(
            f"{len(arcs)} interaction{'s' if len(arcs) != 1 else ''}")

    def _ppi_arc_on_click(self, arc_idx: int):
        """User clicked an arc — show details in info label."""
        arcs = self._ppi_arc_widget._arcs
        if not (0 <= arc_idx < len(arcs)):
            return
        a = arcs[arc_idx]
        pmin = f"{a['pae_min']:.2f} Å" if a['pae_min'] is not None else "—"
        cfrc = f"{a['contact_frac']*100:.1f}%" if a['contact_frac'] is not None else "—"
        conf = ("HIGH ★" if a['pae_min'] is not None and a['pae_min'] < 4.0 else
                "MED"    if a['pae_min'] is not None and a['pae_min'] < 8.0 else "LOW")
        self._ppi_arc_info_lbl.setText(
            f"▶  {a['name_a']} ↔ {a['name_b']}   "
            f"ipTM={a['iptm']:.3f}  PAE_min={pmin}  "
            f"Contact%={cfrc}  [{conf}]   "
            f"Contact zone: {a['contact_region'] or '—'}")
        # Also select in Interaction Results table
        for row in range(self._af3a_table.rowCount()):
            item = self._af3a_table.item(row, 0)
            if item and a['job_name'] in item.text():
                self._af3a_table.selectRow(row)
                break

    def _ppi_arc_on_orf_click(self, orf_idx: int):
        """User clicked an ORF node — center main genome map."""
        self._select_and_center_orf(orf_idx)

    def _ppi_arc_on_hover(self, arc_idx: int):
        """User hovered an arc — show lightweight tooltip in info label."""
        arcs = self._ppi_arc_widget._arcs
        if arc_idx < 0 or arc_idx >= len(arcs):
            self._ppi_arc_info_lbl.setText(
                "Click an arc to see interaction details  |  "
                "Click an ORF to center genome map  |  "
                "Scroll = zoom  ·  Drag = pan")
            return
        a = arcs[arc_idx]
        pmin = f"{a['pae_min']:.2f}" if a['pae_min'] is not None else "—"
        self._ppi_arc_info_lbl.setText(
            f"  {a['name_a']} ↔ {a['name_b']}  "
            f"PAE_min={pmin} Å  ipTM={a['iptm']:.2f}  "
            f"— click to select")

    def _ppi_arc_map_export_svg(self):
        """Export the arc map as SVG using QSvgGenerator."""
        try:
            from PyQt6.QtSvg import QSvgGenerator
        except ImportError:
            try:
                from PyQt5.QtSvg import QSvgGenerator
            except ImportError:
                QMessageBox.warning(self, "SVG Export",
                    "PyQt SVG module not available. Install PyQt6-Qt6 or PyQt5-sip.")
                return
        path, _ = QFileDialog.getSaveFileName(
            self, "Export PPI Arc Map as SVG", "", "SVG (*.svg)")
        if not path:
            return
        gen = QSvgGenerator()
        gen.setFileName(path)
        gen.setSize(self._ppi_arc_widget.size())
        painter = QPainter(gen)
        self._ppi_arc_widget.render(painter)
        painter.end()
        self._status.showMessage(f"✓ PPI arc map exported: {path}")

    def _ppi_arc_map_export_tsv(self):
        """Export displayed arcs as a TSV file."""
        arcs = self._ppi_arc_widget._arcs
        if not arcs:
            QMessageBox.information(self, "Export TSV",
                "No interactions to export. Click Refresh first.")
            return
        path, _ = QFileDialog.getSaveFileName(
            self, "Export PPI Map interactions as TSV", "", "TSV (*.tsv *.txt)")
        if not path:
            return
        headers = ["orf_a", "orf_b", "iptm", "pae_min_inter",
                   "contact_frac_pct", "contact_region", "job_name"]
        rows = []
        for a in arcs:
            rows.append([
                a['name_a'], a['name_b'],
                f"{a['iptm']:.3f}" if a['iptm'] else "",
                f"{a['pae_min']:.3f}" if a['pae_min'] is not None else "",
                f"{a['contact_frac']*100:.1f}" if a['contact_frac'] is not None else "",
                a.get('contact_region', ''),
                a.get('job_name', ''),
            ])
        try:
            with open(path, 'w', encoding='utf-8') as f:
                f.write('\t'.join(headers) + '\n')
                for r in rows:
                    f.write('\t'.join(r) + '\n')
            self._status.showMessage(f"✓ {len(rows)} interactions exported: {path}")
        except OSError as e:
            QMessageBox.warning(self, "Export TSV", str(e))

    def _create_hpc_server_tab(self):
        """Build the generic HPC Server tab with 4 sub-tabs:
        Connect | Submit | Monitor | Results."""
        w = QWidget()
        root = QVBoxLayout(w)
        root.setContentsMargins(4, 4, 4, 4)
        root.setSpacing(4)

        # Paramiko availability banner
        if not PARAMIKO_AVAILABLE:
            warn = QLabel(
                "⚠  paramiko not installed — SSH features disabled.\n"
                "   Install with:  pip install paramiko")
            warn.setStyleSheet(
                "background:#FFF3CD;color:#856404;padding:6px 10px;"
                "border-radius:4px;font-size:11px;")
            root.addWidget(warn)

        # Connection status bar (always visible)
        top_bar = QHBoxLayout()
        self._dv_status_icon = QLabel("⬤")
        self._dv_status_icon.setStyleSheet("color:#bbb;font-size:14px;")
        top_bar.addWidget(self._dv_status_icon)
        self._dv_status_lbl = QLabel("Not connected")
        self._dv_status_lbl.setStyleSheet("font-size:11px;color:#666;")
        top_bar.addWidget(self._dv_status_lbl)
        top_bar.addStretch()
        self._dv_disconnect_btn = QPushButton("Disconnect")
        self._dv_disconnect_btn.setEnabled(False)
        self._dv_disconnect_btn.clicked.connect(self._hpc_disconnect)
        self._dv_disconnect_btn.setFixedHeight(24)
        top_bar.addWidget(self._dv_disconnect_btn)
        root.addLayout(top_bar)

        # Sub-tabs (DetachableTabWidget — right-click or double-click
        # a tab to open it in its own resizable window)
        self._dv_tabs = DetachableTabWidget()
        self._dv_tabs.setTabPosition(QTabWidget.TabPosition.North
                                      if QT_VERSION == 6
                                      else QTabWidget.North)
        self._dv_tabs.setToolTip(
            "Tip: right-click any sub-tab (or double-click it) to open "
            "it in a separate window for more room.")
        root.addWidget(self._dv_tabs)

        self._dv_build_connect_tab()
        self._dv_build_submit_tab()
        self._dv_build_monitor_tab()
        self._dv_build_results_tab()

        self._tabs.addTab(w, "🖥 Submit AF3 via Server")

